// 人情世故指南 640 条精简索引
// 由 tools/sync_social.js 生成，请勿手工编辑
// 来源：changxueyi/renqing-shigu · book/*.md · CC BY 4.0
module.exports = [{"id":"rq01-1","b":"social","s":1,"n":1,"t":"先分清对方在你的哪一圈，再决定用哪套规矩","p":"家人、老朋友、同事、普通熟人、陌生人，期待和规矩都不一样。对家人讲究不计较，对同事讲究公私分明，对陌生人讲究规则和契约。很多委屈来自用错了圈：把同事当家人掏心掏肺，或者对家人锱铢必较。遇事先问一句：这个人离我多近？这件事该按哪一圈的规矩来？","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-2","b":"social","s":1,"n":2,"t":"分清「脸」和「面子」：前者是人品，后者是体面","p":"「不要脸」说的是人品有问题，丢的是做人的底线；「没面子」说的是在人前不够体面，丢的是地位和排场。前者丢了很难找回，后者丢一点无妨。所以宁可在排场上让步，也别在诚信上打折。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-3","b":"social","s":1,"n":3,"t":"人情是长期往来的账，不是一锤子买卖","p":"中国式人情讲究有来有往，但不讲究当场两清。别人帮你一次，你不必马上还一个等价的，可以在对方需要时还；正因为一直「欠着一点」，关系才持续。反过来，和不想深交的人，最好尽快两清，不欠也不让对方欠。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-4","b":"social","s":1,"n":4,"t":"给面子可以，拿原则换面子不行","p":"照顾对方感受、给对方台阶、不当众让人难堪，这些是给面子；替人违规办事、帮人作假、为人担保自己承担不了的风险，这些是拿原则换面子。前者花的是你的姿态，后者花的是你的前途。","tip":"「这个忙按规定我真帮不了，换个我能做的，你看行不行？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq01-5","b":"social","s":1,"n":5,"t":"关系能办的，通常是合规范围内的「快、顺、少走弯路」","p":"找熟人办事，正常的收益是：知道该找哪个窗口、要准备什么材料、哪一步容易卡、什么时候去人少。真正违规的事，比如让不合格变合格、插队拿不该拿的名额，关系办不了，硬办就是在找麻烦。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-6","b":"social","s":1,"n":6,"t":"熟人社会讲人情，陌生人社会讲规则，城市里两套都要会","p":"老家、小单位、熟人圈里，很多事靠一句话、一个面子就办了；在城市和陌生人打交道，靠的是合同、发票、转账记录和明码标价。把熟人那套搬到陌生人身上，容易吃亏；把陌生人那套搬到亲人身上，又显得生分。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq01-7","b":"social","s":1,"n":7,"t":"体面的核心是给对方留台阶","p":"人最难受的不是被拒绝、被纠正，而是在人前下不来台。提意见私下说，指出错误先肯定对方的出发点，拒绝时给一个对方能接受的理由。你给别人留的台阶，往往就是将来别人给你留的路。","tip":"「你这个思路我理解，可能是我没说清楚，我们再对一下细节。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"体面","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-8","b":"social","s":1,"n":8,"t":"别人先帮了你，你会想还——这种心理也会被人利用","p":"受了别人的恩惠想回报，是人之常情，也是人情社会运转的基础。但推销员先送小礼品、陌生人先请你吃饭、刚认识的人先帮你一个小忙，再提出一个大要求，利用的正是这种「不还不好意思」。判断标准：对方给的东西你没要过，回报的要求却远大于所得。","tip":"「谢谢你的好意，这个我不能收，事情我们按正常流程来。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-9","b":"social","s":1,"n":9,"t":"先接住情绪，再讲道理","p":"一个人带着火气来找你，这时候讲道理多半没用，他听到的只是「你在反驳我」。先承认他的感受（不等于承认他对），等情绪落下来，再谈事情本身。家里吵架、客户投诉、同事抱怨，都是这个顺序。","tip":"「换我遇到这种事也会着急。你先说说具体是哪一步出的问题？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-10","b":"social","s":1,"n":10,"t":"维护关系要花时间，所以关系要有排序","p":"一个人真正能经常联系、彼此了解的人数是有限的，时间和精力撒得太开，每段关系都只能维持表面。把精力优先给家人、几位知心朋友和工作上关键的人，其余的保持礼貌、逢年过节问候即可。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-11","b":"social","s":1,"n":11,"t":"别小看「弱关系」：新机会常常来自不太熟的人","p":"亲密朋友和你的圈子高度重合，知道的消息你多半也知道；反而是前同事、校友、行业里见过几面的人，能带来你圈子之外的工作机会和信息。维护弱关系不用费多大力：对方发了好消息时真诚祝贺，对方问到你熟悉的事时热心回答。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":"新人,异乡"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-12","b":"social","s":1,"n":12,"t":"人们普遍低估别人愿意帮忙的程度，该开口就开口","p":"很多人不敢求助，是怕被拒绝、怕麻烦别人。实验显示，人们会明显低估陌生人答应帮忙的比例。对熟人提一个具体、合理、对方力所能及的请求，大多数时候对方是愿意的，而且帮完之后关系往往更近。","tip":"「想请教你一件事，大概占用你十分钟，你看什么时候方便？」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"学生,新人"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq01-13","b":"social","s":1,"n":13,"t":"说到做到，是最值钱的人情资本","p":"别人愿不愿意信任你，主要看三件事：你有没有能力做到、是不是真心为对方着想、说的话算不算数。前两样一时看不出来，第三样很快就会被记住。做不到的事宁可当时不答应，也别答应了再拖。","tip":"「这件事我能保证做到哪一步，后面那部分我不确定，先不跟你打包票。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq01-14","b":"social","s":1,"n":14,"t":"公私分明，是现代人情世故的地基","p":"私人感情好，不等于工作上可以放水；工作上严格，也不代表私下不讲情。公家的钱、单位的资源、手里的审批权，不能拿来做私人人情。把这条守住，你的人情才干净，别人求你时你也好拒绝。","tip":"「咱俩关系归关系，这个流程我得按规定走，你理解一下。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"新人,体制内,管理"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq01-15","b":"social","s":1,"n":15,"t":"客气话和真心话分开听，别把客气当承诺","p":"「改天请你吃饭」「有空来家里坐」「有事尽管找我」，很多时候是表达善意的客气话，不是具体邀约。判断是不是真心：有没有具体时间、地点，对方会不会主动跟进。客气话回以客气话即可，真要约，就由你提出一个具体时间。","tip":"「好啊，那下周四晚上你方便吗？」（想推进时）／「好嘞，有机会一定。」（不想推进时）","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-16","b":"social","s":1,"n":16,"t":"关键时刻看人品，日常相处看分寸","p":"平时谁都可以客客气气，真正看清一个人，要看三种时候：利益冲突时他怎么分，你落难时他怎么待你，他能不能守住你告诉他的秘密。交心之前先观察一段时间，比被骗之后再反省划算得多。","tip":"","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-17","b":"social","s":1,"n":17,"t":"知世故而不世故：懂规矩，但别让规矩把你变成另一个人","p":"懂人情世故，是为了少碰壁、少伤人、少被坑；不是为了学会油滑、两面三刀、见人下菜碟。会看场合说话是本事，说违心的假话骗人就是另一回事。看懂了套路，可以选择不用。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-18","b":"social","s":1,"n":18,"t":"人情投入要算账：你的时间、钱和情绪都有限","p":"每一次随礼、每一顿饭、每一次帮忙都有成本。一年下来算一算：随礼花了多少、应酬占了多少个晚上、哪些投入换回了真正的关系。对长期没有回应、只有在需要你时才出现的关系，可以逐渐减少投入。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-19","b":"social","s":1,"n":19,"t":"不想混的圈子，可以不混","p":"有些饭局只有喝酒和吹牛，有些群只有攀比和八卦，有些关系让你每次相处完都很累。人情世故不是要求你和所有人搞好关系，而是在必须相处的人那里不失礼，在不必相处的人那里礼貌地保持距离。","tip":"「最近手头事多，这次我就不去了，你们玩得开心。」","cost":{"money":"0","time":"少","will":"是","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-20","b":"social","s":1,"n":20,"t":"道理讲赢了，事情可能办输了","p":"和家人、同事、客户争论时，先想清楚目的是什么：是把事办成，还是证明自己对？当众把对方驳倒，对方可能从此不再配合你。多数时候，对的结果比说对的话更重要。","tip":"「我们先不争谁对，看看怎么做能把这件事办成。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-21","b":"social","s":1,"n":21,"t":"别人跟你说难处时，先问「需要我做什么」，别急着给建议","p":"有人跟你倒苦水，有时要的是办法，有时只是想被听见。不分情况地给建议，对方会觉得你没在听。先问一句，再决定是陪着听，还是帮着想办法。","tip":"「你是想让我帮你出出主意，还是想先吐吐槽？我都在。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq01-22","b":"social","s":1,"n":22,"t":"人情世故的三条底线：不违法、不害人、不过度委屈自己","p":"所有的「会做人」，都要在这三条线以内。违法的事，人情再大也不做；坑别人的事，利益再大也不做；长期让自己憋屈、透支、生病的「懂事」，也不必做。底线清楚了，很多纠结就有了答案。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-1","b":"social","s":2,"n":1,"t":"「再说吧」「我考虑考虑」「回头看看」，多数时候是委婉的拒绝","p":"中国人不习惯直接说「不」，常用模糊的话把拒绝包起来。对方说「再说吧」又没有给具体时间，基本可以理解为暂时不行。不要追着问「那到底行不行」，让对方为难；真想推进，换个方式或过一段时间再提。","tip":"「好的，那您先忙，有需要随时找我。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-2","b":"social","s":2,"n":2,"t":"领导说「你看着办」，通常要的是「按我心里的想法办好」","p":"「你看着办」有两种：一种是真的授权，一种是对方没想清楚或懒得说。稳妥的做法是给出你打算怎么办的简短方案，请对方点头，尤其是涉及花钱、对外表态、得罪人的事。","tip":"「那我打算这样处理：……您看可以吗？没问题我就按这个办。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-3","b":"social","s":2,"n":3,"t":"夸人要具体，空泛的夸奖听起来像客套","p":"「你真厉害」「做得很好」说多了没有分量。具体说出好在哪里：「你这个表格把三个月的数据放在一页上，领导一眼就看明白了」。具体的夸奖让人觉得你真的看见了他的付出。","tip":"「你刚才那个比方特别好，客户一下就听懂了。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-4","b":"social","s":2,"n":4,"t":"批评对事不对人，并且私下说","p":"「你怎么老是这么粗心」是在评价一个人，对方只会防御；「这份报告的第三页数字和附表对不上」是在说一件事，对方可以改。批评尽量私下、具体、给出改进方向；公开场合只讲事实，不讲态度。","tip":"「这次的问题主要在核对环节，下次发出去前我们一起过一遍，好吗？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"体面","who":"管理"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-5","b":"social","s":2,"n":5,"t":"别在公开场合问收入、婚育、体重这类私事","p":"「一个月挣多少」「怎么还不结婚」「是不是又胖了」，在长辈那里可能是关心，在对方那里往往是压力。熟人之间话题可以深一点，但最好由对方先打开；在饭局、群聊、有外人的场合，一律不问。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq02-6","b":"social","s":2,"n":6,"t":"被问到不想答的问题，可以笑着绕开，不必撒谎","p":"不想回答收入、感情、工作调动这类问题时，有三种体面的办法：给一个模糊的范围，把问题抛回去，或者直接转移话题。都不需要编造事实。","tip":"「够花，饿不着。您最近身体怎么样？」／「还在看机会，定了第一时间告诉您。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-7","b":"social","s":2,"n":7,"t":"求人时先说清楚对方能得到什么，或者至少别让对方吃亏","p":"别人帮你，要付出时间、精力，有时还有风险。开口时把事情说完整（要做什么、多久、截止时间），并说明你会怎么减少对方的麻烦，比单纯说「拜托拜托」管用。","tip":"「材料我都整理好了，你只要帮忙看一下第二部分，十分钟就够。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq02-8","b":"social","s":2,"n":8,"t":"不知道怎么回答时，「我确认一下再回复您」是最安全的一句话","p":"被领导、客户、长辈当场问住，最容易犯的错是硬答、乱承诺。说一句「我确认一下」，既不显得无能，又给自己留了查证的时间。关键是之后真的回复，并且尽快。","tip":"「这个数据我想再核对一下，今天下班前回复您。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-9","b":"social","s":2,"n":9,"t":"道歉要说清三件事：错在哪、谁负责、怎么补","p":"「不好意思啊」「我也不是故意的」不算道歉。有效的道歉包括：承认具体做错了什么、承认是自己的责任、提出补救办法。其中「承认责任」和「提出补救」最关键，解释原因可以有，但不要变成找借口。","tip":"「是我没核对清楚，导致你白跑一趟。我已经改好了，明天我直接给你送过去。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-10","b":"social","s":2,"n":10,"t":"别用「我是为你好」开头","p":"「我是为你好」「我这是关心你」听起来像在提前堵住对方反驳的嘴，常常让人更抵触。直接说你观察到的事实和你的担心，把决定权留给对方。","tip":"「我看你最近总加班到很晚，有点担心你身体，要不要我帮你分担点？」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-11","b":"social","s":2,"n":11,"t":"当着第三个人的面，不揭人短、不翻旧账","p":"两个人之间能说的玩笑、能提的旧事，当着外人说出来，性质就变了。在饭局上提朋友的糗事、在会议上提同事上次的失误、在亲戚面前提伴侣的缺点，对方会觉得被出卖。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-12","b":"social","s":2,"n":12,"t":"开玩笑看对象：拿自己开涮安全，拿别人开涮危险","p":"外貌、身材、家庭、学历、地域、性别这些话题，开玩笑最容易伤人，哪怕你觉得「只是开玩笑」。自嘲最安全；拿别人开玩笑，前提是你们很熟、对方之前也这样开过你、并且旁边没有外人。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq02-13","b":"social","s":2,"n":13,"t":"提反对意见，先复述对方的观点，再说你的顾虑","p":"直接说「我不同意」，对方第一反应是防御。先把对方的意思复述一遍，证明你听懂了，再用「我担心的是……」引出你的顾虑，最后给一个替代方案。这样对方感受到的是讨论，而不是反驳。","tip":"「我理解您是想先上线再优化，这样能抢时间。我担心的是支付那块没测完，万一出问题影响大。能不能先上其他模块，支付晚两天？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"新人,管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq02-14","b":"social","s":2,"n":14,"t":"听懂长辈的「随便」：通常是「你看着安排，但别太差」","p":"问长辈「想吃什么」「要什么礼物」，回答常常是「随便」「不用买」。这不等于真的什么都行，而是不想给你添麻烦。可以给两三个选项让对方挑，比让对方从零开始想更容易得到真实答案。","tip":"「那我订那家粤菜或者那家本帮菜，您更想吃哪个？」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-15","b":"social","s":2,"n":15,"t":"少用绝对化的词：「永远」「从来」「肯定」","p":"「你从来不做家务」「你永远都迟到」，一个反例就能把你的话推翻，对方的注意力会从问题转到反驳上。说具体的事和具体的次数，更有说服力，也更不伤人。","tip":"「这周三次约好的时间你都晚了半小时，我有点着急。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-16","b":"social","s":2,"n":16,"t":"别抢话、别补全别人的句子","p":"对方话还没说完，你就接上「我知道，你是想说……」，哪怕你猜对了，对方也会觉得不被尊重。尤其和长辈、领导、客户说话，等对方说完再开口，停顿一下再回应，显得你在认真听。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-17","b":"social","s":2,"n":17,"t":"传话时只传事实，不传语气和评价","p":"帮人转达意见，最容易惹祸的是把别人的不满、抱怨连同自己的理解一起传过去。只转述对方要求的事情本身，评价和情绪一律不传；不确定原话时，请当事人直接沟通。","tip":"「王总让我转告，方案周五前要定稿。具体修改意见他说会单独发给你。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-18","b":"social","s":2,"n":18,"t":"当面不说、背后说，是关系最大的杀手","p":"你在背后说的话，迟早会以更难听的版本传到当事人耳朵里。对一个人有意见，要么当面委婉地说，要么不说。在第三人面前评价别人，说好话可以，说坏话不要。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-19","b":"social","s":2,"n":19,"t":"别人诉苦时少说「这有什么」「谁不是这样」","p":"「这算什么，我比你惨多了」「大家都这样，忍忍就过去了」，本意可能是安慰，听起来却是否定对方的感受。先承认这件事对他来说确实难，再看能不能帮上忙。","tip":"「这事搁谁身上都难受，你已经扛得很不错了。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-20","b":"social","s":2,"n":20,"t":"拿不准称呼、说法时，宁可正式一点","p":"第一次接触的人、年龄或职位比你高的人、书面沟通的场合，用「您」、用全称、用正式说法；对方先放松了，你再跟着放松。从正式到随意很容易，从随意再拉回正式就尴尬了。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq02-21","b":"social","s":2,"n":21,"t":"「你误会了」比「你听错了」更好接受","p":"出现误会时，把原因归到自己的表达上，比归到对方的理解上更容易化解。「是我没说清楚」并不等于认输，而是给双方一个体面的台阶，然后把事实重新讲一遍。","tip":"「可能是我刚才没说清楚，我的意思是……」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq02-22","b":"social","s":2,"n":22,"t":"说「不」之前先说「是」：认可对方的需求，再说做不到的部分","p":"直接说「不行」容易让人觉得被冷冷地挡回去。先认可对方的需求合理，再说明限制，最后给出你能做到的部分，拒绝就变成了「部分答应」。更多拒绝的方法见第 4 章。","tip":"「你想周末前拿到我理解，这周我实在排不开，周一上午可以吗？」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq03-1","b":"social","s":3,"n":1,"t":"拿不准职务时，按名片、介绍人或旁人的叫法来","p":"第一次见面不知道怎么称呼，最稳妥的依据有三个：对方递的名片、介绍人怎么介绍、在场其他人怎么叫他。实在没有依据，就用「X 老师」「X 总」这类通用尊称，比直接叫名字或叫错职务好。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-2","b":"social","s":3,"n":2,"t":"副职当面多称正职，正式场合和书面材料写准确","p":"当面称呼副职时，很多单位习惯省掉「副」字，叫「王局」「李总」。但在正式介绍、会议主持、公文和名单里，职务要写全写准，否则会让正职尴尬，也会被认为不懂规矩。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":"新人,体制内"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-3","b":"social","s":3,"n":3,"t":"亲戚称谓拿不准，跟着家里人叫，或请父母先介绍","p":"舅公、表姑、堂叔这些称谓各地叫法不一，同一个人在你家可能叫法也不同。去之前问父母「见到谁该怎么叫」，或者见面时让父母先介绍，比自己乱猜稳妥。","tip":"「妈，待会儿那位我该叫什么？」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-4","b":"social","s":3,"n":4,"t":"介绍别人时，先把位低的介绍给位尊的","p":"通行做法是让地位更高的一方先知道对方是谁：把晚辈介绍给长辈，把下级介绍给上级，把自己公司的人介绍给客户，把主人介绍给客人。介绍时说清名字、身份和你们的关系，最好再加一句双方可能聊得来的点。","tip":"「张总，这是我们部门的小李，负责这次项目的落地。小李，这位是客户方的张总。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"新人,管理"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-5","b":"social","s":3,"n":5,"t":"自我介绍用三句话：我是谁、和你有什么关系、今天想聊什么","p":"自我介绍不是背简历，而是让对方迅速知道「为什么要和你说话」。第一句说名字和身份，第二句说你们的联系（谁介绍的、哪里见过），第三句说你的来意或你能提供什么。","tip":"「王老师您好，我是李明，在 X 公司做数据分析，上次听您讲座很受启发，想请教您一个关于调研方法的问题。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":"学生,新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-6","b":"social","s":3,"n":6,"t":"记住名字：见面时复述一遍，事后马上记下来","p":"叫得出对方的名字，是很直接的尊重。听到名字时在回应里用一次（「刘经理您好」），加微信或存电话时立刻备注姓名、单位、在哪认识。下次见面前翻一下备注，比当场想不起来体面得多。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-7","b":"social","s":3,"n":7,"t":"握手等对方先伸手：长辈、上级、女士优先","p":"握手时通常由位尊者、长辈、女士、主人先伸手，你再迎上去。力度适中，时间两三秒，眼睛看着对方。不要戴着手套、不要另一只手插兜，对方伸手你一定要接。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-8","b":"social","s":3,"n":8,"t":"递名片双手、字朝对方；接名片看一眼再收好","p":"递名片时双手拿着，文字正对对方；接名片时也用双手，看一眼对方的名字和职务，必要时读出来确认，再放进名片夹或上衣口袋。当面把名片随手塞进裤兜、压在杯子下面，都会让人不舒服。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":"新人,生意"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-9","b":"social","s":3,"n":9,"t":"第一次见面提前五到十分钟到","p":"第一次见面迟到，对方很难不往「不重视」上想。提前几分钟到，可以整理一下思路、找好座位。太早到也不好，比如提前半小时敲门会打乱主人安排，可以在附近等一会儿再进。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-10","b":"social","s":3,"n":10,"t":"第一印象来得极快，但后面的表现能改写它","p":"研究发现，人看一张脸十分之一秒就会对其可信度、能力形成判断，而且再多看一会儿判断也变化不大。所以第一次见面的整洁、守时、礼貌很重要。但第一印象不是判决书，之后几次靠谱的合作，足以把一个普通的开局扭转过来。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-11","b":"social","s":3,"n":11,"t":"着装比场合正式半档，拿不准就问","p":"面试、见客户、见对象家长，穿得比对方预期稍正式一点，最多显得认真；穿得太随便，容易被理解为不重视。不确定的时候，问组织者「这次大家一般穿什么」，比猜要稳。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq03-12","b":"social","s":3,"n":12,"t":"加了好友马上改备注：名字、单位、在哪认识","p":"微信好友一多，半年后谁也想不起谁。加好友的当场把备注改成「姓名-单位-场合」，比如「张伟-某银行-2026行业会」。下次对方发消息，你一眼就知道是谁、该用什么语气回。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-13","b":"social","s":3,"n":13,"t":"「亲」「宝」「家人们」别用在长辈和正式对象身上","p":"网络上流行的称呼在熟人、同龄人之间显得亲切，用在领导、客户、长辈身上就显得轻浮或不够尊重。正式沟通时用「您好」「X 老师」「X 总」，等对方先用轻松的语气，你再跟上。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-14","b":"social","s":3,"n":14,"t":"「老师」是很多行业里最稳妥的通用尊称","p":"在媒体、文化、教育、咨询、互联网等行业，不知道对方职务时称「X 老师」很普遍，既尊重又不涉及具体职务。对医生称「X 医生」「X 大夫」，对律师称「X 律师」，对有教授职称的称「X 教授」。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-15","b":"social","s":3,"n":15,"t":"同龄同事叫名字还是叫哥姐，跟着团队的习惯走","p":"有的公司习惯叫英文名或直呼其名，有的习惯「X 哥」「X 姐」，有的叫「X 工」「X 老师」。新人入职头几天先听大家怎么叫，跟着多数人走，比自己定规矩安全。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-16","b":"social","s":3,"n":16,"t":"别人叫错你的名字，第一次可以不纠正，第二次温和提醒","p":"偶尔被叫错，当场纠正可能让对方下不来台，可以先应下。但如果对方会长期和你打交道，第二次就要找机会轻松地提醒，越拖越不好改口。","tip":"「我叫李婷，女字旁的婷，很多人都会记成亭子的亭。」","cost":{"money":"0","time":"少","will":"些","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq03-17","b":"social","s":3,"n":17,"t":"第一次去别人家，别空手","p":"第一次登门，带一盒水果、点心或茶叶，表示你把这次拜访当回事。礼物不必贵，贵了反而让主人有负担。进门换鞋、不乱看不乱碰、离开时道谢，都是这次拜访的一部分。送什么、怎么送，见第 7 章。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq03-18","b":"social","s":3,"n":18,"t":"说话前先叫人：先称呼，再说事","p":"「王老师，想跟您确认一下……」比直接「那个，我想问一下……」更有礼貌。在家里也一样：进门先叫「爸、妈」，见到长辈先打招呼。称呼放在前面，是在告诉对方「我在跟你说话，我尊重你」。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-1","b":"social","s":4,"n":1,"t":"拿不准时先说「我看一下再回你」，别当场答应","p":"很多不该答应的事，都是在被当面追问、不好意思拒绝的时候答应下来的。给自己一个缓冲：先说要看看安排、要和家里商量、要确认一下预算，回去冷静想清楚再答复。","tip":"「我得先看下这周的安排，晚上给你准信。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-2","b":"social","s":4,"n":2,"t":"拒绝时给一个真实、简短的理由，不用编故事","p":"理由越长越像借口，编出来的理由还可能被拆穿。一句真实的理由就够了：「这周手上有两个项目要交」「这笔钱是我们留着付房租的」。对方追问细节，可以不展开。","tip":"「这周我实在排不开，不是不想帮你。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-3","b":"social","s":4,"n":3,"t":"拒绝后给一个替代选项，关系不容易受伤","p":"完全帮不了的时候，可以指一条路：推荐更合适的人、给一个可以参考的资料、换一个你能做的时间或方式。对方得到了一点帮助，也就不太在意你没全答应。","tip":"「这事我不熟，不过小王之前做过，我把他微信推给你？」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-4","b":"social","s":4,"n":4,"t":"借钱不想借，就说清楚「这次不方便」，别说「过两天」","p":"「过两天看看」「等我发了工资」会让对方一直等，最后你还得再拒绝一次，伤得更重。不打算借，就一次说清楚。如果愿意帮但不想借大额，可以说明你能拿出的额度，并且把它当成可能收不回来的钱。","tip":"「这次我手头真的不方便，帮不上你，别耽误你找别的办法。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq04-5","b":"social","s":4,"n":5,"t":"别人拿「你不帮就是不够朋友」施压时，可以不接这个框架","p":"「是不是朋友」「白对你好了」把一件具体的事上升成对整个关系的考验，这是在用愧疚感逼你答应。你可以承认关系的价值，同时坚持这件事做不了。真正的朋友不会因为一次拒绝就翻脸。","tip":"「我们是朋友，所以我才跟你说实话：这件事我真的做不了。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq04-6","b":"social","s":4,"n":6,"t":"拒绝领导分派的额外工作，说清现有任务和优先级","p":"对领导直接说「做不了」风险很大，但把手头的任务和截止时间摆出来，请领导决定优先级，就不是拒绝，而是汇报。领导知道你的负荷，会自己权衡要不要换人或延期。","tip":"「我现在手上有 A 和 B，周五都要交。这个新任务要是更急，A 能不能往后推两天？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq04-7","b":"social","s":4,"n":7,"t":"不想参加的饭局和聚会，提前说，别临时放鸽子","p":"订了位、算了人数，临时说不来，组织者最难受。不想去就在邀请时婉拒，或者至少提前一两天说。婉拒时表达一下心意，比如「下次我请」「帮我跟大家问好」。","tip":"「那天我有安排，去不了，你们吃好喝好，下回我做东。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-8","b":"social","s":4,"n":8,"t":"对方得寸进尺时，用「上次是特例」划回边界","p":"帮过一次，对方容易把它当成你的义务：上次帮他接孩子，这次就默认还是你；上次帮他垫钱，这次开口更理直气壮。边界一旦被推开，越晚收越难。明确告诉对方，上次是特殊情况，以后不能常态化。","tip":"「上次是正好赶上了，以后这种事我真没办法每次都帮。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-9","b":"social","s":4,"n":9,"t":"先被一个大要求吓到、再被一个「小一点」的要求说服，要警惕","p":"对方先提一个你肯定不会答应的大要求（借十万、买三年课），被拒后马上退一步（借两万、先上一个月），你会觉得对方让步了、自己也该让一步。其实第二个要求可能才是对方真正想要的。判断时把第二个要求单独拿出来想：如果他一开始就这么说，我会答应吗？","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"金钱","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-10","b":"social","s":4,"n":10,"t":"被拒绝了，先说「理解」，别追问、别翻旧账","p":"被拒绝时最伤关系的反应是追问「为什么不行」、翻出「我上次怎么帮你的」。对方拒绝，往往有他不方便说的难处。体面地接受，下次你开口时，对方会因为上次拒绝了你而更愿意帮忙。","tip":"「没事，理解，你也有你的难处。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-11","b":"social","s":4,"n":11,"t":"被拒绝不等于被否定，换个人、换个时间、换个方式再试","p":"求职被拒、求助被拒、提议被否，原因常常是时机不对、找错了人、方案不够具体，而不是你这个人不行。被拒后问一句「是哪方面不合适」，调整后换个人或过段时间再提。","tip":"「好的，方便的话能告诉我哪里还不够吗？我改进一下。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"学生,新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-12","b":"social","s":4,"n":12,"t":"拒绝推销和「熟人卖货」，一句「不需要，谢谢」就够了","p":"亲戚卖保险、同学做微商、朋友拉你听课，不买会觉得驳了面子。但买了不需要的东西，你吃亏；被拉进下线，可能更麻烦。客气但明确地拒绝，不必解释为什么不需要，更不必为了面子先买一点。","tip":"「我现在真不需要，你有其他事我能帮的再找我。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq04-13","b":"social","s":4,"n":13,"t":"拒绝表白或追求，要清楚、尽早，不留模糊的希望","p":"怕伤人而含糊其辞，比如「我现在不想谈恋爱」「我们先做朋友」，对方常会理解为还有机会。尊重对方的方式是清楚地说明你的态度，同时肯定对方的心意。之后减少单独相处，不接受对方的贵重礼物。","tip":"「谢谢你喜欢我，但我对你没有那种感觉，不想让你误会。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq04-14","b":"social","s":4,"n":14,"t":"可以拒绝亲戚，但对长辈语气要软、态度要定","p":"亲戚要你帮忙安排工作、借钱、担保，碍于辈分很难拒绝。语气上可以尊重、叫人、感谢关心，态度上不松口；必要时让父母出面沟通，或者用「我们家里商量过了」作为统一口径。","tip":"「舅舅，这事我真做不了主，也不想答应了办不好，耽误您。」","cost":{"money":"0","time":"少","will":"是","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq04-15","b":"social","s":4,"n":15,"t":"拒绝违规要求，用「规定」和「风险」说话，不用「我不想」","p":"有人让你改数据、补签字、走后门、开不实的证明，最有力的拒绝不是个人意愿，而是规定和后果：这样做违反哪条规定、出了事谁负责。把风险摆出来，对方往往也不愿意担。","tip":"「这个签了字是要我个人负责的，出了问题我和您都说不清，我们按流程走吧。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"新人,体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq04-16","b":"social","s":4,"n":16,"t":"群里有人@你帮忙，可以私聊回复，不必当众拒绝","p":"在群里被点名求助（转发投票、帮忙砍价、借东西），当众拒绝双方都尴尬，当众答应又不情愿。可以私聊对方说明情况，或者只回一个表情不表态。","tip":"（私聊）「群里那个我这次就不参与了哈，有别的事你再叫我。」","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq04-17","b":"social","s":4,"n":17,"t":"「好人」的标签不值钱，别为了它答应一切","p":"有求必应的人，常常不是最受尊重的人，而是最先被想到「反正他会答应」的人。你的时间、钱和精力有限，全部拿去满足别人，就没有留给自己和家人的。偶尔拒绝，别人会更认真地对待你的答应。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-18","b":"social","s":4,"n":18,"t":"答应了的事做不到，越早说越好","p":"答应了却发现做不到，最糟的做法是拖到截止前才说，或者干脆不说。提前说，对方还有时间找别人；最后才说，就是把对方坑了。说的时候讲清楚做到哪一步了、还差什么、你能补救什么。","tip":"「之前答应你周五给，我评估了一下大概要到下周二，你看来得及吗？不行我先把能用的部分发你。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq04-19","b":"social","s":4,"n":19,"t":"拒绝之后不必反复道歉","p":"拒绝时说一句「不好意思」是礼貌，反复说「真的很对不起」「我太过意不去了」，反而显得你理亏，对方会觉得还可以再争取一下。说清楚、表达理解，然后正常相处。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq04-20","b":"social","s":4,"n":20,"t":"拒绝的权利是平等的：你可以拒绝别人，别人也可以拒绝你","p":"很多人自己不敢拒绝，却很难接受别人拒绝自己；或者反过来，自己常拒绝别人，却觉得别人拒绝是不给面子。把拒绝看成正常的协商：每个人都有权根据自己的情况说「不」。这样拒绝和被拒绝都不再那么沉重。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-1","b":"social","s":5,"n":1,"t":"开口前先想清楚：这件事对方有没有能力、有没有风险","p":"求人最怕找错人：对方没这个能力，只能尴尬地拒绝；或者对方有能力，但帮你要冒违规的风险。先判断这件事在对方的职责和能力范围内吗？帮你会让他为难吗？会，就换个人或换个办法。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq05-2","b":"social","s":5,"n":2,"t":"把请求说完整：要什么、为什么、什么时候、对方要做多少","p":"「在吗？想请你帮个忙」最让人头疼，对方不知道是什么事，答应也不是，拒绝也不是。一次把事情说清：背景是什么、需要对方做哪一件具体的事、大概花多少时间、什么时候要、你已经做了哪些准备。","tip":"「王老师好，我在准备一个调研报告，有个统计方法拿不准，想请您帮忙看一下第三页的分析是否合理，大概十分钟。您这周哪天方便？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"学生,新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-3","b":"social","s":5,"n":3,"t":"把门槛降到最低：材料备齐、方案写好，对方只需拍板或动动手","p":"别人帮你，时间是他的。你多准备一点，他就少花一点。请人推荐，就附上简历和推荐要点；请人看方案，就标出需要他看的部分；请人引荐，就写好一段对方可以直接转发的介绍。","tip":"","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-4","b":"social","s":5,"n":4,"t":"求人帮忙之后，人反而可能更喜欢你","p":"很多人怕求人会欠人情、让人厌烦。研究发现，帮过你一个小忙的人，往往对你的好感会上升，因为人会倾向于认为「我愿意帮的人一定不错」。所以适度地请教、求助，反而是拉近关系的方式。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-5","b":"social","s":5,"n":5,"t":"帮完之后，一定要有反馈和感谢","p":"别人帮了你，最寒心的是事情办完就没了下文。不管结果好坏，都告诉对方：事情办成了没有，他的帮助起了什么作用。感谢要具体，比单纯说「谢谢」更让人记住。","tip":"「上次您帮我改的那版材料，评审都过了，尤其您建议加的那组数据，评委专门问到了。太感谢了！」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-6","b":"social","s":5,"n":6,"t":"托人办事，别让中间人替你背压力","p":"通过熟人找到能帮忙的人后，中间人的任务是引荐，不是替你催进度、替你担结果。拿到联系方式后，你直接和对方沟通，及时告诉中间人进展，事情办完分别感谢两个人。","tip":"（对中间人）「谢谢你帮我联系上李老师，后面我直接跟他对接，有结果第一时间告诉你。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-7","b":"social","s":5,"n":7,"t":"求人办事别先送礼，事成之后再表达心意","p":"事情还没办就先送东西，对方收了等于答应，不收又尴尬，还可能被理解为「花钱买结果」。普通的人情帮忙，事成后请吃顿饭、送点家乡特产就够了。对方是公职人员、手里有审批权的，礼物和宴请都要避开，见第 29 章。","tip":"「这次真的多亏你，周末请你吃个饭，别推。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq05-8","b":"social","s":5,"n":8,"t":"帮人之前先说清楚边界：帮到哪一步，不保证什么结果","p":"帮人推荐工作、引荐资源、介绍对象，结果不在你的掌控里。答应时说清楚：你只负责引荐或给建议，成不成要看对方自己。不然事情没成，对方会觉得你没尽力；成了出了问题，也会找到你头上。","tip":"「我可以把你的简历转给他们 HR，能不能进还得看面试，我没法打包票。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-9","b":"social","s":5,"n":9,"t":"帮人推荐人选，只推荐你真了解的，并且说实话","p":"推荐一个人，是在用你的信用为他担保。推荐了不靠谱的人，下次你说话就不灵了。不熟的人请你推荐，可以说「我只能帮你转交，不方便写推荐」；熟悉的人，也要如实说他的长处和短处。","tip":"「他做事很踏实，数据分析是强项，带团队的经验还少一些。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"体面","who":"新人,管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-10","b":"social","s":5,"n":10,"t":"别人求你时说「就这一次」，先想想有没有下一次","p":"「就帮这一次」「下不为例」，常常是下一次的开始。判断的方法：这个请求是不是对方长期问题的一部分？他自己有没有在解决？如果他每个月都会缺钱、每次出差都需要你接送，你的「这一次」很快会变成义务。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-11","b":"social","s":5,"n":11,"t":"帮人办事别邀功，也别到处说","p":"帮了别人的忙，到处说「他那个工作是我帮着找的」，对方会觉得欠了你一个公开的人情，反而疏远你。帮完就放下，对方心里自然记得；要是需要第三人知道，让受益人自己去说。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-12","b":"social","s":5,"n":12,"t":"去机关单位办事，先查清流程和材料，再找人问","p":"很多「求人办事」其实是不熟悉流程。先查官方网站、政务服务 App、12345 热线，把材料清单、办理时限、窗口地址弄清楚。实在不懂的再问熟人，问的是「流程是不是这样」，而不是「能不能帮我通融」。","tip":"","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq05-13","b":"social","s":5,"n":13,"t":"别人帮你的时候，别挑三拣四","p":"请朋友帮忙设计个海报、改个简历、搬个家，得到的结果可能不完全如你所愿。可以礼貌地提一两处修改，但不要像对待付费服务那样反复挑剔。真有严格要求，就花钱请专业的人。","tip":"「整体很好了，就是标题能不能再大一点？其他我都满意，辛苦你了。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-14","b":"social","s":5,"n":14,"t":"帮人帮到让对方能自己做，比替他做更好","p":"同事每次都找你帮忙处理同一个问题，你替他做完，下次他还会来找你。花一次时间教会他，或者把步骤写下来给他，以后他自己就能做。帮人独立，比让人依赖你更长久。","tip":"「这个步骤我写在文档里了，你照着走一遍，卡住了再叫我。」","cost":{"money":"0","time":"中","will":"些","gain":"中","lens":"关系","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-15","b":"social","s":5,"n":15,"t":"同一件事别同时托好几个人","p":"为了保险，同时托三个朋友帮你找关系、找房、找工作，最后几个人都在使劲，你却只能用其中一个结果，其他人白忙一场还会觉得被耍了。真要多路并行，就提前告诉每个人「我也在问别的渠道」。","tip":"「这事我也问了另外两个朋友，你方便就帮我留意下，不用特意跑。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-16","b":"social","s":5,"n":16,"t":"别人帮不上忙，也要感谢他花的时间","p":"对方打了几个电话、问了一圈，最后没办成，他也付出了时间和人情。只有办成了才感谢，会让人觉得你只看结果。帮不上也道一声谢，下次他还愿意尽力。","tip":"「没成也没关系，你为这事跑了好几趟，真的谢谢你。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-17","b":"social","s":5,"n":17,"t":"求人办事最好当面或电话，别只发文字","p":"文字请求容易被看成群发，也容易被搁置。研究发现，当面提出请求的成功率明显高于发邮件，而提出请求的人往往低估了这种差别。重要的请求，先打电话或当面说，再用文字把细节发过去。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-18","b":"social","s":5,"n":18,"t":"自己能查到的，别去问人","p":"问别人一个网上一搜就有答案的问题，会让人觉得你懒，也浪费对方时间。先自己查，查不到或看不懂再问，并说明你已经查了哪些、卡在哪里。这样的问题，别人更愿意认真回答。","tip":"「我查了官网和几篇教程，都说要先备案，但我这个情况属于例外吗？」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"学生,新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq05-19","b":"social","s":5,"n":19,"t":"别人求你办违规的事，拒绝后也不要替他保密到害了自己","p":"有人请你帮忙伪造材料、给评审打招呼、泄露未公开信息，你拒绝了，事情并没有结束。如果这件事涉及你的岗位职责（比如你负责审核），之后对方仍可能通过别人去办，被查出来你也可能被问「为什么知道不报告」。按单位规定，该报告的报告，该留痕的留痕。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq05-20","b":"social","s":5,"n":20,"t":"人情要用在关键处，别把小事都托关系","p":"每次托人都会消耗一点人情。买东西要折扣、孩子转个班、挂个普通号都去找熟人，真正遇到大事时，对方可能已经不想再帮了。小事自己按流程办，把人情留给真正需要的时候。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq06-1","b":"social","s":6,"n":1,"t":"记一本简单的人情账：谁、什么事、多少钱","p":"婚丧嫁娶、生孩子、乔迁、升学，收到和送出的礼金时间一长就记不清。在手机备忘录或表格里记下：日期、对方姓名、事由、金额或礼物。下次对方家里有事，翻一下就知道该怎么回。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-2","b":"social","s":6,"n":2,"t":"回礼一般略高于或等于对方当初的礼","p":"对方当年随你两百，现在轮到他家办事，你回两百或略多一点，表示记得这份情。明显少于对方给的，会被理解为疏远；多出很多，对方下次又得加码，变成负担。物价上涨、时隔多年的，可以适当加一点。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-3","b":"social","s":6,"n":3,"t":"别人帮了大忙，用对方需要的方式还，而不一定是钱","p":"有些人情用钱还反而显得生分，比如对方帮你介绍了工作、帮你家人找了医生。更好的方式是在他需要时出力：他孩子升学你帮着打听信息，他搬家你去帮忙，他有好消息你真心祝贺。","tip":"","cost":{"money":"少","time":"中","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-4","b":"social","s":6,"n":4,"t":"不想深交的人，人情尽快两清","p":"对你有所图、你不想长期来往的人，帮了你一次，最好尽快用对等的方式还上，比如请吃饭、送一份价值相当的礼物。人情一旦拖着，对方日后开口求你时，你就很难拒绝。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-5","b":"social","s":6,"n":5,"t":"来路不明的好处，先别收","p":"关系一般的人突然送你贵重礼物、请你吃高档饭、帮你免费办事，大概率是在为以后的请求做铺垫。你手里如果有对方需要的权力或资源，这份好处收了，往后就很难说「不」。不明白对方为什么对你这么好的时候，先婉拒。","tip":"「心意领了，东西真不能收，有什么事你直说就行。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"体制内,管理"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq06-6","b":"social","s":6,"n":6,"t":"人情不对等时，别指望「我对他好，他也会对我好」","p":"有的人只接受不回报，你付出越多，他越理所当然。互惠是人情的基础，但不是所有人都遵守。连续几次单方面付出都没有回应，就减少投入，把精力留给有来有往的人。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-7","b":"social","s":6,"n":7,"t":"欠了人情说「谢谢」不够，要说「有事随时找我」并且做到","p":"感谢之后表明愿意回报，是人情往来里很重要的一步。关键是对方真来找你时，你要接得住，不能推三阻四。说了做不到，比不说更伤人。","tip":"「这次真的多亏你，以后你那边有用得上我的，一定开口。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-8","b":"social","s":6,"n":8,"t":"钱债和人情分开还：借的钱按时还，感谢另外表达","p":"找朋友借钱应急，按约定时间把钱还上，是还了钱债；但对方在你最难的时候伸手，这份情还在。还钱时附一句感谢，或者事后请吃顿饭、送点特产，人情才算有了交代。只还钱不表示，对方会觉得借钱给你只是一笔没利息的生意。","tip":"「钱给你转过去了，那会儿真是多亏你，改天我请你吃饭。」","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-9","b":"social","s":6,"n":9,"t":"熟人帮忙涉及钱，事先说清楚，比事后「看着给」好","p":"请亲戚装修、找朋友代购、让熟人帮忙卖二手车，最容易出矛盾的是「到底给多少」。事前不说，事后给多了心疼、给少了伤情。熟人之间可以优惠，但价格、范围、出了问题谁负责，最好提前讲明白，大额的写下来。","tip":"「咱们亲兄弟明算账，你按正常价报，材料单子也给我一份，这样我心里踏实。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-10","b":"social","s":6,"n":10,"t":"对你有恩的人，平时就要有往来，别等有事才出现","p":"老师、老领导、在你困难时帮过你的人，平时不联系，只在需要帮忙时才想起来，对方会觉得你是功利。过年发个问候、有好消息告诉他一声、路过他的城市约一次饭，关系就一直是热的。","tip":"「王老师，新年快乐！今年我换到了新岗位，挺顺利的，一直记着您当年的指点。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq06-11","b":"social","s":6,"n":11,"t":"「我当年帮过你」，最好别从自己嘴里说出来","p":"人情是对方心里记着的东西，你一提，就变成了讨债。帮过别人，对方记得最好；不记得，你提出来也换不回真心，反而让对方觉得被要挟。真的需要对方帮忙，就就事论事地请求，不翻旧账。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-12","b":"social","s":6,"n":12,"t":"还人情最好的时机，是对方落难的时候","p":"对方顺风顺水时，你锦上添花，他未必记得；对方生病、失业、家里出事时，你一个电话、一次探望、一点实际的帮助，他会记很多年。帮过你的人走了下坡路，正是你表达感激的时候。","tip":"「听说你最近身体不太好，我明天过去看看你，需要带点什么吗？」","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq06-13","b":"social","s":6,"n":13,"t":"多年不联系的人请你随礼，可以只随礼不出席，也可以都不去","p":"十年没说过话的老同学突然发来请柬，去不去、随不随，看你们以前的交情和以后会不会来往。交情还在的，人不到礼到；只是名单上的人，可以发一句祝福，不随礼也不失礼。别为了面子把钱撒给不会再见的人。","tip":"「恭喜恭喜！那天实在赶不过去，祝你们新婚快乐。」","cost":{"money":"少","time":"少","will":"些","gain":"中","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-14","b":"social","s":6,"n":14,"t":"父母那一辈的人情，成年后接过来一部分","p":"父母的老同事、老邻居、几十年的朋友，当年在你上学、生病、找工作时可能都出过力。父母年纪大了，这些往来慢慢要由你接手：对方家里有大事，你可以代父母去一趟；父母生病住院，这些人往往是最先来看望的。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-15","b":"social","s":6,"n":15,"t":"随礼支出太重时，缩小范围，而不是硬撑","p":"一年随礼花掉一两个月工资的人并不少。人情往来要量入为出：亲属、真朋友、重要同事照常随；只是加过微信、见过一面的，送上祝福就够了。比起为了面子透支，被少数人说两句的代价要小得多。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-16","b":"social","s":6,"n":16,"t":"收到礼要及时回应，别让对方猜你收到没有","p":"微信转账、快递寄来的礼物、托人带的红包，收到后第一时间告诉对方并道谢。迟迟不回应，对方会担心没送到，或者觉得你不在意。转账红包收了要回句话，不收也要及时退回并说明原因。","tip":"「东西收到了，特别喜欢，让你破费了！」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq06-17","b":"social","s":6,"n":17,"t":"回礼少了不一定是看不起你，别急着记仇","p":"你当年随了五百，人家这次回了三百，可能是手头紧，可能是记错了，也可能是当地习惯不同。为几百块钱断一段关系不划算。偶尔一次不对等，放下；长期只收不回、只求不帮，再慢慢疏远。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq06-18","b":"social","s":6,"n":18,"t":"救命之恩、救急之恩，要记一辈子","p":"在你重病时帮你找医生、在你走投无路时借钱给你、在你被冤枉时站出来作证的人，这份恩情不是一顿饭能还清的。不必时时挂在嘴上，但对方或其家人遇到大事时，要出现、要尽力。","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-1","b":"social","s":7,"n":1,"t":"先想清楚送礼的目的：是表达心意，还是想换什么","p":"生日、节日、乔迁、探病、答谢，这些是表达心意，礼物合适就好。如果送礼是为了让对方在审批、招标、评级、升学、录用这类事情上给你「照顾」，并且对方手里正好有这个权力，这就不再是人情，而可能涉嫌行贿。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq07-2","b":"social","s":7,"n":2,"t":"送礼看对方需要，不看你自己喜欢","p":"你觉得好的东西，对方未必用得上。送之前想想对方的年龄、身体、爱好和家庭：长辈血糖高就别送点心礼盒，朋友刚搬家缺的是实用家居，同事有小孩送儿童用品更受欢迎。拿不准的，送大家都用得上的消耗品。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-3","b":"social","s":7,"n":3,"t":"礼物的价格和关系的深浅相当，太贵反而是负担","p":"普通朋友送一件远超平时往来水平的礼物，对方第一反应往往不是高兴，而是「我该怎么还」「他是不是有事求我」。礼物的价格大致和你们平时往来的水平持平，最多略高一点，对方收得安心。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-4","b":"social","s":7,"n":4,"t":"避开谐音和习俗上的忌讳","p":"不少地方忌讳送钟（谐音「送终」）、伞（「散」）、梨（「离」，尤其不要分着吃），给老人送礼避开「四」这个数，探望病人不送白色、黄色菊花。各地讲究不同，不必样样当真，但送给长辈、送给讲究的人，避开总没错。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq07-5","b":"social","s":7,"n":5,"t":"递礼时说一句轻话，别强调价钱","p":"送礼时说「一点家乡特产，您尝尝」「看到觉得适合您就买了」，让礼物显得轻松自然。强调「这可是托人买的」「好几千呢」，会把心意变成压力，也让人觉得你在邀功。价签、小票提前撕掉；需要保修的，单独装个信封附上。","tip":"「没什么贵重的，带了点老家的茶叶，您别嫌弃。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-6","b":"social","s":7,"n":6,"t":"对方推辞时，客气两次是礼节，再推就是真不要","p":"中国人收礼常常要推让几次，表示不贪、给送礼人面子。一般坚持一两次，对方就会收下。如果对方语气坚决、反复推辞，或者说明「单位有规定」，那就是真的不能收，再塞就让对方为难了。","tip":"「那我就不勉强了，心意您收下就好。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-7","b":"social","s":7,"n":7,"t":"收礼当面拆不拆，看场合；拆了就要表现出喜欢","p":"传统上中国人不当面拆礼物，免得显得看重东西；年轻人、生日聚会上当面拆则很常见，送礼人也期待看到你的反应。拆了就真诚地说一句喜欢在哪里；不拆就先道谢，事后再发消息告诉对方你很喜欢。","tip":"「这个颜色正好是我想要的，你太懂我了！」","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-8","b":"social","s":7,"n":8,"t":"普通单位逢年过节给领导送礼，小心意可以，贵重礼不要","p":"在私企、外企，出差带点特产分给整个部门、节日送领导一份不贵的伴手礼，属于正常人情。单独给领导送贵重礼物、购物卡、现金，容易被理解为「有所求」，也可能违反公司的廉洁制度；领导收了反而被动。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"自保","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq07-9","b":"social","s":7,"n":9,"t":"给公职人员送礼送宴请，对方收了违纪，你送了也可能违法","p":"中央八项规定和党纪明确禁止党员干部、公职人员收受可能影响公正执行公务的礼品、礼金、消费卡、有价证券和电子红包，也禁止接受可能影响公务的宴请。请托办事时给对方送钱物、谋取不正当利益，送的一方可能构成行贿罪。去机关办事，按流程来，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"体制内,生意"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq07-10","b":"social","s":7,"n":10,"t":"不用给孩子的老师送礼，想感谢就写几句真话","p":"教育部的教师职业行为准则明确要求，老师不得索要、收受学生和家长的财物，也不得参加家长付费的宴请、旅游。家长送购物卡、红包，是在让老师违规，也让孩子在班里处境尴尬。真想表达感谢，教师节让孩子写一张卡片，或者给学校写一封表扬信。","tip":"「王老师，这学期孩子数学进步很大，谢谢您的耐心，孩子也特别喜欢您。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":"父母"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq07-11","b":"social","s":7,"n":11,"t":"看病不用给医生塞红包，感谢可以送锦旗、写表扬信","p":"医务人员廉洁从业准则明确规定，不得收受患者及其亲友的红包、礼品、消费卡。正规医院的诊疗按规范进行，不送红包不会被区别对待；医生收了反而违规。病好了想感谢，送一面锦旗、在医院的评价系统里写几句具体的好评，医生会很受用。","tip":"「李医生，这次手术多亏您，我们写了封感谢信交给科室了。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-12","b":"social","s":7,"n":12,"t":"出差旅行回来带点特产，部门里人人有份","p":"从外地回来，带一盒当地特色零食放在办公区，招呼大家来拿，是很好的随手人情。关键是不厚此薄彼：只给领导和关系好的同事，没拿到的人会觉得被冷落。量要够，最好是独立包装、方便分的。","tip":"「这是那边的特色饼，放茶水间了，大家随便拿哈。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-13","b":"social","s":7,"n":13,"t":"探病的礼物看病情，问清能吃什么再买","p":"探病最常见的错误是带一堆病人不能吃的东西：糖尿病人收到点心，术后禁食的人收到水果篮，过敏的人收到鲜花。先问家属病人现在能吃什么、需要什么。很多地方探病习惯包个红包，让家属自己安排，也是实用的心意。","tip":"「阿姨，叔叔现在饮食上有什么要注意的吗？我带点他能吃的。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq07-14","b":"social","s":7,"n":14,"t":"不该收的礼，尽快原样退回，并留下记录","p":"工作关系中有人送来明显超出正常往来的礼品、购物卡、红包，拖得越久越说不清。当场能拒就当场拒；事后发现的，尽快原样退回，转账退回要截图保存；公职人员按单位规定登记上交。退礼时语气客气，把原因归到「单位有规定」。","tip":"「谢谢你的好意，单位规定这类东西我不能收，已经给你退回去了，事情我们按流程办。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"体制内,管理"},"grade":"A","disputed":false,"ev":"官方文件","hasRef":false},{"id":"rq07-15","b":"social","s":7,"n":15,"t":"节礼要提前送，别等节日当天","p":"中秋的月饼、春节的年货，提前几天送到最合适：对方能用上，也有时间回礼。节日当天才送，对方可能已经出门走亲戚，东西也错过了时候。快递寄的，要算好物流时间，节前一周左右寄出。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-16","b":"social","s":7,"n":16,"t":"给长辈送烟酒，先考虑他的身体","p":"烟酒是传统的「硬通货」，但对有高血压、糖尿病、心脏病的长辈，送烟酒等于送风险。很多老人嘴上说喜欢，家里人却在劝他戒。不如换成按摩仪、体检套餐、好茶叶、合脚的鞋，或者一次陪伴的旅行。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-17","b":"social","s":7,"n":17,"t":"别送假货、山寨货和临期食品","p":"为了显得贵，买仿冒的名牌包、来路不明的「特供酒」，一旦被识破，比不送还丢人。食品、保健品要看保质期和生产许可，送给老人、孩子的更要谨慎。宁可送一件普通但真材实料的东西。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-18","b":"social","s":7,"n":18,"t":"回礼不急于一时，下一个合适的场合补上即可","p":"收了礼马上回一份等价的，像是急着两清，对方可能觉得你见外。更自然的做法是记住这份情，在对方生日、节日、家里有喜事时回一份。真的想当场回点什么，回一样不贵的小东西，比如家里的特产。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq07-19","b":"social","s":7,"n":19,"t":"不确定送什么，就送「吃得完、用得掉」的","p":"摆件、装饰画、纪念品，送的人觉得有意义，收的人常常不知道放哪。实在不了解对方，送好一点的水果、茶叶、咖啡、零食、洗护用品，不占地方，用完就没有负担。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-20","b":"social","s":7,"n":20,"t":"托人转交的礼，要让收礼人知道是谁送的","p":"托朋友带东西给第三个人，到了对方手里常常说不清是谁送的、送的是什么。附一张写了名字的卡片，或者你自己发条消息告诉对方「托某某带了点东西给你」，双方都清楚。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-21","b":"social","s":7,"n":21,"t":"送礼的场合要私密，别当着第三人塞给关键的人","p":"当着一屋子人只给其中一位送礼，其他人尴尬，收礼的人也难办。给长辈、老师、恩人单独表达心意，找私下的场合；面向一群人的，就准备一份大家都有的。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq07-22","b":"social","s":7,"n":22,"t":"礼物可以简单，心意要具体：附一句写给对方的话","p":"同样一盒茶叶，附一张手写卡片「记得你说最近熬夜多，这个茶是我常喝的，安神」，就从一件商品变成了一份心意。写清楚你为什么送这个、想到了对方什么，比礼物本身更让人记住。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-1","b":"social","s":8,"n":1,"t":"随多少看三样：关系远近、当地行情、对方随过你多少","p":"最直接的参照是对方当年随你的数（翻人情账，见第 6 章）；没有往来记录的，问问同一圈子的人一般随多少；再根据你们的亲疏远近上下浮动。直系亲属、多年好友明显高于普通同事和点头之交。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq08-2","b":"social","s":8,"n":2,"t":"喜事随吉利的双数，白事很多地方随单数","p":"结婚、满月、乔迁这类喜事，多数地方喜欢双数和吉利数，比如 600、666、800、888，避开带「4」的数。不少北方地区白事随单数，寓意「不成双」，不希望坏事再来。习俗各地不同，拿不准就问当地长辈。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-3","b":"social","s":8,"n":3,"t":"红包背面写上名字，方便主家记账","p":"婚宴、寿宴收礼的人一天要收几十上百个红包，没写名字的很容易记混，主家想回礼都不知道回给谁。在红包背面写上你的名字，两个人一起随的写两个名字；转账的话在备注里写上姓名和祝福。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-4","b":"social","s":8,"n":4,"t":"去不了可以「人不到礼到」，附上一句祝福","p":"异地、时间冲突、身体不适去不了的，可以提前转账或托人带礼金，并发一条真诚的祝福。不去也不随，又是关系比较近的人，对方会觉得你不在意。","tip":"「那天实在赶不回去，礼金先转给你，祝你们百年好合，回来一定补上喜酒！」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-5","b":"social","s":8,"n":5,"t":"一家人一起去，份子通常要比一个人多","p":"婚宴按人头摆酒，你带上伴侣、孩子一起去，占了好几个座位，只随一份单人的礼，主家嘴上不说，心里可能会算。带家属去的，礼金适当加一些；不确定能不能带家属，提前问一声。","tip":"「到时候我和爱人一起过去，没问题吧？」","cost":{"money":"少","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-6","b":"social","s":8,"n":6,"t":"白事不说「恭喜」，穿深色衣服，少说多陪","p":"参加葬礼、吊唁，穿黑、灰、深蓝等素色衣服，不化浓妆、不戴鲜艳首饰。见到家属说「节哀」「保重身体」，不追问去世的细节，不在现场大声谈笑、玩手机。能帮忙的地方（接待、跑腿）主动问一句。","tip":"「叔叔阿姨节哀，有什么要帮忙的随时叫我。」","cost":{"money":"少","time":"中","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq08-7","b":"social","s":8,"n":7,"t":"看望产妇和新生儿：先问时间，别久坐，抱孩子前洗手","p":"刚生完孩子的头一个月，产妇需要休息，家里也忙乱。去看望前先问方不方便，待二三十分钟就走。不要随手抱孩子、亲孩子，感冒咳嗽时别去。礼物送尿不湿、婴儿衣物（大一两个码）、给产妇的营养品，或者包一个给孩子的红包。","tip":"「恭喜恭喜！孩子真可爱，你好好休息，我们就不多打扰了。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"官方文件","hasRef":false},{"id":"rq08-8","b":"social","s":8,"n":8,"t":"满月酒、百日宴的红包，是给孩子的祝福","p":"满月、百日、周岁的红包，通常比婚礼份子少一些，寓意给孩子添福。很多地方习惯把红包塞到孩子的襁褓里或交给孩子的父母。也可以送一件寓意好的小礼物，比如长命锁、银手镯，但要注意孩子小，不送能放进嘴里的小物件。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"小","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-9","b":"social","s":8,"n":9,"t":"升学宴：亲戚给孩子包个红包即可，公职人员不要操办也不要赴宴收礼","p":"孩子考上大学，亲朋好友给孩子一点鼓励，送学习用品或红包，是人之常情。但近年各地纪委多次通报公职人员违规操办「升学宴」「谢师宴」借机收礼的问题。体制内的家长，孩子升学可以家里人庆祝，不要大范围宴请、不要收管理服务对象的礼金。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"自保","who":"父母,体制内"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq08-10","b":"social","s":8,"n":10,"t":"乔迁随礼送实用的，别送钟、别送镜子","p":"朋友搬新家，送一件新房用得上的东西：好一点的锅具、香薰、绿植、家用小电器，或者直接随个红包让主人自己置办。送钟有「送终」的忌讳，一些地方也忌讳送镜子、送刀具。拿不准的，问问主人缺什么。","tip":"「新家缺点啥不？我给你添一样。」","cost":{"money":"少","time":"少","will":"否","gain":"小","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-11","b":"social","s":8,"n":11,"t":"开业送花篮或红包，说吉利话，别说「不好做」","p":"朋友开店、公司开业，送一对花篮、一盆发财树，或者包一个红包，图的是热闹和好兆头。开业当天说「生意兴隆」「开门大吉」，不要当着客人分析「这地段不好做」「现在实体店难」。有余力的，开业后去消费一次、帮着推荐一下，比什么都实在。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"小","lens":"体面","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-12","b":"social","s":8,"n":12,"t":"同事的份子钱，问老同事「一般随多少」，或者部门一起凑","p":"单位里随礼通常有不成文的标准，随多了让别人为难，随少了显得小气。新人先问老同事；部门统一凑份子送一份大礼，既省心又不用比较。关系特别好的同事，可以在部门份子之外单独再表示一下。","tip":"「王姐，咱们部门这种情况一般大家随多少啊？」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-13","b":"social","s":8,"n":13,"t":"份子钱随出去，一般就要不回来了","p":"法律上，随礼一般属于赠与，礼金交给对方之后，就不能因为对方不回礼、后来翻脸、婚礼取消就随便要回来。所以随礼要量力而行，别把「以后会回来」当成借出去的钱。彩礼不同，有专门的返还规则，见第 14 章。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq08-14","b":"social","s":8,"n":14,"t":"公职人员办婚丧喜庆：控制规模、按规定报告、不收管理对象的礼","p":"党员干部和公职人员操办婚丧喜庆，很多单位要求事先报告规模和邀请范围，禁止借机敛财，禁止收受下属、管理服务对象和有利害关系的人的礼金。亲属之间正常随礼不受影响，但「来者不拒」的大操大办，是纪委通报的高发问题。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-15","b":"social","s":8,"n":15,"t":"不想随礼的场合，送上祝福也是一种礼数","p":"只见过几面的人发来请柬、多年不联系的同学群里发电子喜帖，你不去也不随，没有人能指责你。回一句真诚的祝福，就已经尽到了礼数。份子钱留给还会长期来往的人。","tip":"「恭喜恭喜，祝你们幸福！」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq08-16","b":"social","s":8,"n":16,"t":"二婚、补办婚礼也可以随，金额看关系，不必比照头婚","p":"朋友再婚、领证几年后补办婚礼，都是值得祝福的事。随礼金额看你们的关系，很多人会比头婚时少一些，但对真心朋友不必刻意少给。最重要的是别说「怎么又办」「上次不是随过了」这类话。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"小","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-17","b":"social","s":8,"n":17,"t":"主家帮忙收礼的人，要可靠、要当天清点交接","p":"婚宴、寿宴、白事收礼，最好安排两个可靠的人一起负责：一人收、一人记，礼金和礼单当天当面清点后交给主家。扫码收款的，用主家本人的收款码。交接不清，事后少了钱，伤的是亲戚之间的信任。","tip":"","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-18","b":"social","s":8,"n":18,"t":"办完事要一一道谢，别收了礼就没下文","p":"婚礼、满月、寿宴结束后，给来宾和随礼的人发一条感谢消息，最好单独发、带上称呼，而不是群发。远道而来、帮了大忙的人，可以另外送一份回礼或请吃顿饭。","tip":"「李叔，谢谢您昨天专门赶过来，还帮着招呼客人，辛苦您了！」","cost":{"money":"0","time":"中","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-19","b":"social","s":8,"n":19,"t":"电子请柬、群发收款码，很多人会反感","p":"在大群里发电子请柬、附上收款二维码，容易让人觉得「只是为了收礼」。重要的亲友，打个电话或单独发消息邀请；不太熟的人，不必邀请。礼金让对方自愿，不要在群里催、晒收了多少。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq08-20","b":"social","s":8,"n":20,"t":"遏制人情攀比，可以从自己家开始","p":"各地都在推动婚俗改革、移风易俗，倡导婚事新办、丧事简办，有的村规民约还对酒席桌数、礼金标准作了上限。自家办事时控制规模、明说「不收礼金」或设一个较低的标准，亲友的负担轻了，往往也更愿意真心来。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"中","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-1","b":"social","s":9,"n":1,"t":"先弄清这顿饭的性质，再决定穿什么、说什么、带谁","p":"家人聚餐、朋友小聚、领导请客、商务宴请、相亲见家长，规矩完全不同。朋友聚会可以随意，商务宴请要注意座次和话题，领导请客要照顾全场。拿不准时问组织者：「都有谁？大概什么场合？」","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-2","b":"social","s":9,"n":2,"t":"主位多在面对门口的正中，主宾坐在主人右手边","p":"多数地方的宴席，面对包间门口、视野最好的位置是主位，由请客的主人或在场最尊贵的人坐；最重要的客人坐在主人右手边，次要的客人坐在左手边；靠门、上菜口的位置通常留给陪同人员或晚辈。各地规矩不同，有的地方以左为尊，有的由「副陪」坐主人对面。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"新人,生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-3","b":"social","s":9,"n":3,"t":"拿不准坐哪，就等主人安排，别一进门先坐下","p":"作为客人或者晚辈、下属，进了包间别急着找位子坐，更别直接坐到面门的位置。等主人或组织者招呼「您坐这儿」再落座；主人让你坐上座时，客气推辞一下，对方坚持再坐。","tip":"「您先坐，我坐哪都行。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-4","b":"social","s":9,"n":4,"t":"请客点菜：先问忌口，荤素冷热搭配，菜量比人数多一两个","p":"请客时先问客人有没有不吃的东西、有没有忌口（宗教、过敏、控糖、吃素）。点菜讲究搭配：有冷有热、有荤有素、有一道当家菜、有汤有主食。数量一般是人数再加一两道，宁可略有剩余，不要吃到一半不够。","tip":"「大家有没有什么不吃的？我先点几个，不够再加。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-5","b":"social","s":9,"n":5,"t":"被请客时点菜，点一两个中等价位的，别点最贵的","p":"主人把菜单递给你，全推回去显得客套过头，点最贵的海鲜又显得不客气。点一两道中等价位、大家都能吃的菜就好；主人坚持让你多点，再加一个。","tip":"「那我点个清炒时蔬，其他您来安排。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-6","b":"social","s":9,"n":6,"t":"转桌顺时针，主宾先动筷，别人夹菜时不要转","p":"新菜上桌，先转到主宾或长辈面前，请他们先尝。转盘一般顺时针转，转之前看一眼有没有人正在夹菜。不要把一道菜转到自己面前不停地夹，也不要隔着转盘伸长胳膊。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-7","b":"social","s":9,"n":7,"t":"买单在席间悄悄去，别在门口当众抢着付","p":"请客的人最好在点菜时或吃到一半，借去洗手间的机会把单买了，结束时大家起身就走。散席时在收银台前你推我让、拉拉扯扯，既耽误时间又尴尬。说好 AA 的，饭前讲清楚，饭后一人收款再分摊。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-8","b":"social","s":9,"n":8,"t":"被请了一次，下次找机会请回来","p":"朋友、同事之间吃饭，你请一次我请一次，关系就有来有往。总是被请却从不回请，时间长了别人会觉得你只占便宜。回请不必同样规格，心意到了就好。","tip":"「上次你请的，这次换我，下周找家好吃的？」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-9","b":"social","s":9,"n":9,"t":"饭桌上手机静音，别长时间低头","p":"大家在说话，你一直低头看手机、回消息、刷视频，等于告诉在场的人「你们没我手机里的东西重要」。手机调成静音放一边，确实有急事要处理，说一声「不好意思，我回个消息」，再出去打电话。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-10","b":"social","s":9,"n":10,"t":"饭局话题别碰收入、政治立场和别人的私事","p":"饭局上人多嘴杂，聊工资、聊站队、聊某个不在场的人的八卦，最容易传出去变味。安全的话题是美食、旅行、孩子（对方愿意聊时）、共同的爱好和行业里的公开新闻。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-11","b":"social","s":9,"n":11,"t":"晚辈、下属多照应：添茶、倒水、照顾长辈和客人","p":"和长辈、领导、客户吃饭，年纪最小或职位最低的人，要多留意：谁的茶杯空了，谁够不着菜，谁需要叫服务员。不用刻意表现，顺手做到就好。倒茶时七八分满，壶嘴不对着人。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-12","b":"social","s":9,"n":12,"t":"中途要走，先跟主人打招呼，别悄悄消失","p":"有事要提前离席，先跟主人和主宾打声招呼，说明原因，道个歉再走。不告而别，主人会担心你是不是不高兴，其他人也会议论。知道自己要早走，入席时就先说一声。","tip":"「不好意思，家里有点事我得先走，大家慢慢吃，改天我请。」","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-13","b":"social","s":9,"n":13,"t":"商务宴请重在建立关系，别在饭桌上逼对方当场拍板","p":"请客户吃饭，目的通常是增进了解、建立信任。饭桌上逼着对方压价、签字、表态，对方即使当场答应，酒醒了也可能反悔。饭局上多聊行业、聊对方关心的事，具体条款第二天正式沟通、落在纸面上。","tip":"","cost":{"money":"少","time":"中","will":"否","gain":"中","lens":"关系","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq09-14","b":"social","s":9,"n":14,"t":"有人迟到，等一刻钟左右可以先上凉菜；主宾没到就再等等","p":"作为主人，约定时间过了十几分钟，可以先请到场的人喝茶、上几道凉菜；主宾或长辈还没到，一般要等到他到了再正式开席。作为迟到的一方，提前告诉主人大概几点到，并请大家先吃。","tip":"「路上堵车，大概还要二十分钟，大家先吃，别等我。」","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-15","b":"social","s":9,"n":15,"t":"体制内的公务接待有硬标准：家常菜、不上高档菜品和烟酒","p":"党政机关的公务接待，工作餐要求提供家常菜，不得提供鱼翅、燕窝等高档菜肴和用野生保护动物制作的菜肴，不得提供香烟和高档酒水，不得使用私人会所和高消费餐饮场所。超标准接待、借公务名义宴请吃喝，是纪委查处的重点。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"官方文件","hasRef":false},{"id":"rq09-16","b":"social","s":9,"n":16,"t":"别在饭桌上批评人、算旧账","p":"饭桌是放松和联络感情的地方。当着一桌人批评下属、数落孩子、跟伴侣吵架，不只当事人难堪，全桌人都吃不下去。有意见，散席后单独说。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-17","b":"social","s":9,"n":17,"t":"散席后，主人送客人到门口或车边","p":"作为主人，饭后把客人送到包间门口、电梯口或车边，看着客人离开再回去，是很周到的礼数。客人喝了酒的，帮忙叫代驾或出租车，确认安全到家。","tip":"「到家了给我发个消息啊。」","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq09-18","b":"social","s":9,"n":18,"t":"打包看场合：朋友和家宴可以，商务宴请听主人的","p":"朋友聚餐、家里吃饭，剩菜打包是节约，没人会笑话。商务宴请时，作为客人主动要求打包可能让主人尴尬，可以等主人提议；作为主人，剩得多可以问客人要不要带走一些。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-19","b":"social","s":9,"n":19,"t":"别人给你夹菜、劝你多吃，有忌口就直说","p":"长辈、热情的主人爱给人夹菜、劝人多吃，这是好意。实在吃不了，或者有过敏、宗教、健康上的忌口，直接说明比勉强吃下去好。对方夹到你碗里的菜不想吃，可以留着不动，不必当众退回去。","tip":"「谢谢阿姨，我对海鲜过敏，这个就不吃了，我多吃点别的。」","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq09-20","b":"social","s":9,"n":20,"t":"想带人赴约，先问主人","p":"主人订位、点菜都是按人数准备的，临时带上朋友、同事或家属，主人可能要加座加菜，也可能有些话题不便当着外人说。想带人一起，提前问一句，主人说不方便就别勉强。","tip":"「明天我能带个朋友一起吗？他也做这行，正好想认识一下大家。」","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-1","b":"social","s":10,"n":1,"t":"不能喝，一开始就说清楚，别喝了一半再推","p":"入席时就说明今天不喝酒的原因：开车、在吃药、酒精过敏、身体不适。理由一开始就摆出来，大家也就不再劝；喝了几杯再说不能喝，别人只会觉得你是在找借口，劝得更凶。说了不喝，就以茶代酒或以饮料代酒参与敬酒。","tip":"「不好意思，我今天开车，以茶代酒敬大家。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-2","b":"social","s":10,"n":2,"t":"敬酒顺序：主人先敬，先长后幼、先主宾后其他人","p":"多数地方的规矩是，开席后由主人先敬全桌，再由主宾回敬；之后其他人才开始依次敬酒，顺序一般是先长辈、领导、主宾，再到同辈。晚辈、下属不要抢在主人前面敬酒，也不要越过长辈先敬身份低的人。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-3","b":"social","s":10,"n":3,"t":"敬酒起身、杯口略低于对方，说一句具体的话","p":"给长辈、领导、客人敬酒时，起身走到对方身边，碰杯时杯口略低于对方，表示尊重。敬酒词不用长，说一件具体的事比空喊「感谢领导」更真诚。对方可以少喝或只抿一口，你自己量力而行。","tip":"「张总，这次项目多亏您把关，我敬您一杯，您随意，我干了。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-4","b":"social","s":10,"n":4,"t":"别劝酒：强行劝酒出了事，劝酒的人要担责","p":"「感情深一口闷」「不喝就是看不起我」这类劝酒，在法律上可能成为过错。司法实践中，同饮者强迫劝酒、明知对方不能喝或身体有病仍劝、对方醉酒后不照看不护送、明知对方酒后要开车不劝阻，出了伤亡事故，常被判承担一定比例的赔偿责任。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-5","b":"social","s":10,"n":5,"t":"喝酒不开车：饮酒驾驶会被罚，醉驾是犯罪","p":"血液酒精含量达到每百毫升 20 毫克就是饮酒驾驶，会被暂扣驾照并罚款；达到 80 毫克就是醉酒驾驶，构成危险驾驶罪，吊销驾照、留下犯罪记录，五年内不能重新考取驾照。一两杯啤酒就可能超过 20 毫克。喝了酒，叫代驾、打车或者让没喝酒的人开。","tip":"","cost":{"money":"少","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq10-6","b":"social","s":10,"n":6,"t":"吃着头孢等药，绝对不要喝酒","p":"头孢类抗生素、甲硝唑等药物和酒精同时作用，可能引起双硫仑样反应：脸红、心慌、胸闷、血压下降，严重时会危及生命。正在用这类药，或者停药不到一周，酒桌上直接说明，任何人都不应该再劝。","tip":"「我这两天在吃头孢，喝一口都可能出事，真不能喝。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-7","b":"social","s":10,"n":7,"t":"同桌有人喝醉了，要有人照看，别留他一个人","p":"醉酒的人可能呕吐窒息、摔倒受伤、在路边受冻。让他侧躺，头偏向一边，防止呕吐物堵住气道；不要让他独自回家或独自睡在酒店；联系他的家人或可靠的朋友来接。叫不醒、呼吸异常、抽搐、呕吐带血，马上打 120。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"法条","hasRef":false},{"id":"rq10-8","b":"social","s":10,"n":8,"t":"醉不醉看喝了多少酒精，不看混没混着喝","p":"「先啤后白不会醉」「混着喝才容易醉」这类说法没有可靠依据。研究发现，啤酒和葡萄酒先喝哪个，对第二天宿醉的程度没有明显影响；真正决定醉不醉、伤不伤身的，是喝进去的酒精总量和喝的速度。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-9","b":"social","s":10,"n":9,"t":"没有「安全的饮酒量」，能少喝就少喝","p":"「小酌怡情」「每天一杯红酒保护心血管」的说法，近年被越来越多的研究质疑。世界卫生组织已明确表示，就健康而言不存在安全的饮酒水平，酒精是一类致癌物。应酬中真推不掉，就把量降到最低。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-10","b":"social","s":10,"n":10,"t":"被一轮轮敬酒时，可以「少量多次」，也可以找人帮你挡","p":"推不掉的场合，可以每次只抿一小口、用小杯；喝一口酒配一口水或汤；请同伴帮忙解释「他真不能喝」。实在顶不住，借口打电话、去洗手间离开一会儿，或者跟主人说明后提前离席。","tip":"「我酒量真不行，这杯我抿一口，心意到了，您见谅。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-11","b":"social","s":10,"n":11,"t":"女性在酒桌上被劝酒、被借酒骚扰，可以当场拒绝并保留证据","p":"借敬酒拉扯、搂抱、说带性暗示的话，属于性骚扰，不是「开玩笑」「活跃气氛」。可以明确拒绝、起身离开、请同伴陪同，事后记下时间、地点、在场的人，保留聊天记录。单位有义务预防和处置职场性骚扰，你可以向单位投诉，也可以报警或起诉。","tip":"「请您把手拿开，我不喜欢这样。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"新人"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq10-12","b":"social","s":10,"n":12,"t":"酒后别谈正事、别做决定、别发重要消息","p":"喝了酒判断力下降，容易拍胸脯答应做不到的事、说出平时不会说的话、在群里发错消息。酒桌上谈到的合作，第二天清醒后再确认；喝多了别给前任、领导、客户发消息，也别在网上发评论。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-13","b":"social","s":10,"n":13,"t":"不喝酒也能融入：以茶代酒，照样敬、照样聊","p":"不喝酒的人在酒桌上容易被冷落，但只要你同样起身敬茶、主动聊天、照顾同桌，大家很快就会接受。越来越多的人因为健康、开车、信仰不喝酒，酒桌的规矩也在变。真诚比酒量更打动人。","tip":"「我以茶代酒，敬王总一杯，祝您身体健康。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-14","b":"social","s":10,"n":14,"t":"「不喝就是不给面子」这类话，可以笑着化解","p":"劝酒的人把喝不喝和面子、感情、诚意绑在一起，你顺着他的逻辑去辩，往往越辩越被动。轻松地把话题从「喝不喝」转到「感情」本身，或者自嘲一下，场面就过去了。","tip":"「咱俩的感情哪是一杯酒能装下的？这杯我抿一口，剩下的留着下次。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-15","b":"social","s":10,"n":15,"t":"领导敬你酒，起身接，能喝多少喝多少","p":"领导或长辈主动敬你，是一种认可。马上起身、双手端杯迎上去，碰杯时杯口低一点，说一句感谢的话。喝多少看自己，不必为了表忠心一口闷；领导真正在意的通常是你的态度，而不是喝了多少。","tip":"「谢谢领导关心，我一定好好干。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-16","b":"social","s":10,"n":16,"t":"敬酒词简短，别借敬酒逼人表态","p":"敬酒时长篇大论，全桌人举着杯子等你，很累；借敬酒逼对方答应合作、借钱、帮忙，对方答应了也是被架上去的，酒醒后未必认账。敬酒就是表达心意，一两句话足矣。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq10-17","b":"social","s":10,"n":17,"t":"请客选酒看客人习惯，别为了面子上来路不明的「特供」","p":"请客上酒，可以先问客人平时喝什么、能喝多少。宁可上一瓶价格中等、渠道可靠的酒，也别为了撑场面买来路不明的「内供」「特供」「原浆」，假酒伤身，被识破了也丢面子。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"官方文件","hasRef":true},{"id":"rq10-18","b":"social","s":10,"n":18,"t":"劝别人戒酒、少喝，用关心而不是说教","p":"家人、朋友喝酒太多，直接说「你再喝就废了」常常适得其反。说具体的担心和具体的事实，比如「上次你喝完第二天头疼了一整天」「体检报告里肝功能有箭头」，并且陪他一起做改变，比如一起运动、聚会时主动帮他挡酒。","tip":"「我是真担心你的身体，下次聚会我帮你挡，咱们少喝点。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-1","b":"social","s":11,"n":1,"t":"在哪过年、待几天，提前和伴侣、双方父母商量好","p":"已婚或稳定恋爱的人，最容易为「回谁家过年」吵架。提前一两个月商量：轮流、一家过年三十一家过初一、或者把两边父母接到一起。定下来以后早点告诉双方父母，让他们有心理准备，别临到年根才通知。","tip":"「今年咱们在你家过三十，初二去我家，明年反过来，你看行吗？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-2","b":"social","s":11,"n":2,"t":"拜年先近后远、先长后幼，去不了的长辈打个电话","p":"多数地方的习惯是先给自家长辈拜年，再去近亲、远亲、老邻居、老师家。具体哪天去谁家，各地讲究不同，问父母最准。实在去不了的长辈，单独打个视频或电话，比一条群发的祝福有心得多。","tip":"「二姨，过年好！今年没能回去看您，给您拜个年，身体还好吧？」","cost":{"money":"少","time":"中","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq11-3","b":"social","s":11,"n":3,"t":"压岁钱看关系和当地行情，亲戚之间大体对等","p":"给亲戚家孩子的压岁钱，金额看亲疏和当地习惯，兄弟姐妹之间一般互给对等的数，免得一方吃亏。不确定给多少，问问父母往年给多少。孩子收到的压岁钱，父母可以帮着保管，但要跟孩子说清楚这是他的钱。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"金钱","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-4","b":"social","s":11,"n":4,"t":"工作以后，过年给父母包个红包","p":"工作后过年给父母一个红包，金额不重要，重要的是让父母知道你长大了、能照顾他们了。很多父母会推辞，甚至偷偷存起来以后再给你，但收到时的那份开心是真的。也可以换成给父母买件衣服、安排一次体检。","tip":"「爸妈，这是我的一点心意，你们拿着买点喜欢的。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-5","b":"social","s":11,"n":5,"t":"被催婚、催生、问工资，准备几句温和的「挡箭牌」","p":"亲戚问「什么时候结婚」「怎么还不要孩子」「一个月挣多少」，大多是习惯性的寒暄，未必真想知道答案。准备几句不伤人的回答，笑着说完马上把话题抛回去或转开，比当场辩论、甩脸色效果好得多。","tip":"「在努力了，有好消息第一个告诉您！您家小明今年考得怎么样？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"体面","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-6","b":"social","s":11,"n":6,"t":"被拿来和「别人家的孩子」比较，别争，转话题","p":"「你看人家小王都买房了」「你表妹孩子都上小学了」，这类比较在饭桌上很常见。当场反驳只会把气氛搞僵，长辈也不会因此改变看法。笑着说一句「人家确实厉害」，然后转到别的话题；真有压力，私下找父母说你的想法。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-7","b":"social","s":11,"n":7,"t":"年夜饭进厨房搭把手，别只等着开饭","p":"一顿年夜饭，往往是家里一两个人从早忙到晚。择菜、洗碗、摆碗筷、收拾桌子，这些顺手的活主动接过来。去对象家或长辈家过年，更要主动问「有什么我能帮忙的」，哪怕被推出厨房，这份心意也会被记住。","tip":"「阿姨，我来洗碗，您歇会儿。」","cost":{"money":"0","time":"中","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-8","b":"social","s":11,"n":8,"t":"亲戚间打麻将带点彩头不违法，以营利为目的的赌博才违法","p":"按照公安机关的执法规定，不以营利为目的，亲属之间带有少量财物输赢的打麻将、打扑克等娱乐活动，不予处罚。但如果输赢金额大、在外面组局抽水、和陌生人一起玩、通过网络平台下注，就可能构成赌博违法甚至犯罪。不想玩的，可以说「我不太会」，…","tip":"","cost":{"money":"少","time":"中","will":"否","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq11-9","b":"social","s":11,"n":9,"t":"微信拜年单独发、带上称呼，别把群发当心意","p":"网上复制来的长篇祝福、明显是群发的拜年图，收到的人很少会认真看，有的人甚至不回。给重要的人单独发，开头叫一声称呼，加一句和对方有关的话，比十张拜年图都有用。","tip":"「刘老师，新年好！今年您带我们做的那个课题我收获特别大，祝您新年身体健康、万事顺意。」","cost":{"money":"0","time":"中","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-10","b":"social","s":11,"n":10,"t":"不回家过年，提前告诉父母，寄年货、视频拜年","p":"因为工作、路远、买不到票不能回家，越早告诉父母越好，让他们有心理准备，别到年前一两天才说。提前寄一箱年货回去，除夕晚上和全家视频，陪父母多聊一会儿。年后有机会补一次回家。","tip":"「爸妈，今年单位值班回不去了，年货给你们寄了，三十晚上我们视频一起吃年夜饭。」","cost":{"money":"少","time":"少","will":"些","gain":"中","lens":"关系","who":"异乡"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-11","b":"social","s":11,"n":11,"t":"带孩子去别人家拜年，管好孩子别乱翻乱拿","p":"小孩子去亲戚家，容易翻抽屉、乱拿东西、吵闹。出门前跟孩子讲好规矩：拿东西前先问主人、不进别人卧室、收到红包要说谢谢。孩子弄坏了东西，大人要主动道歉、赔偿，别说「孩子还小」。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-12","b":"social","s":11,"n":12,"t":"大年三十别翻旧账，家里的矛盾等节后再谈","p":"一年难得团圆，最怕在年夜饭桌上爆发争吵：老人偏心、兄弟分家产、婆媳不和。这些事过年时说，情绪容易失控，还会让全家都过不好年。真的有矛盾，节后找时间、找合适的人一起坐下来谈。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq11-13","b":"social","s":11,"n":13,"t":"燃放烟花爆竹，先查当地是不是禁放区","p":"很多城市划定了烟花爆竹禁放区或限放时段，在禁放区燃放会被罚款。允许燃放的地方，也要远离人群、车辆、易燃物，不在阳台和楼道里放，不让小孩单独点火，不买没有合格标识的产品。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-14","b":"social","s":11,"n":14,"t":"在红包群里发红包，量力而行，工作群里慎发慎抢","p":"家族群、朋友群过年发红包图个热闹，大家都发一点、抢一点，不必攀比金额。工作群里，下属给领导发、供应商在客户群里发大额红包，就可能变味；公职人员收受管理服务对象的电子红包，属于违纪。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"小","lens":"自保","who":"体制内,管理"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-15","b":"social","s":11,"n":15,"t":"去长辈家拜年带点年货，别只带一张嘴","p":"过年去长辈家，带一箱水果、一盒点心、一桶好油，或者一份老人用得上的东西。不必贵，关键是别空着手。给独居老人拜年，可以顺手看看家里有没有什么需要修的、缺的。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq11-16","b":"social","s":11,"n":16,"t":"返程前跟长辈好好道别，留一点「过年的余温」","p":"假期结束回城前，跟父母和身边的长辈认真道个别，帮父母把家里收拾好，给家里的老人留点钱或常用药，约好下次回来的时间。父母常常在你走后好几天都还在念叨，这份道别对他们很重要。","tip":"「妈，我五一再回来看你们，有啥事随时给我打电话。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":"异乡"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-17","b":"social","s":11,"n":17,"t":"过年借钱的开口，可以等节后再说","p":"过年饭桌上亲戚当着一屋子人开口借钱，你当场拒绝伤面子，当场答应又后悔。可以先说「这事咱们节后单独聊」，把决定从热闹的场合挪到私下，再按第 4 章、第 12 章的方法想清楚借不借、借多少、怎么写借条。","tip":"「这事我得跟家里商量一下，过完年我给你回话。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq11-18","b":"social","s":11,"n":18,"t":"春节值班、加班的人，节后记得说声辛苦","p":"医生、警察、保安、快递员、同事里过年值班的人，替大家守住了节日。作为同事或领导，节后带点家乡特产给值班的人、说一句「辛苦了」；作为部门负责人，排班时尽量轮流，别总让同一批人值班。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"关系","who":"管理"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq12-1","b":"social","s":12,"n":1,"t":"亲戚借钱先问用途：救急可以帮，填窟窿要谨慎","p":"看病、孩子上学、家里遭灾，这是救急，能帮就帮。还网贷、炒股补仓、做没谱的生意、赌博输了钱，借出去的钱很可能是填一个越来越大的窟窿，帮了这次还有下次。问清用途不是多管闲事，而是决定借不借的依据。","tip":"「借钱没问题，你跟我说说是遇到啥事了，我看看怎么帮最合适。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq12-2","b":"social","s":12,"n":2,"t":"只借你能承受「要不回来」的数","p":"亲戚之间借钱，不还、拖着还的情况很常见，真要上法院又撕破脸。借之前问自己：这笔钱要是一直要不回来，我和家人的生活会不会受影响？会，就只借一部分，或者换成别的帮助方式。动用房贷、养老钱、孩子学费去借给别人，风险太大。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq12-3","b":"social","s":12,"n":3,"t":"借钱写借条、走转账，借条上写清七样东西","p":"哪怕是亲兄弟，借钱也要留凭证。借条写清：出借人和借款人的姓名、身份证号，借款金额（大写和小写），借款用途，还款日期，是否有利息、利率多少，借款人亲笔签名和日期。钱通过银行转账或微信、支付宝转账给借款人本人，并备注「借款」，不要给现金。","tip":"「咱们写个条，不是信不过你，是怕以后家里人说不清。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq12-4","b":"social","s":12,"n":4,"t":"没写利息就是无息，约定利息也有法定上限","p":"自然人之间借钱，借条上没约定利息或约定不明确的，视为没有利息，事后再要利息很难。要约定利息，利率不能超过合同成立时一年期贷款市场报价利率（LPR）的四倍，超过部分法院不支持。亲戚之间借钱，多数情况下无息或低息就好，别让借钱变成放贷。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq12-5","b":"social","s":12,"n":5,"t":"别轻易给亲戚做担保，签了字就可能替他还钱","p":"亲戚贷款买车、做生意，请你在担保人一栏签个字，说「就是走个形式」。但保证人的责任是实打实的：债务人还不上时，债权人可以找你还钱；如果约定的是连带责任保证，债权人甚至可以不先找债务人、直接找你。担保之前问自己：我愿意替他还这笔钱吗？","tip":"「借钱我可以考虑借一部分，担保这个我家里定过规矩，谁都不签。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq12-6","b":"social","s":12,"n":6,"t":"借出去的钱，到期没还就及时催，催款记录要留着","p":"借钱的诉讼时效一般是三年，从约定的还款日之后起算；没约定还款日的，可以随时要求对方还，催了之后给对方一个合理的期限。拖着不催，时间一长，法律上可能就难以支持了。用微信、短信催款，对方回复「过段时间还」，这些记录本身就是证据，…","tip":"「之前借你的那笔钱到期了，你看什么时候方便还？我这边也有用处。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq12-7","b":"social","s":12,"n":7,"t":"亲戚托你找工作、找关系，可以帮着打听，别打包票","p":"亲戚以为你在大城市、在大单位，一定能帮孩子安排工作。你能做的，通常是提供招聘信息、帮着改简历、介绍一下行业情况、内推一份简历。能不能录用要看对方自己。一开始就把话说清楚，别为了面子答应「包在我身上」。","tip":"「我们公司在招人，我可以帮他内推，面试得靠他自己，我也左右不了结果。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq12-8","b":"social","s":12,"n":8,"t":"亲戚来家里住，事先说好住多久、怎么分担","p":"亲戚来城里看病、找工作、送孩子上学，要借住在你家，住三五天是人情，住三五个月就容易起摩擦。来之前说清楚大概住多久、作息怎么安排、生活费要不要分担。住得久的，可以帮着在附近找短租房。","tip":"「来住没问题，就是家里地方小，住个一周左右，之后我帮你在附近找个合适的地方。」","cost":{"money":"少","time":"中","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq12-9","b":"social","s":12,"n":9,"t":"和亲戚合伙做生意，先签书面协议，账目公开","p":"亲戚之间合伙，开始时大家都讲感情，赚了钱怎么分、亏了钱谁承担、有人想退出怎么办，往往没人提。书面协议写清出资额、分红比例、各自负责什么、账目怎么管、退出和散伙的规则。账目定期公开，大额支出双方都知道。","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"金钱","who":"生意"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq12-10","b":"social","s":12,"n":10,"t":"多年不联系的亲戚突然热情推销、拉投资，先警惕","p":"平时不来往的远房亲戚，忽然频繁联系、嘘寒问暖，接着推荐你买保健品、加入某个「项目」、投资某种高回报理财，很可能是他自己陷入了传销或非法集资，正在发展下线。亲情是真的，但产品和项目要按陌生人的标准去核实。","tip":"「我最近手头紧，不考虑这些，你自己也要多留个心眼。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq12-11","b":"social","s":12,"n":11,"t":"亲戚之间有矛盾，请双方都信得过的长辈来调解","p":"兄弟姐妹、叔伯之间为钱、为老人、为房子闹僵，双方直接谈常常越谈越崩。请一位双方都尊重的长辈或亲戚出面，把各自的想法摆出来，往往比较容易找到台阶。调解也可以找村委会、居委会的人民调解员，调解协议有一定的法律效力。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"中","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq12-12","b":"social","s":12,"n":12,"t":"分遗产别只靠「口头说过」，看遗嘱、看法定继承顺序","p":"老人去世后，兄弟姐妹之间最容易为房子、存款反目。没有遗嘱的，按法定继承：第一顺序是配偶、子女、父母，平均分配为原则，尽了主要赡养义务的可以多分。有遗嘱的，按遗嘱办；几份遗嘱内容冲突的，以最后一份为准，公证遗嘱不再有优先效力。…","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq12-13","b":"social","s":12,"n":13,"t":"兄弟姐妹之间赡养老人，把分工和费用说清楚","p":"父母年老，谁出钱、谁出力、谁陪看病、谁接到家里住，最好兄弟姐妹坐下来商量清楚，写个简单的分工。离得近的多出力，离得远的多出钱，都是贡献。不要因为「谁多分了家产」就推卸赡养责任，赡养是法定义务，不能用放弃继承权来抵。","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq12-14","b":"social","s":12,"n":14,"t":"亲戚帮你带孩子，给生活费也给心意","p":"老人、姐妹、亲戚帮你带孩子，花的是他们的时间和精力。哪怕对方说不要钱，孩子的吃穿用度你要承担，逢年过节再表示一下。带孩子的方式有分歧时，商量着来，别把对方当保姆一样指挥。","tip":"「妈，这是孩子这个月的开销，您带孩子太辛苦了，周末我来带，您歇两天。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq12-15","b":"social","s":12,"n":15,"t":"亲戚请你代买代购，钱款先说清楚","p":"亲戚让你从城里、从国外带东西，常常默认你会「先垫着」，有时就一直没给。小东西当作心意送也无妨；贵一点的，买之前就说好价格，请对方先转钱。代购涉及海关限额的，超额要申报纳税，别为了帮亲戚省钱冒走私风险。","tip":"「这个包大概一万二，你先转我，我到了就去买，小票也给你。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq12-16","b":"social","s":12,"n":16,"t":"对借钱不还的亲戚，不必再借，但面子上的礼数可以保留","p":"有的亲戚借了钱一拖再拖，再开口时理直气壮。对这样的人，钱不必再借；过年走动、红白事随礼这些礼数照常，不在亲戚面前到处说他欠钱不还。保持表面的平和，是给其他亲戚和自己父母留面子。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq12-17","b":"social","s":12,"n":17,"t":"亲戚面前别炫富，也别哭穷","p":"在亲戚面前讲自己挣了多少、买了什么，很容易引来借钱、托办事和背后议论；反过来天天哭穷，又会让人觉得你在提防他们。日子过得好就安静地过，被问到时说「还行，够用」，把重点放在关心对方身上。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq12-18","b":"social","s":12,"n":18,"t":"和亲戚的距离，可以由你自己决定","p":"血缘让你们成为亲戚，但没有规定你必须和每一位亲戚都亲密。对你好的、互相尊重的亲戚，多来往；总是索取、指责、搬弄是非的亲戚，保持基本的礼数即可。你有权根据对方的行为调整关系的远近。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-1","b":"social","s":13,"n":1,"t":"回应父母的担心，而不是回应他们的措辞","p":"「你天天熬夜早晚要出事」「这么大了还不找对象，以后谁管你」，话难听，底下是担心。直接反驳措辞，就会吵起来；回应背后的担心，告诉父母你知道、你有数、你在怎么做，他们往往就安下心来了。","tip":"「我知道您是担心我身体，我最近都尽量十二点前睡，周末也去游泳了。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-2","b":"social","s":13,"n":2,"t":"定个固定的时间给父母打电话","p":"在外地的子女，很多是「想起来才打」，一忙就是一两个月。固定一个时间，比如每周日晚上视频，父母会提前等着，也就不会总担心你出什么事。聊天不用每次都汇报大事，问问他们吃了什么、身体怎么样、最近和谁来往，就是陪伴。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"异乡"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq13-3","b":"social","s":13,"n":3,"t":"人生大事提前告诉父母，但决定权在你","p":"换工作、换城市、结婚、买房这些大事，提前告诉父母，听听他们的意见，是尊重；最后怎么选，由你来定，也由你来承担后果。先说你的考虑和计划，再听父母的顾虑，能采纳的采纳，不能采纳的说明原因。","tip":"「这事我想了挺久，跟您说说我的打算。您有啥担心的，我听听。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-4","b":"social","s":13,"n":4,"t":"被催婚时，给父母一个能对亲戚说出口的说法","p":"父母催婚，一部分是担心你，一部分是在亲戚邻居面前「交不了差」。跟父母说清楚你的态度和计划，同时给他们一个对外的说法，比如「孩子在忙事业，心里有数」。父母有了台阶，催的频率往往就会降下来。","tip":"「我不是不想结，是想找个合适的。亲戚问起来，您就说我在忙工作、在留意，别的我来应付。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-5","b":"social","s":13,"n":5,"t":"父母信保健品、养生偏方，耐心说，别嘲笑","p":"保健食品不是药物，不能代替药物治疗疾病，包装上必须标注这句提示。很多老人被「免费讲座」「专家义诊」吸引，买了高价保健品，甚至停了该吃的药。嘲笑只会让他们更信那些「对他们好」的推销员。带父母看包装上的提示、陪他们去正规医院复查，…","tip":"「妈，您看这上面写着不能代替药物，您的降压药千万别停。这东西要真那么神，医院早就用了。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-6","b":"social","s":13,"n":6,"t":"帮父母的手机装好防诈工具，约定「转账前先给我打电话」","p":"老人是电信诈骗、养老诈骗的重点目标：冒充子女要钱、冒充公检法说涉案、以「养老项目」「以房养老」骗钱。帮父母装上国家反诈中心 App，开启来电预警；和父母约定一条家规：凡是要转账、要说验证码、要去银行办大额业务，先给你打电话。","tip":"「爸，以后不管谁打电话让您转钱，哪怕说是我，您都先挂了，再打我这个号码确认。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq13-7","b":"social","s":13,"n":7,"t":"教父母用智能手机，写下步骤，别嫌他们学得慢","p":"网上挂号、扫码乘车、视频通话，对年轻人是本能，对老人是新知识。教的时候放慢节奏，一次只教一件事，让他们自己动手操作，再把步骤写在纸上或录成短视频。被问到第三遍时，也别说「我都说过了」。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-8","b":"social","s":13,"n":8,"t":"给父母钱，不如帮他们把钱花在实处","p":"很多父母收了钱舍不得花，攒起来又给了子女，或者被推销员骗走。与其只给现金，不如直接安排：带他们做一次全面体检、换一台好用的热水器、给浴室装扶手和防滑垫、报一个老年大学的课程。钱照样给，但大件的事情你来办。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-9","b":"social","s":13,"n":9,"t":"带父母定期体检，关注血压、血糖和慢性病","p":"很多父母身体不舒服不愿说，怕给子女添麻烦。每年带他们做一次体检，看懂报告里的箭头，有异常陪着去复查。高血压、糖尿病等慢性病按时吃药、定期复查，比出了事再救重要得多。65 岁以上的老人，很多地方的社区卫生服务中心每年提供一次免费健康体检。","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-10","b":"social","s":13,"n":10,"t":"父母想回老家、想让你考公，先听完他们的理由","p":"父母希望你回老家、考编制、找个「稳定的工作」，背后是他们对不确定的担心，以及希望你离他们近一点。先听完，再说你的打算和理由，包括你为这份不确定准备了什么。即使最后不按他们说的办，也让他们感受到你认真考虑过。","tip":"「我明白你们是想让我稳当点，我也想过，在这边发展机会多，我每年都会多回来几趟。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-11","b":"social","s":13,"n":11,"t":"成年后和父母要有边界：手机、钱包和小家庭的决定","p":"父母爱你，但成年人的隐私、财务和小家庭的决定，应该由你自己做主。父母翻看你的手机、要求掌管你的工资卡、替你决定和伴侣怎么过日子，可以温和但明确地说不。边界清楚了，关系反而更轻松。","tip":"「妈，我知道您是关心我，工资我自己管，有需要我肯定跟您商量。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq13-12","b":"social","s":13,"n":12,"t":"父母偏心，可以说出你的感受，但别逼他们承认","p":"父母对兄弟姐妹偏心，很多是无意识的，也可能和他们自己的经历、观念有关。与其指责「你就是偏心」，不如具体说出你的感受和需要：「哥结婚你们出了首付，我结婚的时候也希望你们能帮一点」。说出来不一定改变结果，但能避免你一直憋着。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq13-13","b":"social","s":13,"n":13,"t":"趁父母头脑清楚，早点聊养老、监护和财产安排","p":"很多家庭直到父母失智、重病才发现：存折密码不知道、房产怎么处理没说过、谁来做医疗决定没人能定。趁父母身体和头脑都好，找个轻松的时机聊：想在哪养老、生病了希望谁照顾、要不要立遗嘱。法律允许成年人事先书面指定自己的监护人（意定监护），…","tip":"「爸，咱们把这些事提前理一理，不是咒您，是怕万一哪天我们手忙脚乱。」","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":true,"ev":"法条","hasRef":false},{"id":"rq13-14","b":"social","s":13,"n":14,"t":"父母离婚、再婚，是他们自己的权利","p":"老年人的婚姻自由受法律保护，子女不得干涉父母离婚、再婚和婚后的生活。担心的是财产问题，可以建议父母做婚前财产约定，而不是阻止他们找伴。父母晚年有人陪伴，往往比子女隔三岔五的电话更能让他们过得好。","tip":"「您开心最重要。财产上咱们按规矩做个约定，对谁都好。」","cost":{"money":"0","time":"少","will":"是","gain":"中","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq13-15","b":"social","s":13,"n":15,"t":"老人帮带孩子有分歧，先抓安全和健康，其余可以放宽","p":"隔代育儿最常见的冲突：老人喂饭追着喂、孩子穿得太多、用老办法退烧、什么都替孩子做。原则问题坚持：比如安全座椅、疫苗、用药、不打孩子；其他问题可以放宽，比如零食多吃一点、睡前多看一会儿动画片。坚持原则时，用医生、专业机构的建议说话，…","tip":"「妈，医生说孩子发烧不能捂汗，咱们按医生说的来。其他的您看着办就行。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-16","b":"social","s":13,"n":16,"t":"接父母来城里住，先帮他们找到自己的圈子","p":"父母从老家来到陌生的城市，没有熟人、听不懂方言、不知道去哪买菜，很容易孤独，甚至想回去。帮他们找到小区里的广场舞队、老年活动中心、附近的菜市场和公园，介绍几个同龄的邻居，他们才能真正住下来。","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"中","lens":"关系","who":"异乡"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-17","b":"social","s":13,"n":17,"t":"父母做错了事，私下说，给他们留面子","p":"父母也会犯错：被骗了钱、说错了话、做了让你难堪的事。当着亲戚、伴侣、孩子的面数落父母，他们会觉得在子女面前丢了尊严，往往更加嘴硬。私下说，先说「我知道您也是好意」，再说问题和解决办法。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-18","b":"social","s":13,"n":18,"t":"爱和感谢，可以做出来，也可以试着说出来","p":"很多中国家庭不习惯说「我爱你」「谢谢你」，把爱藏在做饭、打钱、唠叨里。行动很重要，但有些话说出来，父母会记很久。不一定要说「我爱你」，可以说「这些年辛苦你们了」「我现在挺好的，是你们教得好」。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-19","b":"social","s":13,"n":19,"t":"和父母有过很深的伤害，可以先照顾好自己","p":"不是所有父母都会给孩子温暖。长期打骂、贬低、控制、利用，会在成年后留下很深的影响。和这样的父母相处，可以减少见面频率、减少深入的交流，必要时寻求心理咨询的帮助。孝顺是美德，但不要求你一再把自己送回伤害里。","tip":"","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq13-20","b":"social","s":13,"n":20,"t":"父母老了，多陪伴比多说教更重要","p":"父母年纪越大，越需要的不是道理和钱，而是有人陪着说话、陪着散步、听他们讲重复了无数遍的往事。陪父母吃一顿饭、带他们出去走走，对他们来说比什么礼物都珍贵。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-1","b":"social","s":14,"n":1,"t":"看一个人，看他怎么对待「对他没有用」的人","p":"恋爱初期，人都会展示最好的一面。更真实的信号是他怎么对待服务员、外卖员、自己的父母、提起前任时的态度、和你意见不合时的反应、遇到挫折时怎么处理情绪。这些细节，比他对你说的情话更能预测婚后的样子。","tip":"","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"自保","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-2","b":"social","s":14,"n":2,"t":"第一次见对方家长：礼物得体、穿着整洁、主动帮忙、不评价对方家里","p":"去之前问伴侣：家里有哪些人、父母喜欢什么、有什么忌讳、当地见家长有什么讲究。带一份不太贵但用心的礼物，穿得整洁大方。见面主动打招呼、叫人，吃饭时帮忙摆碗筷、饭后主动收拾。不评价对方家的房子、装修、饭菜，聊天多问对方父母擅长或喜欢的事。","tip":"「叔叔阿姨好，第一次来，给您二老带了点茶叶，听说叔叔爱喝茶。」","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq14-3","b":"social","s":14,"n":3,"t":"彩礼和嫁妆，先由两家坦诚商量，参考当地习俗和双方经济能力","p":"彩礼给多少、嫁妆陪多少、彩礼最后归谁，最容易让两家人心生芥蒂。两个年轻人先商量好底线，再由双方父母沟通；参考当地一般水平和双方家庭的实际能力，别为了面子掏空家底、背上债务。很多家庭的做法是彩礼大部分随嫁妆带回小家庭，用于两人的生活。","tip":"","cost":{"money":"多","time":"中","will":"是","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-4","b":"social","s":14,"n":4,"t":"彩礼的法律规则：没登记、登记但没共同生活，一般可以要求返还","p":"按照最高人民法院的规定，双方没有办理结婚登记，或者办了登记但确实没有共同生活，或者婚前给付导致给付人生活困难（后两种以离婚为条件），请求返还彩礼的，法院应当支持。已经登记并共同生活后离婚的，一般不支持返还；…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq14-5","b":"social","s":14,"n":5,"t":"节日红包、日常开销一般不算彩礼，分手后很难要回","p":"恋爱期间在生日、情人节、520 等纪念日发的价值不大的红包和礼物，为表达感情的吃饭、看电影、旅行等日常消费，法院一般不认定为彩礼，分手后要求返还通常得不到支持。大额转账、给对方买车买房，最好写清楚是赠与、借款还是以结婚为目的的给付。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq14-6","b":"social","s":14,"n":6,"t":"婚前了解对方的债务：看征信报告，大额负债要说清","p":"婚前一方的个人债务，原则上是个人债务；但婚后以个人名义借的钱用于家庭生活，或者双方共同签字、事后追认的，可能成为夫妻共同债务。结婚前坦诚交换一下各自的负债情况，包括车贷、网贷、信用卡、给别人做的担保。个人信用报告每人每年可以免费查两次，…","tip":"「结婚前咱们把各自的账摊开说说吧，有房贷车贷都没事，就怕有不知道的。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq14-7","b":"social","s":14,"n":7,"t":"婚前买房、父母出资，钱从哪来、写谁的名字要提前想清","p":"房子是婚姻里最大的一笔财产，也是离婚纠纷的焦点。婚前一方全款买的房，一般是个人财产；婚后父母为子女买房出资，没有明确约定的，离婚时可能按共同财产或结合出资情况处理，最高法近年对此有细化规定。父母出资的，可以写一份书面说明，…","tip":"","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq14-8","b":"social","s":14,"n":8,"t":"结婚登记的规矩在变，去之前查一下当地婚姻登记机关的要求","p":"2025 年修订的《婚姻登记条例》施行后，内地居民办理结婚登记，一般凭本人身份证和签字声明即可，不再要求户口簿，并推行在一方常住户口所在地或经常居住地都可以办理的「全国通办」。具体办理地点、预约方式和材料，以当地民政部门的公告为准。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-9","b":"social","s":14,"n":9,"t":"有重大疾病要在登记前如实告诉对方，婚检建议做","p":"婚前医学检查是自愿的，很多地方免费提供，能发现一些影响婚育的疾病。法律规定，一方患有重大疾病的，应当在结婚登记前如实告知另一方；不如实告知的，对方可以在知道之日起一年内请求法院撤销婚姻。隐瞒换来的婚姻，随时可能被撤销。","tip":"","cost":{"money":"少","time":"少","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-10","b":"social","s":14,"n":10,"t":"婚礼预算两家一起定，别为了排场借钱办婚礼","p":"酒店、婚庆、婚纱照、钻戒、蜜月，一项项加起来，很容易超出预算。先定一个总预算和资金来源，再按优先级分配；双方父母各出多少、礼金怎么分配，也提前说好。借钱、刷信用卡办一场婚礼，婚后第一件事就是还债，往往埋下争吵的种子。","tip":"","cost":{"money":"多","time":"中","will":"些","gain":"大","lens":"金钱","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-11","b":"social","s":14,"n":11,"t":"改口、敬茶这些仪式，提前了解，当天照做就好","p":"很多地方婚礼上有给公婆、岳父母敬茶改口的环节，长辈给「改口费」红包。改口叫「爸」「妈」时，声音大一点、笑着叫，长辈会很开心。不太习惯也没关系，当天按流程走，婚后慢慢适应。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq14-12","b":"social","s":14,"n":12,"t":"恋爱中别帮对方贷款、别借大额钱，网上认识的更要警惕","p":"对方以创业、家人生病、资金周转为由，让你借钱、用你的名字办网贷、帮他做担保，是恋爱纠纷和诈骗中最常见的开头。网上认识、从未见面或很少见面的对象，带你「投资」「做任务」「买彩票内幕」，几乎可以确定是杀猪盘。真心爱你的人，不会让你背债来证明爱。","tip":"「钱的事我们都不碰，等我们稳定了再一起规划。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq14-13","b":"social","s":14,"n":13,"t":"查手机、管社交、限制见朋友，不是爱，是控制","p":"恋爱中有些「在乎」会慢慢变成控制：要求随时报备位置、翻看聊天记录、不许你和异性甚至同性朋友见面、贬低你的家人朋友、让你和他们疏远。这些往往是更严重的情感操控和暴力的前兆。感觉自己越来越不敢做自己，就该停下来想一想这段关系。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq14-14","b":"social","s":14,"n":14,"t":"恋爱中动手，一次都不能原谅；同居伴侣也受反家暴法保护","p":"打人、推搡、掐脖子、摔东西威胁，不是「一时冲动」，暴力往往会重复并升级。家庭成员以外共同生活的人之间的暴力，也参照反家庭暴力法处理：可以报警，公安机关可以出具告诫书；可以向法院申请人身安全保护令，禁止对方骚扰、跟踪、接近你。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq14-15","b":"social","s":14,"n":15,"t":"分手要体面：说清楚、不纠缠、不散播对方隐私","p":"决定分手，最好当面或打电话说清楚，不要突然消失。分手后不反复纠缠、不到对方单位和家里闹、不在网上挂人。散布对方的私密照片、聊天记录、隐私信息，侵犯隐私权，可能被治安处罚，情节严重的可能构成犯罪。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-16","b":"social","s":14,"n":16,"t":"相亲第一次见面：守时、礼貌、聊兴趣，别一上来就查户口","p":"相亲第一次见面，最让人反感的是一上来问房子几套、存款多少、父母退休金多少。这些可以在关系有进展时再坦诚沟通。第一次见面聊工作、兴趣、生活习惯，看看两个人是否聊得来。结束时无论有没有感觉，都礼貌道别；没有意向的，之后委婉说明，不要直接拉黑。","tip":"「今天聊得挺开心的，不过我感觉我们更适合做朋友，祝你早点遇到合适的人。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"体面","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-17","b":"social","s":14,"n":17,"t":"双方父母意见冲突时，各自和自己的父母沟通","p":"彩礼、婚房、婚礼形式上，两家父母意见不合时，最忌讳让伴侣去和你的父母硬碰硬。你负责和你的父母沟通，伴侣负责和他（她）的父母沟通，两个人先在私下达成一致，再一起面对双方家长。","tip":"（对自己父母）「这是我们俩商量好的，您要是有意见跟我说，别去为难她。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq14-18","b":"social","s":14,"n":18,"t":"恋爱期间的大额转账，写清是借款还是赠与","p":"恋爱中替对方还信用卡、给对方转钱买车、出钱装修对方的房子，分手后最常见的争议是：这到底是送的还是借的？转账时备注「借款」，或者在聊天记录里明确说明，日后才有据可依。真心想送的，也可以写明「赠与」，免得对方日后不安。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-19","b":"social","s":14,"n":19,"t":"婚前财产协议不伤感情，伤感情的是事后说不清","p":"夫妻可以书面约定婚前和婚后财产归各自所有、共同所有或部分共同所有，约定对双方有法律约束力。一方婚前有房产、股权、家族企业，或者双方收入差距很大的，做一份财产约定，能减少日后的猜疑。提议时把重点放在「把账理清楚」，而不是「防着你」。","tip":"「我们把各自的东西写清楚，以后不管怎样，谁都不用担心被误会。」","cost":{"money":"少","time":"中","will":"是","gain":"中","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-20","b":"social","s":14,"n":20,"t":"异地恋要有共同的时间表：什么时候见面、什么时候结束异地","p":"异地恋最消耗人的，是看不到尽头。两个人商量一个大致的时间表：多久见一次面、谁去看谁、多久以后谁搬去哪个城市。有了共同的目标，等待就有了意义。平时固定视频的时间，分享日常小事，比偶尔的长篇大论更能维系感情。","tip":"","cost":{"money":"少","time":"中","will":"是","gain":"中","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-21","b":"social","s":14,"n":21,"t":"带孩子再婚，先让孩子慢慢接受，别急着要求叫「爸妈」","p":"重组家庭里，孩子往往需要很长时间接受继父母，强迫改口只会引起抵触。让孩子按自己舒服的方式称呼，继父母多陪伴、少管教，管教主要由亲生父母负责。孩子和另一方亲生父母的联系，也要尊重和保留。","tip":"","cost":{"money":"0","time":"多","will":"是","gain":"大","lens":"关系","who":"婚恋,父母"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq14-22","b":"social","s":14,"n":22,"t":"婚姻不是任务，晚一点、不结都可以是选择","p":"「到年纪了就该结婚」是很多人被推着走的原因。婚姻是一个需要两个人都愿意经营的长期承诺，为了应付父母、为了不被议论而仓促结婚，代价往往比单身更大。想清楚自己要什么样的生活，再决定要不要结、什么时候结、和谁结。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"中","lens":"自保","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-1","b":"social","s":15,"n":1,"t":"夫妻先站在一起，再一起面对双方父母","p":"婆媳矛盾、翁婿矛盾里，最伤婚姻的往往不是父母，而是夹在中间那个人的态度：在父母面前附和父母，在伴侣面前附和伴侣，最后两头都不信任你。遇到分歧，夫妻俩关起门先商量出一个共同的立场，再统一对外。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-2","b":"social","s":15,"n":2,"t":"各自的父母各自沟通，别让伴侣去当「坏人」","p":"婆婆插手太多，由丈夫去说；岳父母要求过分，由妻子去说。自己的父母对自己的孩子更宽容，同样一句话，从儿子嘴里说出来是「孩子不懂事」，从儿媳嘴里说出来就是「儿媳妇不孝顺」。把对外沟通的压力留给有血缘的那一方。","tip":"（丈夫对母亲）「妈，孩子怎么带我们俩商量过了，您别跟她说了，有意见冲我来。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-3","b":"social","s":15,"n":3,"t":"能分开住就分开住，保持「一碗汤的距离」","p":"两代人生活习惯、作息、育儿观念差别很大，住在一个屋檐下，小摩擦天天有。条件允许的话，住得近但分开住：走过去不远，汤送过去还是热的，各自又有自己的空间。必须同住的，约定好各自的房间、家务和开销。","tip":"","cost":{"money":"多","time":"少","will":"否","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-4","b":"social","s":15,"n":4,"t":"老人来帮忙带孩子，大事你们定，小事让老人做主","p":"老人帮你带孩子，是在帮你，不是在给你打工。安全、健康、教育方向这些大事，夫妻俩定好后跟老人讲清楚；吃什么、穿什么、几点出门晒太阳这些小事，让老人按自己的方式来。挑刺太多，老人会觉得吃力不讨好。","tip":"","cost":{"money":"少","time":"少","will":"些","gain":"中","lens":"关系","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-5","b":"social","s":15,"n":5,"t":"家里的钱怎么管，两个人说清楚，大额支出一起商量","p":"婚后钱的管理方式没有标准答案：一个人管、共同账户、各管各的加一个家庭基金都可以，关键是两个人都认可、都知道家里的钱在哪。约定一个金额，超过这个数的支出（买车、借钱给亲戚、投资）要两个人商量后再决定。","tip":"「咱们定个规矩，超过五千的花销都提前说一声，好吗？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-6","b":"social","s":15,"n":6,"t":"给双方父母的钱和东西，大体平衡，两个人都知道","p":"一方偷偷给自己父母大额的钱，另一方知道后很难不介意。孝敬双方父母，大体上保持平衡，金额和频率两个人商量好。父母有特殊困难（生病、受灾）需要多帮的，也跟伴侣说清楚，而不是瞒着。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-7","b":"social","s":15,"n":7,"t":"不在父母面前说伴侣的坏话","p":"夫妻吵完架，你跟父母诉苦，过两天你们和好了，父母却还记着「他欺负过你」。父母天然会站在你这边，他们对你伴侣的看法一旦变坏，很难再扭转。夫妻矛盾，优先夫妻之间解决，实在解决不了，找朋友或专业的婚姻咨询。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-8","b":"social","s":15,"n":8,"t":"吵架别当着孩子和老人的面，不翻旧账、不轻易说「离婚」","p":"夫妻吵架难免，但当着孩子的面激烈争吵、互相辱骂，会让孩子长期处在不安里；当着老人的面吵，会把矛盾扩大成两家人的事。吵的时候就事论事，不翻几年前的旧账，不拿「离婚」当武器威胁，说出口的狠话很难收回。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"婚恋,父母"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-9","b":"social","s":15,"n":9,"t":"家务是两个人的事，别用「帮忙」的心态","p":"「我帮你洗碗」「我帮你带孩子」，这种说法背后的意思是「这本来是你的事」。家务和育儿是两个人共同的责任，按各自的时间和擅长的事分工：一个做饭一个洗碗，一个接送孩子一个辅导作业。分工说清楚，比谁更累的争吵少很多。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"关系","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-10","b":"social","s":15,"n":10,"t":"生不生孩子、什么时候生，是夫妻俩的决定","p":"长辈催生，往往是出于传统观念和对后代的期待。但要不要孩子、什么时候要、要几个，关系到夫妻双方的身体、事业和经济能力，应该由两个人商量决定。夫妻俩意见一致后，统一口径应对长辈，不要让一方单独承受压力。","tip":"「爸妈，这事我们俩有计划，等时机合适了一定告诉你们。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq15-11","b":"social","s":15,"n":11,"t":"女婿去岳父母家，多干活、多说话；儿媳去公婆家也一样","p":"去伴侣家里，最容易被诟病的是「坐着玩手机等吃饭」。主动帮忙做饭、洗碗、修个灯泡，陪长辈聊聊天，问问他们的身体和生活。不必刻意讨好，但要让对方父母感受到你把这里当成自己的家。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-12","b":"social","s":15,"n":12,"t":"记住伴侣父母的生日和重要日子","p":"岳父母、公婆的生日、结婚纪念日，打个电话、送一份小礼物，比平时多少句客气话都管用。很多矛盾就是从「他从来不记得我妈的生日」这样的小事开始积累的。","tip":"「妈，生日快乐！给您订了个蛋糕，晚上到。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-13","b":"social","s":15,"n":13,"t":"原生家庭借钱、要钱，夫妻商量后一起回复","p":"兄弟姐妹借钱、父母要钱给弟弟买房，这是很多婚姻里的「炸弹」。用的是夫妻共同的钱，就应该两个人商量后再答复，可以帮多少、怎么帮、要不要写借条。一方私下答应、偷偷转账，即使数额不大，也会严重伤害信任。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-14","b":"social","s":15,"n":14,"t":"尊重伴侣家里的生活习惯，不当着面说「你们家怎么这样」","p":"每个家庭都有自己的习惯：饮食口味、过节方式、说话嗓门、花钱观念。看不惯可以理解，但当着对方家人的面评价「你们家怎么这么不讲究」，等于否定了伴侣成长的环境。真有影响你们小家庭的习惯，私下和伴侣商量怎么调整。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq15-15","b":"social","s":15,"n":15,"t":"长期冷战、经常性辱骂和威胁，也是家庭暴力","p":"家庭暴力不只是动手。家庭成员之间经常性的侮辱、诽谤、威胁、跟踪、骚扰，以冻饿等方式造成的身体或精神侵害，法院都可以认定为家庭暴力，受害人可以申请人身安全保护令。长期被冷落、被贬低、被控制钱和行动，不是「性格不合」那么简单。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq15-16","b":"social","s":15,"n":16,"t":"不随便替伴侣借钱签字，也别背着伴侣借大额的钱","p":"夫妻双方共同签名或者一方事后追认的债务，属于共同债务；一方在婚姻期间以个人名义为家庭日常生活需要所借的债，也可能被认定为共同债务。所以，伴侣让你在借款合同上签字，要先弄清借多少、用在哪；你自己借大额的钱，也要让伴侣知道。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-17","b":"social","s":15,"n":17,"t":"伴侣的父母生病，你主动出力，比什么都管用","p":"岳父母、公婆住院，你主动陪床、跑手续、联系医生、给伴侣分担压力，这份付出伴侣会记一辈子，对方父母也会真正把你当自家人。反过来，在这时候冷眼旁观，是很多夫妻感情出现裂痕的开始。","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq15-18","b":"social","s":15,"n":18,"t":"走到离婚这一步，先弄清离婚冷静期和财产规则","p":"协议离婚要经过三十日的离婚冷静期，期间任何一方都可以撤回申请；冷静期满后三十日内双方要亲自去领离婚证，否则视为撤回。协商不成的，可以向法院起诉。离婚时一方隐藏、转移、变卖、毁损、挥霍共同财产，或者伪造共同债务企图侵占另一方财产的，…","tip":"","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-19","b":"social","s":15,"n":19,"t":"离婚后不在孩子面前说对方的坏话，探望按约定来","p":"离婚是大人之间的事，孩子仍然需要爸爸和妈妈。在孩子面前骂另一方、阻挠对方探望、拿孩子当筹码要钱，伤害最大的是孩子。不直接抚养的一方有探望的权利，也有支付抚养费的义务，双方按约定执行。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"父母"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq15-20","b":"social","s":15,"n":20,"t":"婚姻遇到坎，可以一起去做婚姻咨询","p":"很多夫妻的问题不是不爱了，而是不会沟通：一说就吵，一吵就冷战。婚姻咨询能帮两个人看清互动中的模式，学会更好的沟通方式。不必等到要离婚了才去，越早越有用。","tip":"","cost":{"money":"多","time":"中","will":"是","gain":"中","lens":"关系","who":"婚恋"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-1","b":"social","s":16,"n":1,"t":"朋友分远近，期待也要分远近","p":"能深夜打电话哭诉的知己，一起吃喝玩乐的玩伴，工作上互相帮衬的伙伴，偶尔点赞的点头之交，不同的朋友能给你的东西不一样。对玩伴期待知己的担当，对点头之交期待雪中送炭，最后失望的是自己。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-2","b":"social","s":16,"n":2,"t":"借钱给朋友，按「借出去可能就要不回来」来定数","p":"朋友开口借钱，原则和亲戚一样：问清用途，只借你能承受损失的金额，写借条、走转账（见第 12 章）。很多友谊不是因为不借钱断的，而是因为借了钱、对方不还、你又不好意思催，慢慢断的。借之前就想清楚：如果他还不上，我还愿意和他做朋友吗？","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq16-3","b":"social","s":16,"n":3,"t":"朋友托你保守的秘密，就烂在肚子里","p":"朋友把感情、家事、健康、工作上的秘密告诉你，是把信任交给了你。哪怕是告诉自己的伴侣、哪怕是「只跟一个人说」，秘密都可能越传越远。一旦被朋友知道是从你这里漏出去的，这段友谊基本就到头了。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-4","b":"social","s":16,"n":4,"t":"朋友有好事，真心祝贺；有难事，主动问一句","p":"朋友升职、买房、结婚，你的反应决定了他以后还会不会第一个告诉你好消息。研究发现，对伴侣和朋友的好消息给予积极、热情的回应，比在困难时给予支持，更能预测关系的质量。朋友遇到难事，不等他开口，主动问一句「需要我做什么」。","tip":"「太好了！你这一年真的太拼了，必须庆祝一下！」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-5","b":"social","s":16,"n":5,"t":"朋友吃饭可以 AA，也可以轮流请，关键是别总让一个人掏钱","p":"朋友聚会，AA 制清楚省心，轮流请客有人情味，都没问题。问题是有人每次都「忘了带钱」、每次都等别人买单。你发现自己总是被默认买单，可以提议 AA；发现自己总是被请，下次主动结账。","tip":"「这次咱们 AA 吧，以后常聚，谁也别有负担。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-6","b":"social","s":16,"n":6,"t":"别跟朋友说「你应该」，先问他想不想听建议","p":"朋友诉苦时，你一句接一句「你应该辞职」「你应该分手」「你应该早点跟我说」，他听到的是指责。先听完，再问「你想听听我的看法吗」。对方说要，再给建议；对方只想发泄，就陪着骂两句、递杯水。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-7","b":"social","s":16,"n":7,"t":"朋友让你出借银行卡、手机卡、身份证，一律拒绝","p":"「借你的卡走个账」「帮我注册个账号」「你身份证借我用一下」，哪怕对方说给你好处费、说只用一次，都要拒绝。法律禁止出租、出借、出售银行账户、支付账户、电话卡和互联网账号；这些卡号一旦被诈骗、洗钱团伙使用，…","tip":"「卡和身份证这些我谁都不借，这个真不是针对你。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq16-8","b":"social","s":16,"n":8,"t":"朋友让你作伪证、帮他圆谎，可以不帮","p":"朋友出了事，求你在警察、法院面前替他说假话，或者帮他藏匿、销毁证据。讲义气不等于替人违法：在刑事诉讼中作虚假证明，可能构成伪证罪；帮人毁灭、伪造证据，可能构成帮助毁灭、伪造证据罪；民事诉讼中提供虚假证据，也会被罚款甚至拘留。","tip":"「你的事我能帮你找律师、陪你去，但让我说假话，我做不到，对你也没好处。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq16-9","b":"social","s":16,"n":9,"t":"别把朋友拉进你的微商、保险和理财","p":"你开始做某样生意，第一反应是在朋友圈和老朋友里推销，这很正常，但要有分寸：告诉大家你在做什么，有兴趣的人自然会来问；不要私信轰炸、不要拉人进群、不要用交情逼人下单。朋友买你的东西是情分，不买是本分。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq16-10","b":"social","s":16,"n":10,"t":"朋友疏远了，可以主动联系一次，也可以顺其自然","p":"毕业、换城市、结婚生孩子之后，很多友情会自然变淡，这不一定是谁做错了。想念一个朋友，就主动发条消息、约一顿饭，大多数人都会很高兴。如果对方几次都冷淡回应，也不必强求，人生不同阶段有不同的朋友。","tip":"「好久没见了，突然想起我们以前一起……最近怎么样？」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-11","b":"social","s":16,"n":11,"t":"朋友圈里的八卦，听了就停在你这里","p":"一群朋友里，总有人会说谁和谁闹掰了、谁离婚了、谁欠了钱。你听到了，可以不评论、不追问、不往外传。今天你传别人的事，明天别人就会传你的事；大家也会默默记住「什么事都别跟他说」。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-12","b":"social","s":16,"n":12,"t":"异性朋友和伴侣之间，保持透明，主动避嫌","p":"有了伴侣之后，和异性朋友的往来要让伴侣知道、让伴侣安心：不深夜单独聊天、不单独喝酒到很晚、不在伴侣不知情时频繁见面。坦坦荡荡的友谊，不怕被看见；需要瞒着伴侣的往来，本身就该想想了。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq16-13","b":"social","s":16,"n":13,"t":"和朋友闹僵了，先道歉的人不丢人","p":"朋友之间的矛盾，很多是误会加上谁都不肯先低头。你觉得这段友谊值得，就先迈出一步：为自己做得不对的部分道歉，说明你的感受，问问对方怎么想。先道歉不是认输，而是表明你更在乎这段关系。","tip":"「那天是我说话太冲了，对不起。我挺在乎咱俩的，想把话说开。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq16-14","b":"social","s":16,"n":14,"t":"朋友说想不开，认真问、陪着他、帮他找专业的人","p":"朋友说「活着没意思」「不想活了」，不要当成玩笑，也不要急着讲大道理。可以直接问他是不是有伤害自己的想法——研究表明，直接询问自杀念头并不会增加风险，反而可能让人感到被理解。陪着他，帮他联系心理援助热线或带他去医院精神心理科，…","tip":"「你说的这些让我很担心。你是不是有想伤害自己的念头？我陪你一起想办法。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-15","b":"social","s":16,"n":15,"t":"朋友帮你介绍工作、对象，成不成都要谢","p":"朋友帮你内推、牵线，是用自己的人情和信誉为你背书。成了，好好请他吃顿饭；没成，也要告诉他结果、谢谢他的费心。更不要因为没成而抱怨朋友介绍的人不行，这会让朋友以后再也不敢帮你。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-16","b":"social","s":16,"n":16,"t":"借了朋友的东西，按时还、完好还；弄坏了主动赔","p":"借了朋友的书、相机、车、帐篷，用完尽快还，还之前清理干净、检查有没有损坏。弄坏了，主动说明并赔偿或修好，别等朋友发现。对方不好意思开口要的东西，往往就是你最该记得还的东西。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-17","b":"social","s":16,"n":17,"t":"换了城市、有了家庭，用小而稳定的方式维系友情","p":"成年人的友情很容易被工作和家庭挤掉。不必天天联系，但可以有一些固定的习惯：每年约一次旅行、生日一定打电话、看到和对方有关的东西随手分享。友情不需要轰轰烈烈，需要的是不断线。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"异乡"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq16-18","b":"social","s":16,"n":18,"t":"交朋友，看三观和底线，不只看是否投缘","p":"一起玩得开心的人很多，但能长期交往的朋友，至少在几件事上要一致：怎么对待钱、怎么对待承诺、怎么对待别人。一个总是占小便宜、经常违约、喜欢在背后说人坏话的人，即使对你很好，也迟早会用同样的方式对你。","tip":"","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq17-1","b":"social","s":17,"n":1,"t":"入职头一周，先弄清三件事：向谁汇报、团队怎么分工、事情怎么流转","p":"新人最容易犯的错，是不知道该找谁：一件事该先问组长还是直接问部门领导？审批要走哪个流程？文件放在哪？头一周把直属领导、团队成员和他们负责的事、常用的工具和流程记在本子上，记住同事的名字，后面会少走很多弯路。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq17-2","b":"social","s":17,"n":2,"t":"不懂就问，但先自己查一遍，同一个问题别问第二次","p":"新人提问是正常的，大家也愿意回答。但问之前先查文档、看历史资料、搜一下内部群；问的时候说清楚你已经查了什么、卡在哪里、你自己的理解是什么。别人回答了，记下来，下次别再问同一个问题。","tip":"「我看了上个月的报表模板，这个口径是按自然月还是按结算月？我理解是结算月，对吗？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq17-3","b":"social","s":17,"n":3,"t":"接任务时确认三件事：要什么结果、什么时候要、做到什么程度","p":"领导一句「把这个弄一下」，可能是十分钟的事，也可能是三天的事。接到任务时，确认交付的形式（一页纸还是完整报告）、截止时间、质量要求和有没有参考样例。确认完用一句话复述给领导，避免做完了才发现方向不对。","tip":"「我确认一下：周三下班前给您一版竞品对比，重点看价格和功能，先出一页纸的结论，对吗？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq17-4","b":"social","s":17,"n":4,"t":"进度要主动汇报，坏消息更要早说","p":"领导最怕的不是事情出问题，而是到截止日才知道出了问题。任务时间长的，定期简单汇报一下进度；遇到困难、可能延期的，第一时间说，同时带上你的分析和备选方案。坏消息越早说，越有补救的余地。","tip":"「这个数据源周一接口改了，进度可能延后一天。我先用备份数据做了一版，您看能不能先用着？」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq17-5","b":"social","s":17,"n":5,"t":"重要的口头指令，用一条消息确认下来","p":"会议上、走廊里领导交代的事，转头就容易记岔，日后出了问题也说不清。会后发一条简短的消息：「刚才您说的我整理了一下……有遗漏请您补充」。这不是不信任，而是对双方都负责。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq17-6","b":"social","s":17,"n":6,"t":"犯了错，第一时间说出来，带着补救方案","p":"新人犯错很正常，可怕的是瞒着。发现自己发错了文件、算错了数据、漏了客户的需求，马上告诉领导：发生了什么、影响有多大、你已经做了什么补救、还需要谁的帮助。主动认错的人，大多数领导会帮你兜底；被别人发现的错，性质就变了。","tip":"「王经理，我刚发现给客户的报价单有个数字错了，我已经打电话说明并重新发了一版，想跟您报备一下。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq17-7","b":"social","s":17,"n":7,"t":"试用期也是劳动关系：期限有上限、工资有下限、社保要交","p":"试用期的长短和合同期限挂钩：合同三个月以上不满一年的，试用期不超过一个月；一年以上不满三年的，不超过两个月；三年以上和无固定期限的，不超过六个月；同一单位只能约定一次试用期。试用期工资不得低于约定工资的 80%，也不得低于当地最低工资标准。…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"金钱","who":"新人"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq17-8","b":"social","s":17,"n":8,"t":"入职一个月内要签书面劳动合同，拖着不签可以主张二倍工资","p":"建立劳动关系，单位应当在用工之日起一个月内和你签书面劳动合同。超过一个月不满一年还没签的，单位应当每月支付二倍工资。所以入职后留意合同什么时候签、签的是不是你看过的版本，签完要拿到属于你的那一份。","tip":"「请问劳动合同什么时候签？我这边好准备一下材料。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":"新人"},"grade":"A","disputed":true,"ev":"法条","hasRef":false},{"id":"rq17-9","b":"social","s":17,"n":9,"t":"加班有上限、有加班费，长期超时可以拒绝","p":"法律规定延长工作时间一般每天不超过一小时，特殊原因每天不超过三小时、每月不超过三十六小时；工作日加班支付不低于 150% 的工资，休息日加班不能安排补休的支付不低于 200%，法定节假日不低于 300%。单位不得强迫或者变相强迫加班。…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"新人"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq17-10","b":"social","s":17,"n":10,"t":"新人别急着提改革，先弄明白「为什么现在是这样」","p":"新人常常一眼看出流程的「不合理」，但很多看似不合理的做法背后，有历史原因、客户要求或者合规考虑。先花一两个月把来龙去脉弄清楚，再提改进建议；提的时候带上数据和方案，并且先私下跟直属领导沟通。","tip":"「我注意到这个流程每次要人工核对三遍，想了解一下当初这么设计的原因，有没有可能简化一下？」","cost":{"money":"0","time":"中","will":"些","gain":"中","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq17-11","b":"social","s":17,"n":11,"t":"工作消息结论先行，一条消息说完一件事","p":"工作消息最怕「在吗」「有个事」然后半天不说是什么。一条消息把事情说完整：先说结论或请求，再说背景和细节，最后说需要对方什么时候回复。邮件的标题写清楚事由，附件命名规范。","tip":"「王经理，周报已更新，本周销售额环比增长 8%，有两个风险点需要您决策，详见附件第 3 页，周五前回复即可。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq17-12","b":"social","s":17,"n":12,"t":"找一位愿意带你的前辈，并且让他觉得带你值得","p":"职场上有人愿意点拨你，能少走很多弯路。找一位经验丰富、愿意分享的前辈，请教具体的问题，认真采纳他的建议，并且告诉他结果。让对方看到你的成长，他会更愿意继续带你。","tip":"「上次您说的那个方法我试了，效率高了很多，太感谢了。」","cost":{"money":"少","time":"少","will":"些","gain":"大","lens":"关系","who":"新人"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq17-13","b":"social","s":17,"n":13,"t":"被批评时，先听完、记下来，别当场辩解","p":"第一次被领导批评，本能反应是解释「我是因为……」。当场辩解，领导只会觉得你听不进意见。先把问题听完、记下来，说一句「明白了，我马上改」；如果确实有误会，等对方情绪平复后，再用事实和数据说明。","tip":"「好的，我记下了，今天下班前改好给您。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq17-14","b":"social","s":17,"n":14,"t":"不主动打听同事的工资，也别到处说自己的","p":"很多公司有薪酬保密的要求，同事之间互相比较工资，最容易产生不平衡和矛盾，被领导知道了也会很被动。想了解行业薪资水平，可以看招聘网站、行业报告，或者问已经离职的朋友。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq17-15","b":"social","s":17,"n":15,"t":"下班后的工作消息：急事马上回，不急的第二天回","p":"下班后收到领导、同事的消息，真正紧急的（线上故障、客户投诉、领导明确要求今晚给）尽快处理；只是想到了顺手发一下的，可以第二天上班第一时间回复。长期被要求下班后随时在线、随时干活，属于变相加班，可以和领导沟通边界。","tip":"（第二天）「昨晚看到您的消息了，我上午整理好发您。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq17-16","b":"social","s":17,"n":16,"t":"别在社交媒体上发公司内部信息，也别吐槽客户","p":"会议截图、内部文件、未发布的产品、客户的名字，发到朋友圈或网上，可能违反保密协议，严重的可能侵犯商业秘密。吐槽客户、吐槽领导的帖子，截图一旦传出去，后果难以控制。工作上的情绪，找信得过的朋友私下说。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"新人"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq17-17","b":"social","s":17,"n":17,"t":"午饭和同事一起吃，融入圈子，但别急着站队","p":"和同事一起吃午饭、喝下午茶，是了解团队、建立关系最自然的方式。但新人还看不清办公室里的人际关系，不要急着加入某个小圈子、跟着别人议论某位同事或领导。和谁都客气，和谁都保持一点距离，过一段时间再决定和谁更近。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq17-18","b":"social","s":17,"n":18,"t":"简历和背调资料如实填写，别伪造学历和工作经历","p":"伪造学历、工作经历、薪资证明，一旦被发现，单位可以以欺诈为由主张劳动合同无效、解除合同，不支付经济补偿；买卖、伪造学历证书本身也违法。适度突出自己的优势可以，编造事实不行。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"学生,新人"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq17-19","b":"social","s":17,"n":19,"t":"把「这不是我的活」换成「我先帮你看看」","p":"新人刚开始，别人请你帮个小忙，一口回绝「这不是我的活」，容易显得不合群。在不影响自己主要工作的前提下，可以帮一点；但要注意分寸，别让自己变成谁都能使唤的「杂工」。帮的时候说清楚能帮多少，见第 4 章、第 5 章。","tip":"「我手上的事今天要交，下午四点以后可以帮你看看，行吗？」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq17-20","b":"social","s":17,"n":20,"t":"新人头三个月，比聪明更重要的是可靠","p":"按时到岗、按时交付、回复及时、记录清楚，这些看起来平凡的小事，恰恰是领导判断一个新人能不能被委以重任的依据。能力可以慢慢积累，可靠的名声要从第一天开始建立。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-1","b":"social","s":18,"n":1,"t":"汇报先说结论，再说原因和细节","p":"领导时间有限，最想知道的是结果：事情办成没有？有什么问题？需要他做什么？汇报时第一句话就说结论，然后说关键原因，最后说下一步计划和需要的支持。细节准备好，领导问到再展开。","tip":"「王总，A 客户的合同签下来了，比预期少了 5%，主要让在了交付周期上。下一步我准备……需要您帮忙协调一下技术部。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"新人"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-2","b":"social","s":18,"n":2,"t":"遇到问题带方案去：两三个选项，加上你的建议","p":"「领导，这事办不了，怎么办？」是把难题甩给领导。更好的说法是：「这件事遇到了一个问题，我想了三个办法，各自的利弊是这样，我建议选第二个，您看行吗？」领导只需要做选择题，而不是填空题。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-3","b":"social","s":18,"n":3,"t":"摸清领导的沟通习惯，用他舒服的方式汇报","p":"有的领导喜欢当面聊，有的喜欢看文字；有的要看详细数据，有的只要一页纸结论；有的早上效率高，有的下午才有空。观察他回消息、开会、审文件的习惯，按他偏好的方式和时间来，沟通效率会高很多。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-4","b":"social","s":18,"n":4,"t":"领导交代的事，办完了说一声，形成闭环","p":"领导交代的事，最让人放心的状态是「件件有着落，事事有回音」。办完了，主动告诉领导结果，哪怕只是一句「已经办好了」；办不完，也要说明进展和原因。不要让领导来追问「那件事怎么样了」。","tip":"「您上午让联系的供应商已经确认了，下周一送样。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-5","b":"social","s":18,"n":5,"t":"一般不越级汇报，除非涉及违法违规或直属领导本人的问题","p":"绕过直属领导直接找更高层，会让直属领导觉得被架空，以后很难共事。正常的工作问题，先找直属领导；大领导直接问你，如实回答，事后告知直属领导。但如果发现的是违法违规问题、安全隐患，或者问题出在直属领导本人身上，…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-6","b":"social","s":18,"n":6,"t":"公开场合维护领导，不同意见私下说","p":"在会议、客户、其他部门面前当众反驳领导，即使你是对的，领导也会很难堪。有不同意见，会后单独找领导，用数据和事实说明你的顾虑。领导采纳了，功劳记在他头上也无妨；没采纳，按决定执行，必要时留个书面意见。","tip":"（会后）「王总，会上那个方案我有个顾虑想跟您单独汇报一下……」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-7","b":"social","s":18,"n":7,"t":"决策定了就认真执行；有保留意见，留一封书面说明","p":"讨论阶段可以充分表达不同意见，一旦领导拍板，就按决定执行，而且要尽力做好，不能消极怠工、等着看笑话。如果你担心的风险比较大，在执行前发一封简短的邮件，写明你的顾虑和建议，语气客观。将来真出了问题，有据可查；没出问题，也不丢人。","tip":"「方案按您定的推进。我把之前说的库存风险整理在邮件里了，供您参考，我们会提前做好预案。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-8","b":"social","s":18,"n":8,"t":"功劳归团队，向上汇报时点名同事的贡献","p":"项目做成了，在领导和更高层面前，把团队和具体出力的同事说出来：「数据是小李熬了两个通宵跑出来的」。这不会让你显得没本事，反而说明你会带人、能合作。处处抢功的人，领导心里有数，同事也不愿再配合。领导的功劳，更不要在外人面前抢着说是自己的主意。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq18-9","b":"social","s":18,"n":9,"t":"领导的私事不打听、不外传，看见了也当没看见","p":"离领导近了，难免会知道一些私事：家里的矛盾、身体的状况、和谁的关系好坏、个人的财务安排。领导不主动说，不问；知道了，不和任何同事讲，也不在朋友圈、群里暗示。能守住秘密的人，才会被当作自己人；嘴不严的人，迟早会被边缘化。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-10","b":"social","s":18,"n":10,"t":"领导要你做违法违规的事：明确拒绝、留下记录，不替人背锅","p":"做假账、改数据、签假合同、违规操作、冒险作业，这些事一旦出事，签字的人、经手的人都跑不掉，「领导让我干的」不能免责。遇到这种要求，先客气地说明风险，请领导出具书面指令或走正式流程；领导坚持，就明确拒绝，保存好聊天记录、邮件，…","tip":"「这个操作不符合财务制度，我签了字以后要担责任。您看能不能走一下正式审批，或者给我一个书面的说法？」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq18-11","b":"social","s":18,"n":11,"t":"新领导上任：先对齐目标和习惯，别急着表忠心，也别急着诉苦","p":"新领导来了，头一个月最重要。主动约个时间，简短介绍你负责的事、目前的进度和难点，问问他最看重什么、希望怎么汇报。别一见面就抱怨前任、诉苦要资源，也别急着站到他身边表忠心。他会观察谁靠谱、谁有用，你只要把工作摆清楚、把事做好。","tip":"「王总，我简单跟您汇报一下我这边的三块工作。您刚来，有什么想先了解的、希望我怎么配合，您随时说。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-12","b":"social","s":18,"n":12,"t":"谈加薪、要资源：带上数据，挑对时机，说出具体数字","p":"「我最近很辛苦」打动不了谁。谈之前准备三样东西：过去一段时间你做成了什么（最好有数字）、市场上同类岗位的薪资水平、你接下来能承担什么。时机选在项目刚做成、绩效评定前、预算编制前，而不是领导焦头烂额的时候。开口要说具体数字或幅度，…","tip":"「今年我负责的渠道收入涨了 40%，同岗位的市场价大概在这个区间。我希望薪资能调到 X，您看需要我在哪些方面再做出成绩？」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"金钱","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-13","b":"social","s":18,"n":13,"t":"请假提前说，交接安排好；年休假是法定权利","p":"请假尽量提前，按公司流程提交，同时把手头的工作安排好：谁来接、紧急情况找谁、哪些事已经提前处理。休假期间如果答应能看消息，就说清楚什么时段能回。年休假不是领导的恩赐，是法律规定的权利，只是具体时间要和单位协商安排。","tip":"「我下周三到周五想休年假，手上的周报已经提前交了，客户那边有急事小张会对接，我每天晚上看一次消息。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":"新人"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq18-14","b":"social","s":18,"n":14,"t":"领导之间有矛盾：不站队、不传话，按流程和授权办事","p":"两个领导意见不合，最危险的是夹在中间传话、选边站。两位领导给你的指令冲突时，不要自己判断听谁的，而是把冲突摆到桌面上：请他们一起确认，或者请共同的上级定夺。一位领导在你面前说另一位领导的不是，听着，不附和，更不转述。","tip":"「李总让我先做 A，张总让我先做 B，两件事时间冲突，我拉个三方会，请两位定一下优先级？」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq18-15","b":"social","s":18,"n":15,"t":"不在领导面前说同事坏话；反映问题只说事实，不贴标签","p":"在领导面前说同事「懒」「不靠谱」「人品不行」，领导会想：他在别人面前是不是也这么说我？同事确实影响了工作，就只讲事实和影响：哪件事、什么时间、造成了什么后果、你需要什么支持。贴标签是打小报告，讲事实是反映问题。","tip":"「这周的接口已经延期两次了，影响了我们周五的上线。能不能请您帮忙协调一下资源？」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-16","b":"social","s":18,"n":16,"t":"弄清领导的考核目标，你的工作才有分量","p":"领导也有自己的考核：营收、成本、项目进度、安全、满意度。你的工作和他最看重的指标连在一起，才会被看见。年初看部门目标和考核方案，平时留意领导反复提的事，选工作重点时优先挑「对部门目标贡献大」的那几件。","tip":"「今年部门最重要的指标是什么？我这块工作怎么做能帮上忙？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-17","b":"social","s":18,"n":17,"t":"挨了批评：先接住，事后复盘；人格侮辱另当别论","p":"领导批评的是事，就先认下来，别当场辩解「不是我的问题」，更别甩锅给同事。回去冷静地复盘：错在哪、怎么补救、以后怎么避免，然后简短地回复领导。如果批评里有误会，等领导气消了再用事实说明。但如果是辱骂、拿你的长相家庭说事、当众羞辱，…","tip":"「这次是我考虑不周，我今天下班前把补救方案发给您。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq18-18","b":"social","s":18,"n":18,"t":"领导酒后、私下说的话：听听就好，不当真、不外传","p":"饭局上、出差路上，领导可能会说一些平时不说的话：对某位同事的评价、对公司的牢骚、对你的许诺。评价和牢骚，听着就好，不接话、不传播；对你的许诺，也别马上当真，等到正式场合再确认。第二天见面，就当什么都没发生。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq18-19","b":"social","s":18,"n":19,"t":"领导让你办私事：顺手的小忙可以帮，花公款、占工时的要说清楚","p":"顺路帮忙取个快递、推荐个医生，算是人之常情。但如果变成经常接送孩子、搬家跑腿、代办私人手续，或者要你用公司的钱、车、人去办，就超出了工作范围。可以婉转地说明自己的工作安排，涉及公款公物的，坚决不碰。帮忙垫付的钱，及时、明确地说清楚，…","tip":"「王总，这周我手上的投标材料比较赶，周末接孩子的事我可能顾不上，要不我帮您问问附近的托管？」","cost":{"money":"少","time":"中","will":"些","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq18-20","b":"social","s":18,"n":20,"t":"领导「画饼」：把承诺落到时间、条件和书面上","p":"「好好干，明年给你升职」「项目做成了少不了你的」，这类话说着容易，兑现很难。听到承诺，客气地追问细节：什么时间？达到什么条件？是什么级别、多少钱？然后用邮件或消息总结一下发给领导确认。真正有诚意的承诺不怕写下来，怕写下来的，…","tip":"「谢谢王总！我确认一下：如果年底项目按时上线，明年一季度晋升到 P6，对吗？我记一下，按这个目标努力。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq18-21","b":"social","s":18,"n":21,"t":"给领导送礼：平时不必，心意要小；公职人员和国企更要谨慎","p":"在大多数正规公司，给领导送礼不是必需的，做好工作比什么都强。出差带点当地特产大家分、领导家有红白喜事按单位惯例随礼，这些可以。贵重礼物、现金、购物卡，不但让领导为难，还可能违反公司的廉洁制度。领导是公职人员或者在国企的，规矩更严，…","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"小","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-1","b":"social","s":19,"n":1,"t":"同事首先是合作者：友好、可靠、有边界，不必人人都是朋友","p":"和同事的关系，最重要的不是亲密，而是可靠：答应的事按时完成，需要配合时痛快配合，见面打招呼、有事说清楚。私人生活可以分享一点，但不必掏心掏肺；聊得来的可以慢慢成为朋友，聊不来的，保持礼貌就够了。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq19-2","b":"social","s":19,"n":2,"t":"办公室八卦：不传、不评、不打听","p":"谁和谁有矛盾、谁要离职、谁的家事，听到了就停在你这里，不评价、不转述，也不主动打听。别人拉你聊，可以笑笑、转个话题，或者说「这个我真不清楚」。八卦传到当事人耳朵里，最后被记住的往往是传话的人。","tip":"「这事我不太了解，不好说。对了，下午那个会要准备什么？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-3","b":"social","s":19,"n":3,"t":"不在背后说同事和领导的坏话，说出去的话迟早会传回去","p":"同事之间吐槽领导、议论别人，当下觉得是「自己人才说的话」，但办公室里没有绝对的秘密。而且心理学研究发现，你描述别人时用的负面词，听的人会不自觉地把它们联想到你身上。真有不满，找信得过的朋友（最好是公司外面的）说。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"体面","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-4","b":"social","s":19,"n":4,"t":"请同事帮忙：说清背景、要什么、什么时候要，帮完了公开道谢","p":"「有空帮我看下这个」最让人头疼：看什么？看到什么程度？什么时候要？请人帮忙，一次说清楚：这件事是什么、为什么找他、需要他做哪一步、最晚什么时候要。帮完了，除了私下说谢谢，在群里或者对方领导面前提一句，对方会很受用。","tip":"「张哥，客户周四要报价，里面的运费我拿不准，您之前做过华南线，能不能帮我看下第三页的测算？明天中午前给我就行，谢谢！」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-5","b":"social","s":19,"n":5,"t":"同事找你帮忙：先看自己的活，帮得了说清范围，帮不了早说","p":"乐于助人是好事，但自己的工作被耽误了，最后吃亏的是你。同事来求助，先想想手上的事；能帮，就说清楚帮到哪一步、什么时候能给；帮不了，当场说明原因，或者推荐更合适的人。最怕的是答应了又做不到，或者帮了一次就变成了你的活。","tip":"「我今天要赶完投标书，明天上午可以帮你看一小时，你看来得及吗？」","cost":{"money":"0","time":"中","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-6","b":"social","s":19,"n":6,"t":"合作的事情留痕：会议纪要、群消息确认，谁负责什么写清楚","p":"「我以为你会做」「我没说过这个」，大部分扯皮都来自口头约定。几个人合作的事，会后发一条简单的纪要：结论是什么、每项工作谁负责、什么时候完成，请大家确认。这不是不信任谁，而是让所有人记得同一个版本。","tip":"「同步一下今天的结论：1. 方案用 B 版；2. 小王周三前出设计稿；3. 我周五对接客户。有出入的请回复，谢谢。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-7","b":"social","s":19,"n":7,"t":"被甩锅：当场用事实澄清，语气平和，事后补齐记录","p":"会上有人说「这事是小李负责的」，而你从没接过，沉默就等于认了。当场平静地说出事实：什么时间、谁定的分工、你负责的是哪部分，并拿出纪要或消息记录。不要激动、不要反咬，只把事实摆清楚。会后再给领导发一条简短的说明，附上记录。","tip":"「我补充一下：上周三的会上，这一块定的是由运营组跟进，我负责的是数据部分，纪要我会后发给大家。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq19-8","b":"social","s":19,"n":8,"t":"被抢功：平时留痕，关键时刻拿出来，不必当众撕破脸","p":"方案是你写的，汇报的时候却变成了别人的功劳，这在职场很常见。防的办法是日常留痕：周报里写清楚自己做了什么，文档写上作者和版本，重要的成果发邮件时抄送领导。真被抢了，私下找对方或领导，用记录说明你的贡献，而不是在群里争吵。","tip":"「王总，上次汇报的那版分析，数据模型是我搭的，我把过程文档发您一份，后续优化我也可以继续跟。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-9","b":"social","s":19,"n":9,"t":"同事升职、拿奖：真心祝贺；自己没轮上，私下问清差距","p":"和你同期的人升了职，你心里不舒服很正常，但当面阴阳怪气、背后说「他就是会来事」，只会让人看轻你。当面痛快地祝贺，回头单独约领导聊一聊：这次的标准是什么？我差在哪里？下次要做到什么？把失落变成具体的目标。","tip":"「恭喜啊，实至名归！」（对领导）「这次晋升我没赶上，想听听您的看法，我接下来重点补哪些？」","cost":{"money":"0","time":"少","will":"是","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq19-10","b":"social","s":19,"n":10,"t":"和同事起了冲突：先冷静，再私下当面谈，对事不对人","p":"工作里吵起来，最忌在群里、会上争个输赢，或者从此冷战。先缓一缓，等双方情绪下去了，找个没人的地方当面谈：说清楚你看到的事实、你的顾虑和你希望怎么做，再听听对方的理由。目标是把事情办成，不是证明谁对。实在谈不拢，一起找领导定。","tip":"「昨天在会上我语气有点冲，不好意思。我主要是担心上线时间，我们一起看看怎么排更合适？」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-11","b":"social","s":19,"n":11,"t":"新同事来了，主动帮一把：介绍一下人和流程，叫上一起吃饭","p":"每个人都当过新人，都记得刚来时那种不知道找谁、不敢多问的局促。新同事来了，花半小时告诉他常用的系统、各项事情找谁、团队有哪些不成文的习惯，第一周叫他一起吃饭。这点小事，他会记很久。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq19-12","b":"social","s":19,"n":12,"t":"同事离职：好好告别，不说坏话，留个联系方式","p":"同事离职，是人脉从「同事」变成「同行」的时刻。他在的时候帮过你的，走之前当面道谢、留个联系方式，有余力可以请顿饭。别在他走后说「早就看出他不行」，也别打听他去哪家、拿多少钱。今天离开的同事，可能是你明天的客户、合作方或者推荐人。","tip":"「这几年跟你学了很多，新地方加油，常联系！」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-13","b":"social","s":19,"n":13,"t":"同事开口借钱：小额应急可以，大额婉拒，借了就写清楚","p":"同事之间借钱，比朋友之间更难处理：要不回来，每天还得见面；催得急了，工作也受影响。几百块的应急，可以当作帮忙，做好要不回来的准备；数额大的、理由含糊的、反复借的，直接说「最近手头也紧」。真借了，发个消息写明金额和还款时间，转账留记录。","tip":"「这次真不太方便，家里刚交了房租。你要是急，可以看看公司有没有员工互助金。」","cost":{"money":"少","time":"少","will":"是","gain":"中","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-14","b":"social","s":19,"n":14,"t":"团队凑份子：按惯例量力而行，不想参加就低调说明","p":"同事结婚、生孩子、过生日、离职，不少团队会凑钱买礼物或随礼。先看团队以前怎么做，金额跟着大多数人走，不必多也不要少得太明显。组织的人要把钱怎么花、买了什么公开说清楚，多退少补。真不想参与，私下跟组织的人说一声，别在群里公开表态。","tip":"（组织者）「给小王的结婚礼物，每人 50 元，买了一套餐具共 680 元，剩下的 20 元下次团建用，明细在这里。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-15","b":"social","s":19,"n":15,"t":"办公室恋情：先看公司制度，工作中低调，分手不影响工作","p":"同事之间产生感情很正常，但有几件事要想清楚：公司是否禁止或要求申报（尤其是上下级之间）；在工作中能不能做到不偏袒、不在办公室秀恩爱；万一分手，还能不能正常共事。在关系稳定之前，没必要公开；如果存在上下级关系，最好主动申报，由公司调整汇报线。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq19-16","b":"social","s":19,"n":16,"t":"同事的病情、家事等隐私：知道了不外传，也别当成谈资","p":"同事请了长病假、家里出了变故、在办离婚，这些事他愿意告诉你，是信任；你知道了，就别在午饭时讲给别人听，也别当着他的面问「听说你……」。需要帮他分担工作的，按工作安排来，不必解释原因。","tip":"（别人打听时）「他请假的原因我不清楚，工作上有需要找我就行。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq19-17","b":"social","s":19,"n":17,"t":"被排挤、孤立：先自查、主动沟通；持续针对的，找领导或人事并留下记录","p":"吃饭不叫你、开会不通知你、信息不同步给你，被孤立的滋味很难受。研究发现，被排斥带来的心理痛苦是真实的。先想想有没有误会，找一位关系还行的同事私下问问；如果是有人持续针对，例如故意隐瞒工作信息、当众嘲讽、给你穿小鞋，…","tip":"「这三次项目会我都没有收到通知，导致我负责的部分没能同步，我想请您帮忙看看是哪里出了问题。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-18","b":"social","s":19,"n":18,"t":"遇到同事性骚扰：明确拒绝、保存证据、向单位投诉","p":"黄色笑话、不必要的身体接触、深夜发暧昧消息、借工作之名约单独见面，只要你明确感到被冒犯，就不是「开玩笑」。当场或尽快明确表态「请你停止」；保存聊天记录、邮件，记下时间地点和在场的人；向直属领导之外的人事、合规或工会投诉。…","tip":"「你刚才的话让我很不舒服，请以后不要再这样。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq19-19","b":"social","s":19,"n":19,"t":"同事出了错，不在群里或会上点名批评，私下提醒","p":"同事的材料有错别字、数据算错了，在大群里@他指出来，他会很难堪，还会觉得你在领导面前「表现自己」。私聊告诉他，让他自己改。确实需要大家知道的（例如已经发给客户的错误），先私下沟通，再由他本人或者负责人统一更正。","tip":"「小王，表格第 12 行的合计好像少算了一项，你看下？我没在群里说。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq19-20","b":"social","s":19,"n":20,"t":"和同事竞争：比结果，不使绊子，不藏资料、不拆台","p":"同一个晋升名额、同一个大客户，同事之间难免竞争。把劲用在自己的业绩上；共享的资料照常共享，该配合的照常配合，不在领导面前贬低对方，不故意拖他的进度。职场是长期的，今天靠使绊子赢了一次，以后所有人都会防着你。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq19-21","b":"social","s":19,"n":21,"t":"跨部门协作：先找对的接口人，按对方的流程走，帮了忙在他领导面前提一句","p":"其他部门的人没有义务优先处理你的事，他们也有自己的考核。先弄清对方部门由谁对接、走什么流程、需要提前多久；提需求时说清楚背景和对他们的好处；对方帮了忙，给他的领导发个邮件致谢，或者在周会上提一句。","tip":"「这次活动能按时上线，多亏技术部小刘加班支持，特别感谢！」（抄送对方领导）","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq19-22","b":"social","s":19,"n":22,"t":"同事向你吐苦水：认真听，不跟着骂，不转述","p":"同事找你倒苦水，大多数时候只是想有个人听。你可以表示理解：「换我也会着急」，但别跟着一起骂领导或其他同事，今天你附和的话，明天可能被说成是你的观点。听完的内容，不要讲给任何人。","tip":"「确实挺憋屈的，你打算怎么处理？需要我帮什么忙吗？」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq20-1","b":"social","s":20,"n":1,"t":"当上管理者，先完成角色转换：从自己干，到让大家干成","p":"很多业务骨干升成组长后，还是什么都自己上手，结果自己累死，团队也没成长。管理者的产出是团队的产出：花时间讲清目标、拆好任务、帮下属解决卡点、培养能接班的人。自己做一遍确实更快，但只有让别人学会了，你才能腾出手来做更重要的事。","tip":"","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"关系","who":"管理"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-2","b":"social","s":20,"n":2,"t":"布置任务说清五件事：目标、为什么、标准、时间、资源","p":"下属做不好，很多时候是因为没听明白。布置任务时说清楚：要达成什么结果，为什么要做这件事，做到什么程度算合格，什么时候要，可以找谁、用什么资源。最后请对方复述一遍，有没有理解偏差，一听就知道。","tip":"「这次要做的是三家竞品的价格对比，目的是给下周定价会做参考。一页纸结论加附表，周三下班前给我。数据可以找市场部的小林要。你说一下你的理解？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq20-3","b":"social","s":20,"n":3,"t":"表扬要公开、具体；批评要私下、对事","p":"「辛苦了」「不错」太空泛，下属听了没感觉。表扬要具体：哪件事、做得好在哪里、带来了什么结果，最好在团队面前说。批评则相反，关起门来单独说，只讲事情和影响，不说「你怎么老是这样」「你就是不用心」这类给人定性的话。","tip":"「这次客户投诉，小张当天就把退款流程理清楚了，还写了一份排查清单，以后大家都可以用。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"体面","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-4","b":"social","s":20,"n":4,"t":"定期一对一：听多说少，问问他的困难和想法","p":"只在开会和出问题时才和下属说话，你永远不知道他在想什么，直到他递上辞职信。定期和每个人单独聊：最近工作顺不顺、卡在哪里、需要什么支持、对团队有什么意见、想往哪个方向发展。这个时间属于下属，你主要负责听和记，聊完把答应的事落实。","tip":"「这半小时是你的，最近有什么想聊的？工作上、团队里的事都行。」","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"关系","who":"管理"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-5","b":"social","s":20,"n":5,"t":"分机会、分奖金、排加班，标准公开，不看亲疏","p":"团队最伤人心的，不是钱少，而是不公平：好项目总给关系好的人，苦活累活总是那几个人干，奖金怎么分没人知道。好机会怎么分配、绩效怎么评、加班怎么轮，定一个大家都知道的规则，并且自己带头遵守。下属问起来，你能讲清楚理由。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"管理"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-6","b":"social","s":20,"n":6,"t":"功劳给下属，责任自己扛","p":"项目做成了，向上汇报时把具体做事的人推到前面；项目出了问题，对上级先说「是我安排得不周到」，回头再和团队内部复盘。把功劳揽到自己身上、把锅甩给下属的领导，下属一次就看清楚了，以后不会再为他拼命。","tip":"（对上级）「这次延误主要是我在排期上估计不足，我们已经定了补救方案。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-7","b":"social","s":20,"n":7,"t":"不收下属的礼，不让下属替你办私事","p":"下属给你送礼，多半是有所求，或者是怕你；你收了，评绩效、分机会时就很难再公平，其他人也会有样学样。出差带回来的特产大家分，可以；贵重礼物、红包、购物卡，客气而坚决地退回。同样，别让下属帮你接孩子、搬家、代购，哪怕他嘴上说愿意。","tip":"「心意我领了，东西你拿回去。以后不用这样，工作做好就是对我最大的支持。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq20-8","b":"social","s":20,"n":8,"t":"下属犯了错：先止损，再复盘；复盘找原因，不找替罪羊","p":"出了事故，第一时间要做的是控制损失，而不是追问「谁干的」。事情平息后组织复盘：按时间线还原经过，找出流程、工具、分工上的漏洞，定下改进措施和负责人。复盘会上不点名羞辱，否则下次大家只会想办法把错误藏起来。屡教不改、故意违规的，另按制度处理。","tip":"「先别急着追责，我们一起把时间线理一遍，看看是哪个环节没拦住，下次怎么防。」","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"关系","who":"管理"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-9","b":"social","s":20,"n":9,"t":"让下属敢报坏消息、敢提反对意见","p":"如果下属一报坏消息就挨骂、一提不同意见就被怼，团队很快就只剩下「好的」「没问题」，直到问题大到藏不住。研究发现，团队成员觉得「说出问题不会被惩罚」时，学习和改进的效果更好。听到坏消息，先说「谢谢你早告诉我」；有人提了反对意见，即使不采纳，…","tip":"「这个风险你提得很及时，谢谢。我们一起看看怎么处理。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"管理"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-10","b":"social","s":20,"n":10,"t":"授权了就放手：说清边界和检查点，中间少插手","p":"把事交给下属，又天天盯着改细节、越过他直接指挥他的下属，等于没授权，还让他在团队里没面子。授权时说清楚：哪些可以自己决定，哪些要请示，什么时候同步一次进度。之后在检查点上看结果，中间他不来问，就别插手；方法和你不同但能达成目标的，尊重他。","tip":"「这个活动你全权负责，预算 5 万以内你自己定，超过的找我。每周五同步一次进度就行。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-11","b":"social","s":20,"n":11,"t":"团队成员闹矛盾：尽早介入，把人叫到一起，只谈事","p":"两个下属闹矛盾，拖着不管，很快会变成两拨人的对立。先分别听听两人的说法，不当场表态；再把两人叫到一起，围绕工作本身：分歧是什么、各自的顾虑是什么、按什么原则来定。能定的当场定，定不了的说明由你来决定，并解释理由。不在一方面前说另一方的不是。","tip":"「你们俩的出发点都是为了项目好，我们把分歧摆出来，按上线时间优先的原则来定。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"关系","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq20-12","b":"social","s":20,"n":12,"t":"绩效差的下属：早说、说具体、给期限；要辞退，依法办","p":"平时什么都不说，年底突然给个差绩效，下属会觉得被坑了。发现问题就尽早单独谈：哪里没达到要求、标准是什么、给多长时间改进、你能提供什么帮助，谈完留书面记录。改进期满仍不行的，可以调岗或协商解除。注意：考核排名末位不等于「不能胜任工作」，…","tip":"「这两个月的交付有三次延期，标准是按时率 90% 以上。接下来六周我们每周对一次进度，你看需要什么支持？」","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"自保","who":"管理"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq20-13","b":"social","s":20,"n":13,"t":"答应下属的事要兑现，兑现不了就早点说明原因","p":"管理者最值钱的是信用。「这个项目做完给你调薪」「下次培训名额给你」，说出口就是承诺。拿不准的事不要随口许诺；答应了但因为预算、政策变化做不到的，第一时间当面说明原因，并说清楚还能争取什么。一次说了不算，下属会把你以后的所有话都打折扣听。","tip":"「之前说的调薪，今年公司冻结了，我很抱歉没能兑现。我已经帮你申请了年底的专项奖，明年调薪窗口一开我第一个提。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq20-14","b":"social","s":20,"n":14,"t":"招人看能力和靠谱，不问婚育、不设性别门槛","p":"面试时问「有没有男朋友」「打算什么时候要孩子」，招聘启事写「限男性」，不但让候选人反感，还违反法律。面试围绕岗位需要的能力和过往的具体经历来问，比如「讲一件你推动跨部门协作的事」。录用标准对所有人一致，记录面试评价，经得起复核。","tip":"「请讲讲你上一个项目里最难的一个环节，你具体做了什么？」","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"自保","who":"管理"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq20-15","b":"social","s":20,"n":15,"t":"下属提离职：先听原因，能留就谈，留不住就好聚好散","p":"下属提离职，别第一反应就是生气或者冷落。先约个时间认真听：是钱的问题、成长的问题、还是和人的问题？能解决的，诚恳地谈；留不住的，帮他做好交接，按时办手续、开离职证明，别故意拖延或者在背调里说坏话。走得体面的人，日后可能回来，…","tip":"「很遗憾，但我尊重你的选择。交接我们一起排一下，有什么需要我帮忙的你说。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"管理"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq20-16","b":"social","s":20,"n":16,"t":"和下属亲近但有分寸：不称兄道弟，不在下属面前抱怨上级","p":"和下属关系融洽是好事，但走得太近，批评时开不了口，分配时被说偏心。可以关心他们的生活、一起吃饭聊天，但别和个别人形成小圈子，别和下属一起吐槽公司和你的上级。你在下属面前说的牢骚，会让整个团队都没了士气，也可能传到上面去。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-17","b":"social","s":20,"n":17,"t":"团建尽量放在工作时间，自愿参加，不劝酒","p":"占用周末、强制参加、喝到半夜的团建，对很多人来说是加班。团建尽量安排在工作日下午，形式多样一些，吃饭、运动、看展都可以，事先问问大家的意见。有人不喝酒、要接孩子、有事来不了，不追问、不计较。作为领导，你早点离场，大家才能放开玩。","tip":"「这次团建定在周四下午，不喝酒，有事来不了的跟我说一声就行。」","cost":{"money":"少","time":"中","will":"否","gain":"中","lens":"关系","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq20-18","b":"social","s":20,"n":18,"t":"带比你年长、资历深的下属：尊重经验，明确分工，多请教","p":"年轻人带老员工很常见，对方可能心里不服，也可能真的比你更懂业务。私下诚恳地请教他的经验，重要决策前听听他的意见；公开场合给他应有的尊重，把他擅长的事交给他负责。同时，分工和标准要清楚，该他完成的目标照样要完成，不能因为面子就放任不管。","tip":"「这块业务您比我熟，这次方案想先听听您的意见，再定分工。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"体面","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-19","b":"social","s":20,"n":19,"t":"自己判断错了，在团队面前认","p":"方向定错了、排期估错了、错怪了某个下属，很多管理者怕丢面子，选择不了了之。其实团队心里都清楚。大大方方地说一句「这次是我判断错了」，然后说清楚怎么调整，下属不会看轻你，反而会更信你；错怪了谁，要单独向他道歉。","tip":"「上周我坚持先做 A 功能，现在看判断错了，耽误了大家两周。我们调整一下，从今天起优先做 B。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"体面","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-20","b":"social","s":20,"n":20,"t":"替团队争资源，也替团队挡掉不合理的需求","p":"上面一句「下周加个需求」，你直接转给团队，大家就得通宵。管理者要先过滤：这件事的价值是什么、现有人手够不够、和已有任务冲突时先做哪个。不合理的，带着数据去和上级谈，要人、要时间或者砍需求；合理的，替团队争取到足够的资源，再布置下去。","tip":"「这个需求我们可以接，但要么把上线时间推一周，要么从测试组借两个人，您看哪种合适？」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"关系","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq20-21","b":"social","s":20,"n":21,"t":"加班要事出有因、提前安排，依法给加班费或调休","p":"偶尔赶工可以理解，长期把加班当常态，人会走、事会错，单位还要承担法律风险。确需加班，提前说明原因和时长，和大家商量；加完班按规定给加班费或者安排调休。你自己天天最后一个走，下属就不敢先走，要有意识地按时下班，给团队做个样子。","tip":"「这周五上线，周四晚上可能要加班到九点，周一大家可以晚到半天调休。」","cost":{"money":"多","time":"少","will":"否","gain":"大","lens":"自保","who":"管理"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq20-22","b":"social","s":20,"n":22,"t":"下属家里有急事、生病、生孩子：先给支持，按法定假期安排","p":"下属家人住院、自己生病、要生孩子，这时候领导的一句「先顾家里，工作我来安排」，他会记很多年。批假痛快，工作临时找人顶上，不在假期里频繁打扰。产假、陪产假、病假是法定权利，不能因此给差绩效或者变相逼走。","tip":"「你先去医院，手上的事交给小李，有需要随时说，不用着急回来。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"管理"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-1","b":"social","s":21,"n":1,"t":"和公司有矛盾，先走内部渠道，并且尽量用书面形式","p":"绩效不公、调岗不合理、工资算错了，第一步是找直属领导或人事沟通，说清楚事实和你的诉求。口头谈不拢，就发邮件或者正式的书面申请，写明时间、事实和要求。这样既给了公司纠正的机会，也为后面可能的仲裁留下了证据。","tip":"「关于 9 月绩效工资少发 2000 元的问题，我已在 10 月 8 日口头反映过，现书面申请核查，请在 10 月 20 日前答复。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq21-2","b":"social","s":21,"n":2,"t":"想跳槽：先找好下家再提离职，在公司内部别张扬","p":"裸辞后找工作，心态和议价能力都会变差，空窗期还要自己交社保。除非身体或心理已经撑不住，最好拿到书面录用通知后再提离职。找工作期间，不在工位上打招聘电话，不和同事聊跳槽的打算，请假面试用正常的理由。消息提前传到领导耳朵里，你会很被动。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq21-3","b":"social","s":21,"n":3,"t":"面试时不说老东家的坏话，不带走老东家的机密","p":"面试官问「为什么离职」，大骂前公司和前领导，对方只会想：将来你也会这样说我们。离职原因说正面的：想要更大的平台、想往某个方向发展。也不要为了展示能力，把老东家的客户名单、内部数据、源代码带去面试或者拷走，这可能侵犯商业秘密，要承担法律责任。","tip":"「在上家公司我把渠道从零做到了一千万，现在想找一个能做全国市场的平台。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-4","b":"social","s":21,"n":4,"t":"拿到录用通知，确认书面内容：岗位、薪资结构、入职时间","p":"口头说的「月薪三万」，可能包含了绩效、补贴，甚至年终奖摊下来的部分。拿到录用通知时确认清楚：基本工资多少、绩效和奖金怎么算、试用期多长、试用期工资多少、社保公积金按什么基数交、入职时间是哪天。最好是正式的邮件或盖章文件。背景调查如实配合，…","tip":"「想跟您确认一下：月薪 3 万是税前固定工资，还是包含绩效？年终奖是几个月，有没有发放条件？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq21-5","b":"social","s":21,"n":5,"t":"辞职提前 30 天书面通知就行，不需要公司批准","p":"很多人以为辞职要领导「批准」，领导不签字就走不了。其实法律规定，劳动者提前三十日以书面形式通知用人单位，就可以解除劳动合同；试用期内提前三日通知即可。辞职信写清楚姓名、岗位、最后工作日，交给领导或人事，并保留送达的证据，…","tip":"「本人因个人发展原因，申请于 2026 年 11 月 30 日解除劳动合同，最后工作日为当日。感谢公司的培养，交接工作我会全力配合。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"新人"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-6","b":"social","s":21,"n":6,"t":"公司欠薪、不交社保：可以随时解除合同，还能要经济补偿","p":"公司拖欠工资、不按规定交社保、不提供合同约定的劳动条件，劳动者可以解除劳动合同，并要求经济补偿。关键是解除通知里要写明理由，例如「因公司未及时足额支付劳动报酬」，并保留工资流水、社保记录等证据。如果写成「个人原因辞职」，…","tip":"「因公司自 2026 年 7 月起未足额支付工资，根据《劳动合同法》第三十八条，本人即日起解除劳动合同，并要求支付经济补偿。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-7","b":"social","s":21,"n":7,"t":"被通知辞退：先别签字，问清理由和法律依据","p":"人事突然叫你进会议室，拿出一份「协商解除协议」或者「辞职申请」让你签，这时最重要的是：不当场签任何文件。先问清楚：是公司单方面辞退还是协商解除？依据是哪一条？补偿怎么算？请对方书面出具。回去对照法律算清楚，再决定是谈、是签还是申请仲裁。","tip":"「这份协议我需要回去仔细看一下，请把解除理由和补偿方案发我邮箱，我三天内答复。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq21-8","b":"social","s":21,"n":8,"t":"经济补偿怎么算：N、N+1 和 2N 分别是什么","p":"N 是工作年限，每满一年给一个月工资，六个月以上不满一年按一年算，不满六个月给半个月；这里的月工资按离职前十二个月的平均工资计算，过高的有封顶。公司以「不能胜任」「客观情况重大变化」等理由辞退、又没有提前三十天通知的，要多付一个月工资，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-9","b":"social","s":21,"n":9,"t":"被逼「主动辞职」：调岗降薪、冷处理，别写个人原因辞职信","p":"有的公司不想付补偿，就用软办法逼人走：无故调到偏远岗位、大幅降薪、不派活、不让进系统、天天开会点名批评。这时不要一气之下写「个人原因」辞职。把调岗通知、工资变化、聊天记录都保存下来，书面表示不同意单方变更，必要时咨询 12333 或律师，…","tip":"「本人不同意公司单方调整岗位和降低工资，请按原劳动合同履行。」（书面发给人事）","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-10","b":"social","s":21,"n":10,"t":"离职交接列清单、双方签字，不删公司数据、不带走公司财物","p":"交接做得好，是给自己的职业声誉收尾。把负责的项目、客户、账号、文件、未完成事项列成清单，逐项交给接手的人，最后请对方和领导签字确认。电脑、门禁卡、公司资料按规定归还。千万别一气之下删除文件、清空邮箱、带走客户资料，…","tip":"","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-11","b":"social","s":21,"n":11,"t":"离职证明和社保转移是公司的义务，不能拿来卡人","p":"离职时，公司应当出具解除或终止劳动合同的证明，并在十五日内办理档案和社保关系转移。离职证明写的是合同期限、解除日期、工作岗位和工作年限，不应写对你的负面评价。公司以「交接没完」「赔偿没谈拢」为由拖着不开、导致你入职新公司受影响的，…","tip":"「我的最后工作日是 11 月 30 日，请在当天出具离职证明，并在 15 日内办理社保转移，谢谢。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-12","b":"social","s":21,"n":12,"t":"竞业限制：只限掌握商业秘密的人，最长两年，必须按月给补偿","p":"竞业限制是说离职后一段时间内不去竞争对手那里工作，也不自己干同类业务。它不是人人都能签：只适用于高管、高级技术人员和其他负有保密义务的人，期限最长两年，而且公司必须在离职后按月支付经济补偿。人社部 2025 年的合规指引还提出，…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-13","b":"social","s":21,"n":13,"t":"「提前走要赔钱」？法定的违约金只有两种","p":"有的合同写着「未满三年离职赔偿五万元」「离职未提前两个月通知扣一个月工资」。按照法律，单位只能在两种情况下约定由劳动者承担违约金：一是单位出钱给你做了专项技术培训、约定了服务期，违约金不超过培训费用，并按没履行的服务期分摊；…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"金钱","who":"新人"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-14","b":"social","s":21,"n":14,"t":"劳动仲裁不收费，时效一年，先打 12333 问清楚","p":"和单位谈不拢的劳动争议，先申请劳动仲裁，不服仲裁结果才能去法院起诉。仲裁不收费，自己就能去，不一定要请律师。注意时效：一般从知道权利被侵害之日起一年内申请；拖欠工资的，在职期间不受一年限制，但离职后要在一年内提出。不知道怎么办，…","tip":"","cost":{"money":"0","time":"多","will":"是","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-15","b":"social","s":21,"n":15,"t":"长期超时加班可以拒绝；先保留考勤和工作记录","p":"法律对加班有明确上限：一般每天不超过一小时，特殊情况每天不超过三小时，每月不超过三十六小时，还要和工会、劳动者协商。所谓「早九晚九、一周六天」的硬性规定，超出了法律上限。可以婉拒常态化的超时加班，…","tip":"「这周已经连续三天加班到十点了，今晚家里有事，明早我提前一小时到把剩下的做完。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-16","b":"social","s":21,"n":16,"t":"被拖欠工资：先书面催要，再投诉劳动监察或申请仲裁","p":"工资拖了，别只在群里抱怨。先给公司发一封书面的催款通知，写明拖欠的月份和金额。没有回应的，可以向当地劳动保障监察部门投诉，由监察部门责令限期支付，逾期不付的，单位还要额外加付赔偿金；也可以直接申请劳动仲裁，或者向法院申请支付令。…","tip":"「本人 2026 年 8 月、9 月工资合计 26000 元至今未发放，请于 10 月 31 日前足额支付，否则我将依法投诉和申请仲裁。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-17","b":"social","s":21,"n":17,"t":"和领导吵翻了，也别当场摔门走人","p":"吵到最后一句「老子不干了」，转身就走，第二天不来上班，看似痛快，实际上把主动权拱手让人：公司可以按旷工、严重违反规章制度把你辞退，而且不用付任何补偿。再生气，也按程序来：请假冷静几天，想清楚是谈、是走还是维权，然后书面提出。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq21-18","b":"social","s":21,"n":18,"t":"离职面谈：给一个得体的原因，不当场清算旧账","p":"人事和领导做离职面谈，可能真想了解问题，也可能只是走流程。可以客观地提一两条建设性的意见，比如流程、培训上的问题，但没必要把对某个人的积怨一股脑倒出来，那改变不了什么，只会让你走得很难看。原因可以说得体面一些：「想换个方向发展」。","tip":"「在这里学到很多，主要是想往产品方向发展。如果说建议的话，新人培训可以更系统一些。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq21-19","b":"social","s":21,"n":19,"t":"离职之后不说老东家坏话，和信得过的老领导、老同事保持联系","p":"同一个行业的圈子比你想象的小，你今天在新公司、在朋友圈里怎么评价老东家，迟早会传回去，下一次背景调查、下一次合作都可能受影响。离开后，和真正帮过你的老领导、老同事保持低频而真诚的联系：节日问候，看到对他有用的信息转一下，偶尔约个饭。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq21-20","b":"social","s":21,"n":20,"t":"想回老东家：好聚好散的回报，谈的时候按新人重新谈条件","p":"离开后发现老东家其实更合适，回去并不丢人，很多公司也欢迎熟悉业务的「回流员工」。前提是当初走得体面。回去之前想清楚：当初离开的原因解决了没有？然后像对待新机会一样，把岗位、薪资、级别谈清楚，不要因为是「回家」就不好意思提要求。","tip":"「王总，这一年在外面看了看，觉得还是咱们这边的方向更适合我。如果有合适的岗位，我很想回来，具体条件我们可以聊聊。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq21-21","b":"social","s":21,"n":21,"t":"裸辞前先算三笔账：存款、社保、失业保险","p":"辞职前算清楚：手里的存款够不够撑六个月以上的生活费和房贷房租；社保断缴会影响医保报销、买房买车资格和养老金累计，空窗期要不要以灵活就业身份自己交；失业保险金能不能领。按照《失业保险条例》，…","tip":"","cost":{"money":"多","time":"少","will":"否","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq21-22","b":"social","s":21,"n":22,"t":"内部转岗：先和现在的领导说，再去对接新部门","p":"想调到别的部门，最忌讳的是现在的领导从别人口中听说。先看公司的内部转岗制度，然后主动和直属领导沟通：为什么想转、想去哪里、交接怎么安排。领导支持，一切顺利；领导不同意，也要按制度走，不要私下绕开。转岗成功后，原来的工作交接好，…","tip":"「王总，我想跟您聊聊我的职业规划。我对数据分析一直很感兴趣，看到数据部在招人，想先听听您的意见。手上的工作我一定交接好。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-1","b":"social","s":22,"n":1,"t":"甲方乙方：地位可以不对等，尊重要对等","p":"做乙方，服务要到位，但不必卑躬屈膝，专业和靠谱才是你的底气；不合理的需求、超出合同范围的工作，可以礼貌地说明并商量费用。做甲方，提要求可以严格，但不要颐指气使、随意改需求、拖着不付款。今天的乙方，可能是明天的甲方，行业圈子很小。","tip":"（乙方）「这个新增功能不在原合同范围内，我们可以做，我先出一份补充报价和排期您看看。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-2","b":"social","s":22,"n":2,"t":"谈判前先想清楚：底线是什么，谈不成的退路是什么","p":"很多人谈判输在没准备：不知道自己能接受的最低价格，也不知道谈不成还有什么选择，结果被对方的气势和人情一步步推着走。谈之前写下来：最理想的结果、能接受的底线、谈不成时的最佳替代方案。替代方案越好，你在谈判桌上越从容。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"金钱","who":"生意"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-3","b":"social","s":22,"n":3,"t":"第一个报价会成为「锚」：有把握就先开价，被别人先开价时别被带着走","p":"谈判中第一个说出来的数字，会很大程度上影响最后成交的价格，这在心理学上叫「锚定」。如果你对行情心里有数，可以先报一个有依据、略有余地的价格；如果对方先报了一个离谱的价格，不要在它的基础上讨价还价，而是直接说明你的依据，重新给出你的数字。","tip":"「您报的价格比市场上同类服务高了 40%，按我们了解的行情和这次的工作量，我们的预算在 X 左右。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":"生意"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-4","b":"social","s":22,"n":4,"t":"让步要有交换，不白让，也不一次让到底","p":"对方一说「大家都是朋友，再便宜点」，你就降价，下一次他还会这样要求。每一次让步，都换回一点东西：降价可以，但付款周期要缩短；多送服务可以，但合同要签两年。让步的幅度要越来越小，让对方感觉到已经接近你的底线。","tip":"「价格可以再降 3%，但需要预付 50%，并且合同期签两年，您看可以吗？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-5","b":"social","s":22,"n":5,"t":"饭桌上的承诺不算数，一切以书面合同为准","p":"酒桌上拍着胸脯说的「这单就给你了」「价钱好说」，第二天可能谁都不记得了，或者对方根本没有决定权。饭局上谈得再热烈，第二天也要发邮件或消息总结要点，推进到正式的合同。同样，你自己在饭桌上也别随口许诺价格和交期。","tip":"「昨天跟您聊得很愉快，我把我们沟通的几点合作意向整理了一下，您看有没有出入？没问题的话我们推进合同。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq22-6","b":"social","s":22,"n":6,"t":"合同至少看清七件事：谁和谁、做什么、多少钱、怎么付、怎么验收、违约怎么办、去哪里打官司","p":"签合同前，不能只看金额。要看清：合同主体是不是你以为的那家公司；交付的内容、数量、质量标准是否写具体；价款含不含税、怎么支付、什么时间支付；怎样算验收合格；一方违约要承担什么责任；发生纠纷由哪里的法院管辖或者去哪个仲裁委员会。…","tip":"","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"自保","who":"生意"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq22-7","b":"social","s":22,"n":7,"t":"签约前查一查对方：工商信息、涉诉记录、是否失信","p":"对方说得再好，也要核实：公司是不是真实存在、注册资本和实缴情况、经营范围、股东和法定代表人是谁、有没有被列为经营异常；有没有大量的诉讼、是不是失信被执行人。这些都能在国家企业信用信息公示系统、中国执行信息公开网等官方平台免费查到。…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-8","b":"social","s":22,"n":8,"t":"签字盖章看三样：章和主体一致，签字的人有权限，多页合同盖骑缝章","p":"合同上的公章、合同专用章，名称要和合同里写的主体完全一致；签字的如果不是法定代表人，要求对方出具授权委托书；合同有好几页的，盖骑缝章，防止被替换页面。合同签好后，双方各执一份原件，扫描件存档。…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"生意"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq22-9","b":"social","s":22,"n":9,"t":"「定金」和「订金」差一个字，效果完全不同","p":"「定金」是法律上的担保：交定金的一方违约，定金不退；收定金的一方违约，要双倍返还；而且定金不能超过合同总额的 20%，超出部分不算定金。「订金」「意向金」「诚意金」一般只是预付款，违约时通常只能要求退还，没有双倍返还的效果。想让对方有约束，…","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-10","b":"social","s":22,"n":10,"t":"违约金约定要合理，太高太低都可以请求调整","p":"违约金不是越高越好。约定得过分高于实际损失的，违约方可以请求法院或仲裁机构适当减少；约定得低于实际损失的，守约方也可以请求增加。所以与其写一个吓人的数字，不如把违约的情形、计算方法写清楚，例如「每逾期一日，按未付款项的万分之五支付违约金」。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"金钱","who":"生意"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-11","b":"social","s":22,"n":11,"t":"回扣、返点、好处费：看起来是人情，其实是商业贿赂","p":"为了拿单子，私下给对方采购人员、经办人员送钱送卡、报销费用、安排旅游，或者给能影响交易的人「好处费」，都属于商业贿赂。法律允许的是明示的折扣和佣金：写进合同、开具发票、双方都如实入账。…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"生意"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq22-12","b":"social","s":22,"n":12,"t":"对方经办人暗示要好处：不给，并通过正式渠道反映","p":"「这个项目竞争很激烈，你懂的」「我们领导比较看重『诚意』」，这类暗示很常见。你给了，不但违法，还会被对方长期拿捏。可以装作听不懂，只谈产品和价格；对方明确索要的，记录下时间和内容，向对方公司的纪检、审计或举报渠道反映，…","tip":"「我们公司有严格的合规要求，所有优惠都写在报价单里，您看价格上还有什么需要我们调整的？」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq22-13","b":"social","s":22,"n":13,"t":"节日给客户送礼：先看对方公司的规定，价值适中、公开送","p":"逢年过节给客户送点东西，是维护关系的常见做法，但要守三条：一是先了解对方公司的礼品政策，很多公司规定员工不得接受超过一定价值的礼品；二是送公司层面的、价值适中的东西，比如定制的茶叶、本地特产，而不是现金、购物卡、奢侈品；三是公开送，…","tip":"「一点家乡的特产，是我们公司给各位合作伙伴准备的，感谢一年来的支持，大家分一分。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq22-14","b":"social","s":22,"n":14,"t":"商务宴请标准适中，不去低俗娱乐场所","p":"请客户吃饭，环境干净、菜品得体就够了，不必追求天价菜和名贵酒。更不要安排去有色情服务、赌博的场所「招待」，这类招待一旦出事，你和客户都要承担法律后果，还可能被拿来要挟。客户提出这类要求的，可以婉拒，换成正常的活动。","tip":"「今天就不去那边了，我知道附近有家茶馆挺安静的，我们换个地方再聊聊。」","cost":{"money":"多","time":"中","will":"些","gain":"中","lens":"自保","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq22-15","b":"social","s":22,"n":15,"t":"合伙开公司：先签股东协议，把出资、分工、分红、退出写清楚","p":"「我们是兄弟，不用写那么清楚」，是合伙生意最常见的悲剧开头。创业之初就要谈好、写好：每人出资多少、什么时候缴、谁负责什么、谁说了算、利润怎么分、有人中途要退出怎么办、意见僵持不下怎么办。2023 年修订的《公司法》规定，…","tip":"","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"自保","who":"生意"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq22-16","b":"social","s":22,"n":16,"t":"熟人生意也要明算账：报价、交付、付款照规矩来","p":"和亲戚朋友做生意，最怕「看着给」「先拿去用」。不谈清楚，你吃亏了不好意思说，对方也可能觉得你赚了他的钱。熟人生意更要把价格、数量、交付时间、质量标准、付款方式说清楚，最好也签个简单的协议。可以给熟人优惠，但优惠要明说，而不是含糊不清。","tip":"「咱们是自己人，我给你按成本价加 10%，比外面便宜两成。我们简单写个单子，你我都放心。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-17","b":"social","s":22,"n":17,"t":"给别人做担保要慎重：搞清楚是一般保证还是连带责任","p":"在借款合同的「保证人」一栏签字，就意味着对方还不上钱时，你可能要替他还。如果约定的是连带责任保证，债主可以不找借款人，直接找你要钱。法律规定，没有约定或约定不明的，按一般保证处理，但很多借款合同都会写明「连带责任」。…","tip":"「担保这件事我家里定过规矩，谁都不做，真不是针对你。你看看我能不能在别的方面帮上忙？」","cost":{"money":"多","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq22-18","b":"social","s":22,"n":18,"t":"用微信谈生意：重要事项用书面确认，聊天记录要保存","p":"很多生意都在微信上谈，语音一条接一条，事后找不到依据。价格、数量、交期、变更这样的重要事项，要用文字明确确认，最好再通过邮件或正式的补充协议固定下来。聊天记录、转账记录不要删除，换手机前备份。能够有形地表现内容、随时调取查用的电子数据，…","tip":"「刚才语音说的，我用文字确认一下：单价调整为 85 元，数量 2000 件，11 月 15 日前交货。没问题请回个『确认』。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"生意"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-19","b":"social","s":22,"n":19,"t":"催款先礼后兵：书面催告，留意三年诉讼时效","p":"对方拖着不付款，先客气地提醒，再发正式的书面催款函，写明合同、金额、到期日和最后期限；还不付，就发律师函、申请支付令、起诉或者申请仲裁。注意时效：一般是三年，从知道权利受损之日起算；每一次书面催要、对方承认欠款或者同意还款，…","tip":"「按照合同约定，第二期款项 15 万元应于 9 月 30 日支付，至今未到账。请于 10 月 31 日前支付，逾期我方将按合同约定追究违约责任。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"金钱","who":"生意"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-20","b":"social","s":22,"n":20,"t":"招投标不串标、不陪标：别人请你「帮忙凑个数」也不行","p":"「这个项目已经内定了，你来陪个标，下次有好项目给你」，这是串通投标的典型说法。投标人之间商量报价、轮流中标，或者和招标人串通，都是法律明确禁止的；情节严重的，还可能构成刑法上的串通投标罪。别人邀请你陪标，婉拒就好，不必为了人情卷进去。","tip":"「这个项目我们评估了一下，不太适合参与，就不凑这个热闹了，谢谢你想着我们。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"生意"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq22-21","b":"social","s":22,"n":21,"t":"合作结束：结清账目、交还资料，好聚好散","p":"合同到期或者合作不愉快要分开，最好把收尾做干净：对一遍账，结清款项，开好发票；归还对方的资料、样品、账号权限，删除按约定应当删除的数据；有必要的，签一份终止协议，写明双方没有其他纠纷。即使合作得不愉快，也不要在行业里到处说对方坏话。","tip":"「合作期间感谢各位的支持。这是双方的对账单，确认无误后我们签一份终止确认书，以后有合适的机会再合作。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq22-22","b":"social","s":22,"n":22,"t":"客户投诉：先接住情绪，再解决问题，最后改进流程","p":"客户带着火气来，先别急着解释「这不是我们的问题」。第一步，认真听完，承认对方的感受；第二步，弄清事实，提出具体的解决方案和时间；第三步，问题解决后回访一次，并在内部复盘，防止同样的事再发生。处理得好的投诉，客户往往比没出问题时更忠诚。","tip":"「给您添麻烦了，确实是我们的发货出了问题。今天下午我们重新补发，明天上午能到，运费我们承担，您看这样可以吗？」","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"关系","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq23-1","b":"social","s":23,"n":1,"t":"进了体制，先学规矩：程序和纪律比人情更重要","p":"体制内的很多事，看起来是人情，背后其实是程序：发文要走审批，花钱要按标准，用人要按条例，出差要按规定报销。新人入职后，把单位的工作规则、财务制度、保密规定、请销假制度认真看一遍，不懂的请教老同事。「以前都是这么办的」不能代替规定，出了问题，…","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"自保","who":"体制内"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq23-2","b":"social","s":23,"n":2,"t":"称呼按职务，党内称同志；场合不同，叫法不同","p":"正式场合，一般称「姓 + 职务」，比如「王局长」「李主任」；副职通常不带「副」字，但在同一场合有正职时要注意区分。党内倡导「一律称同志」，不搞「老板」「老大」之类的庸俗称呼。私下场合，跟着单位的习惯走，拿不准就用职务称呼，总不会错。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"体制内"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq23-3","b":"social","s":23,"n":3,"t":"请示和报告分清楚：请示一文一事，报告里不夹带请示","p":"需要上级批准的事，用「请示」，一份请示只讲一件事，写明理由、方案和建议；只是汇报情况、不需要批复的，用「报告」，不要在报告里顺带一句「妥否，请批示」。同样的道理也适用于口头汇报：先说清楚这次是「请您定一件事」还是「跟您汇报一下进展」。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"体制内"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq23-4","b":"social","s":23,"n":4,"t":"凡事按程序走，关键环节留痕","p":"领导口头交代的重要事项，事后形成书面记录或请领导在文件上签批；集体研究的事情，有会议纪要；花钱、用章、对外发文，严格按审批流程走。将来审计、巡视、追责时，能证明你依规办事的，只有这些记录。不要因为「领导急着要」就跳过程序，出了问题，…","tip":"「王局，您刚才交代的这件事，我拟个签报，您签一下字，我好按程序办。」","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"自保","who":"体制内"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq23-5","b":"social","s":23,"n":5,"t":"重大事项按规定请示报告，不搞先斩后奏","p":"体制内对哪些事情必须事先请示、哪些要事后报告，有明确的规定。超出自己职权范围的事，事先请示；遇到突发情况来不及请示的，先处置并第一时间报告。不要擅自决定、事后补手续，更不能隐瞒不报。个人层面的事，比如出国（境）、婚姻变化、子女从业等，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq23-6","b":"social","s":23,"n":6,"t":"开会守规矩：提前到场，手机静音，发言简短，会后落实","p":"体制内的会议比较多，也比较讲究。提前几分钟到场，按桌签或者安排就座；手机调静音，不在会上随意接打电话、刷手机；需要发言的，提前准备，紧扣议题，控制时间；会议布置的事项，会后记下来并按时落实。会上没讲的不同意见，会后按程序反映。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"体制内"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq23-7","b":"social","s":23,"n":7,"t":"写材料先看上级文件和领导讲话，用规范表述，数据要核实","p":"体制内的材料，讲究「有出处、有分寸」。动笔前，先找上级的相关文件、领导最近的讲话和单位以往的同类材料，弄清楚政策口径和规范的说法；引用的数据要和统计部门、业务部门核对一致；不确定的表述，宁可删掉也不要乱写。写完自己先通读一遍，…","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"关系","who":"体制内"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq23-8","b":"social","s":23,"n":8,"t":"不收可能影响公正执行公务的礼，也不给公职人员送礼","p":"管理和服务对象送的礼品、礼金、购物卡、有价证券，不管价值大小、以什么名义，原则上都不能收；推不掉的，及时登记上交。反过来，自己也不要给公职人员送礼，哪怕只是「过年的一点心意」。正常的亲友之间礼尚往来是允许的，但「明显超出正常礼尚往来」的，…","tip":"「谢谢您的心意，但我们有纪律，东西您一定得带回去。事情我会按规定尽快给您办好。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq23-9","b":"social","s":23,"n":9,"t":"不接受可能影响公正执行公务的宴请；公务接待按标准来","p":"管理服务对象请吃饭、请旅游、请健身娱乐，原则上一律谢绝。公务接待要有公函、按标准、在规定场所，工作餐不上高档菜肴和烟酒，不能借接待之名大吃大喝。和老同学、老朋友私人聚餐可以，但要注意对方是不是你的管理服务对象、谁买单、在什么场所，…","tip":"「饭就不吃了，有纪律要求。有什么问题，明天到办公室我们当面说。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq23-10","b":"social","s":23,"n":10,"t":"操办婚丧喜庆：控制规模，按规定报告，不借机收礼","p":"干部家里结婚、办丧事，是人之常情，但不能利用职权或者职务影响大操大办，更不能借机收管理服务对象的礼金。很多地方和单位要求事前报告规模、范围，事后报告收礼情况。宴请范围控制在亲友之间，礼金只收亲友正常往来的，下属和服务对象送的，…","tip":"","cost":{"money":"少","time":"少","will":"些","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq23-11","b":"social","s":23,"n":11,"t":"不经商办企业，不违规兼职取酬","p":"公务员和党员干部不得违反规定经商办企业、持有非上市公司股份、从事有偿中介活动；因工作需要在机关外兼职，要经过批准，而且不得领取兼职报酬。帮朋友的公司挂名当股东、法人，私下开网店、做代购、讲课收费，都可能触碰纪律红线。拿不准的，…","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq23-12","b":"social","s":23,"n":12,"t":"遇到亲属和利害关系，主动申请回避","p":"你要审批的项目里有亲戚的公司，你要面试的考生是朋友的孩子，你要处理的投诉涉及你的老同学，这时最安全的做法是主动说明情况、申请回避，而不是「我心里有数，会公正处理的」。法律对公务员的任职回避和公务回避都有明确规定，…","tip":"「这家企业的负责人是我表哥，按规定我需要回避，这个项目请安排其他同志审核。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq23-13","b":"social","s":23,"n":13,"t":"管理服务对象的钱、房、车，一样都不借","p":"「王科长，我那套房子空着，您先住着」「我的车闲着，您拿去用」「手头紧先从我这儿周转一下」，这种「帮忙」看起来是朋友情分，实际上是把你绑上了对方的船。向管理服务对象借钱、借房、借车，可能影响公正执行公务的，就违反了纪律；…","tip":"「谢谢您，这个真不行，我们有规定。我自己想办法。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq23-14","b":"social","s":23,"n":14,"t":"公车、公物不私用，也不长期占用","p":"开公车接孩子、周末用公车出游、把单位的电脑相机拿回家长期用、用单位的快递账号寄私人物品，这些「小事」在审计和巡察中经常被发现。公物公用，私事私办。确实需要临时借用的，按程序登记、按时归还。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq23-15","b":"social","s":23,"n":15,"t":"保密无小事：涉密内容不上网、不进微信、不随意带出","p":"涉密文件不能用普通电脑处理，不能通过微信、QQ、个人邮箱传送，不能拍照发群里，不能随手带回家。没有标密的内部文件、会议内容、工作安排，属于工作秘密，也不要外传、不要发朋友圈。很多泄密都不是故意的，而是「随手一发」。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq23-16","b":"social","s":23,"n":16,"t":"网上发言要谨慎：单位内部的事不晒，身份敏感的话不说","p":"在朋友圈晒工作场景、吐槽单位和群众、转发未经证实的消息、和网友争论敏感话题，在体制内都有风险，一张截图就可能引发舆情。可以分享生活，但不暴露单位内部的情况；对公共事件的看法，以不违反纪律和规定为前提；以工作身份对外发言，…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"体制内"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq23-17","b":"social","s":23,"n":17,"t":"有人托你「打招呼」：按规定办，干预过问如实记录","p":"亲戚朋友托你「跟承办人打个招呼」「帮忙关照一下」，最稳妥的回答是：按规定办，该怎么办就怎么办。你自己是承办人，有人来打招呼的，按单位的制度记录并报告。司法机关有专门的「三个规定」，…","tip":"「这个事我不方便过问，您按正常程序去申请，有什么不清楚的流程我可以帮您问问。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq23-18","b":"social","s":23,"n":18,"t":"进步靠实绩和组织程序，不跑官要官","p":"干部的选拔任用有一套严格的程序：动议、民主推荐、考察、讨论决定、任前公示。拉关系、送钱物、托人说情来求提拔，不但违反纪律，还可能卷进腐败案件。能做的，是把本职工作做出成绩，在推荐和考察中经得起群众评价；对选拔结果有意见，按程序反映。","tip":"","cost":{"money":"0","time":"多","will":"是","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq23-19","b":"social","s":23,"n":19,"t":"辞职或退休后，几年内不去原来管的企业任职","p":"公务员辞去公职或退休后，原系领导成员、县处级以上领导职务的，三年内，其他公务员两年内，不得到与原工作业务直接相关的企业或营利性组织任职，也不得从事与原工作业务直接相关的营利活动。准备离开体制的，提前了解这些规定，别被高薪邀约冲昏头脑。","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq23-20","b":"social","s":23,"n":20,"t":"对办事群众热情、公正，不吃拿卡要","p":"窗口和一线工作人员，是群众眼里政府和单位的形象。办事流程一次讲清楚，材料一次性告知；能办的马上办，不能办的说明理由和依据；不因为对方是熟人就开绿灯，也不因为对方不懂就刁难。「门难进、脸难看、事难办」的问题，现在都可以被投诉、被通报。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"体面","who":"体制内"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq23-21","b":"social","s":23,"n":21,"t":"体制内也有自己的权益救济：对处分、辞退不服可以复核申诉","p":"受了处分、被辞退、考核被定为不称职、工资福利被违规扣减，觉得不公平的，不要只在私下发牢骚。公务员可以在知道人事处理之日起三十日内向原处理机关申请复核，对复核结果不服的再申诉，也可以直接申诉。准备好事实和证据，按程序反映。","tip":"","cost":{"money":"0","time":"中","will":"是","gain":"中","lens":"自保","who":"体制内"},"grade":"A","disputed":true,"ev":"法条","hasRef":false},{"id":"rq24-1","b":"social","s":24,"n":1,"t":"办事之前先查清楚：办事指南、材料清单、办理时间","p":"现在大部分政务事项都有公开的办事指南，可以在当地政务服务网、政务服务 App 或小程序上查到要什么材料、去哪里办、能不能网上办、要多久。拿不准的，打 12345 政务服务便民热线问清楚。去之前把原件、复印件、照片、表格都准备好，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-2","b":"social","s":24,"n":2,"t":"对窗口工作人员客气，把诉求一句话说清楚","p":"窗口工作人员每天要面对大量的人，你客气一点、条理清楚一点，事情往往办得更顺。开口先说你要办什么事、你已经准备了哪些材料；有不懂的地方，请对方指一下；对方说材料不对，先问清楚具体缺什么、哪里不合格，不要一上来就发火。","tip":"「您好，我来办新生儿落户，出生证明、户口本、父母身份证和结婚证都带了，麻烦您看看还缺什么。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-3","b":"social","s":24,"n":3,"t":"材料不齐，窗口应当一次性告知要补什么","p":"「今天缺这个，明天再来」「下次还要带那个」，让人来回跑好几趟，是很多人最头疼的事。按照法律，申请行政许可时材料不齐全或者不符合要求的，行政机关应当当场或者在五日内一次性告知需要补正的全部内容；逾期不告知的，从收到材料之日起就视为受理。…","tip":"「麻烦您把需要补充的材料一次性给我列一下，我回去一起准备，免得再跑一趟。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq24-4","b":"social","s":24,"n":4,"t":"遇到推诿刁难：先问依据，再打 12345 或做「差评」","p":"工作人员说「不归我们管」「规定就是这样」「你找领导去」，可以平静地问：依据是哪一条规定？应该去哪个部门？能不能给个书面的答复？依然推诿的，记下时间、窗口号和工作人员工号，拨打 12345 投诉，或者在政务服务的「好差评」系统里如实评价。…","tip":"「我理解您的难处。能不能告诉我这是依据哪个文件，或者我应该去哪个部门办？」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"官方文件","hasRef":false},{"id":"rq24-5","b":"social","s":24,"n":5,"t":"能按流程办的事，别托关系「打招呼」","p":"本来正常排队就能办的事，托人打招呼，不但欠下一个人情，还可能让熟人为难，甚至让他违反纪律。真正需要帮忙的，是弄清楚流程、找对部门，这可以问熟人，但不要请他「插队」「通融」。涉及资格审核、招生录取、执法处罚的，托关系还可能卷入违法违纪的事。","tip":"「我不是要你帮忙走后门，就是想问问这个事该找哪个部门、要准备哪些材料。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq24-6","b":"social","s":24,"n":6,"t":"对行政决定不服：申请行政复议或提起行政诉讼，注意期限","p":"被罚款、被拒绝发证、被认定不符合条件，觉得不合理的，可以先申请行政复议。2023 年修订的《行政复议法》扩大了复议范围，申请一般应在知道该行政行为之日起六十日内提出；也可以直接向法院提起行政诉讼，一般在知道之日起六个月内。…","tip":"","cost":{"money":"0","time":"多","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq24-7","b":"social","s":24,"n":7,"t":"信访要依法逐级反映，到指定场所，不聚集、不缠访","p":"对国家机关及其工作人员有意见、有诉求，可以通过信访反映。按照规定，信访一般采用书信、网上、电话等形式，或者到有关机关设立的接待场所当面反映；多人反映共同意见的，推选代表。涉及诉讼、仲裁、行政复议等法定途径的事项，要先走法定途径。…","tip":"","cost":{"money":"0","time":"多","will":"是","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-8","b":"social","s":24,"n":8,"t":"想知道政府的决定依据：可以申请政府信息公开","p":"拆迁补偿的标准、某个审批的依据、某项收费的文件，如果没有主动公开，公民可以向有关行政机关申请公开。申请时写清楚你的身份信息、要获取的信息内容和获取方式。行政机关一般应当在规定期限内答复，不予公开的要说明理由。拿到的信息可以作为维权的依据。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-9","b":"social","s":24,"n":9,"t":"消费纠纷：先找商家协商，不行就打 12315","p":"买到假货、服务缩水、预付卡老板跑路，先带着小票、合同、聊天记录找商家协商；协商不成，可以通过全国 12315 平台或者拨打 12315 投诉，也可以找消费者协会调解，必要时起诉。网购的商品，除定制、鲜活易腐、拆封的数字商品等例外，…","tip":"「这件商品和页面描述的材质不符，我要求退货退款，否则我将向 12315 投诉。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq24-10","b":"social","s":24,"n":10,"t":"看病前准备好：症状经过、既往病史、用药清单和想问的问题","p":"门诊时间很短，说不清楚就容易漏掉重要信息。去之前写下来：哪里不舒服、从什么时候开始、有没有加重、做过什么检查、正在吃什么药、有没有过敏史和慢性病，再把想问医生的两三个问题列好。带上以前的病历和检查报告。看完后，没听懂的地方当场问清楚，…","tip":"「医生，我最想弄清楚两件事：这个病要不要做手术？这个药要吃多久？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-11","b":"social","s":24,"n":11,"t":"不给医生送红包，也不收「医托」的好意","p":"很多人担心不送红包医生不用心，其实医务人员收受红包、回扣是明令禁止的，送了反而可能让医生为难。真想表达感谢，出院后送一面锦旗、写一封感谢信，或者在医院的评价系统里点名表扬。另外，医院门口主动搭讪、说「带你找专家」「某某诊所效果更好」的，…","tip":"「谢谢您这些天的照顾，这是我们一家人写的感谢信。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq24-12","b":"social","s":24,"n":12,"t":"发生医疗纠纷：先复印、封存病历，再走调解、鉴定或诉讼","p":"怀疑治疗出了问题，最重要的是保全证据：患者有权查阅、复制病历资料，医院应当提供复制服务；发生纠纷需要封存病历的，要在医患双方都在场的情况下进行，开列封存清单、双方签字。之后可以协商、申请人民调解或者行政调解，…","tip":"「我们要求复印全部病历，并在双方在场的情况下封存病历原件。」","cost":{"money":"少","time":"多","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq24-13","b":"social","s":24,"n":13,"t":"再生气也不医闹：打砸、围堵、拉横幅都可能违法","p":"亲人在医院出了意外，情绪失控可以理解，但在医院里打骂医护人员、聚众堵门、摆设灵堂、拉横幅，不但解决不了问题，还可能被行政拘留，情节严重的构成犯罪。把精力用在保全证据、申请鉴定和找律师上，才是真正为亲人讨说法。","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq24-14","b":"social","s":24,"n":14,"t":"和老师沟通：先约时间，私下说，就事论事","p":"孩子回家说在学校受了委屈，家长的第一反应往往是去找老师理论。先听孩子把事情讲完整，再私下联系老师，约个方便的时间，用「了解情况」而不是「兴师问罪」的语气开场。说清楚你看到的情况和担心，听听老师的说法，最后商量一起怎么帮孩子。…","tip":"「王老师，孩子回家说今天课间和同学有点矛盾，我想跟您了解一下情况，看看我们在家怎么配合。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-15","b":"social","s":24,"n":15,"t":"不给老师送礼，感谢可以用别的方式","p":"教师节、毕业季，家长群里常有人张罗给老师送礼。按照规定，教师不得索要、收受学生及家长的财物，送了反而让老师为难，还可能被举报。真想表达感谢，让孩子亲手写一张卡片、画一幅画，或者给学校写一封表扬信，老师会更珍惜。有人在群里组织凑钱送礼，…","tip":"「我们家就让孩子写张卡片给老师了，礼物就不参与了，谢谢您组织。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":"父母"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-16","b":"social","s":24,"n":16,"t":"家长群里：不刷屏、不攀比、不争吵，私事私聊","p":"家长群是用来传达通知的，不是社交场。老师发了通知，不需要每个人都回复「收到」，除非老师要求；不在群里发广告、拉投票、晒孩子的成绩；个别孩子的问题，私聊老师，不在群里讨论；家长之间有矛盾，私下解决，别在群里互相指责。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq24-17","b":"social","s":24,"n":17,"t":"孩子被欺凌：先了解事实、保留证据，书面要求学校处理","p":"孩子被同学反复嘲笑、孤立、索要财物、推搡殴打，不是「孩子之间闹着玩」。先耐心听孩子讲，记下时间、地点、经过和涉及的同学；有伤的及时就医，保留诊断证明和照片；然后书面向班主任和学校反映，要求调查处理。学校有义务建立学生欺凌防控制度，…","tip":"「孩子这两周三次被同班同学推倒，这是就医记录。我们请学校按欺凌防控制度调查处理，并书面告知处理结果。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":"父母"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-18","b":"social","s":24,"n":18,"t":"孩子之间起冲突：先听自家孩子说完，别急着上门讨说法","p":"小孩子之间的摩擦很常见，孩子的描述也难免片面。先让孩子完整地讲一遍，问问对方为什么这么做、你自己做了什么；如果是一般的小矛盾，可以引导孩子自己解决；需要家长出面的，通过老师约对方家长，大家心平气和地沟通。…","tip":"（对孩子）「你慢慢说，当时发生了什么？他为什么推你？你那时候在做什么？」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-19","b":"social","s":24,"n":19,"t":"报警时说清时间、地点、经过，记下接警信息","p":"遇到盗窃、诈骗、人身伤害、骚扰，及时拨打 110 或到派出所报案。说清楚：发生了什么、在哪里、什么时间、对方的特征或身份、有没有人受伤、你手上有哪些证据。报案后，记下接警的派出所、民警姓名和联系方式，有受案回执的保存好，…","tip":"「我要报案，今天下午三点左右，我在某某小区门口被人抢了手机，对方是一名穿黑色外套的男子，往东边跑了。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq24-20","b":"social","s":24,"n":20,"t":"去法院立案：符合条件的应当登记立案","p":"欠钱不还、合同纠纷、侵权赔偿，协商不成可以起诉。法院实行立案登记制，起诉状写清原告被告的身份信息、诉讼请求、事实和理由，附上证据，符合法律规定的，法院应当登记立案；当场不能判定的，应在法定期限内决定是否立案。现在很多法院支持网上立案，…","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq24-21","b":"social","s":24,"n":21,"t":"被热心服务过，也记得表扬一句","p":"办事遇到耐心负责的窗口人员、救治及时的医生、尽心尽力的老师，花一分钟在「好差评」系统里点个好评，或者写一封感谢信给他们的单位。这些表扬会进入他们的考核，对他们来说比一份礼物更有分量，也让认真做事的人得到正向反馈。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-1","b":"social","s":25,"n":1,"t":"搬进新家，主动和邻居打个招呼","p":"城市里很多人住了好几年都不知道对门是谁。搬家或者装修前，敲开左右和上下的门，简单介绍一下自己，留个联系方式，可以带一点水果或者小零食。以后装修吵到人家、快递需要代收、家里漏水要关阀门，有个能说上话的邻居，会方便很多。","tip":"「您好，我们是新搬来 1202 的，接下来装修可能会有点吵，给您添麻烦了。这是我的电话，有什么问题随时找我。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-2","b":"social","s":25,"n":2,"t":"装修前告知物业和邻居，严格按规定时间施工","p":"装修是邻里矛盾的头号来源。开工前到物业办理装修登记，了解小区允许施工的时间段；在电梯和单元门口贴一张告示，写明工期和联系方式；嘈杂的拆墙、打孔安排在工作日白天，周末和午休时间尽量不做；装修垃圾按规定清运，不堆在楼道。","tip":"（告示）「1202 室将于 3 月 1 日至 5 月 30 日装修，施工时间为工作日 8:30—12:00、14:00—18:00，给大家带来不便，敬请谅解。…","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq25-3","b":"social","s":25,"n":3,"t":"自己家里也要控制噪声，夜里十点以后尤其注意","p":"拖椅子、穿硬底拖鞋来回走、孩子在地板上跑跳、深夜洗衣服、电视和音响开得很大声，对楼下来说都是折磨。可以在椅子腿上贴脚垫，给孩子活动的区域铺地垫，洗衣机、跑步机避开深夜。法律规定的「夜间」是晚上十点到第二天早上六点，这段时间更要安静。","tip":"","cost":{"money":"少","time":"少","will":"些","gain":"大","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq25-4","b":"social","s":25,"n":4,"t":"被噪声困扰：先当面沟通，再找物业、居委会，最后报警","p":"很多噪声问题，邻居自己并不知道。先找个白天的时间，客气地上门说明：什么时间、什么声音、对你有什么影响，提出具体的请求。沟通没用的，找物业或者居委会协调，必要时申请人民调解。持续干扰、经劝阻和调解仍不停止的，可以报警，由公安机关依法处理。…","tip":"「不好意思打扰您，最近晚上十一点以后楼上经常有拖椅子的声音，孩子总被吵醒，能不能麻烦您晚上注意一下？」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq25-5","b":"social","s":25,"n":5,"t":"家里漏水影响楼下：先止损，再拍照、找物业，主动协商赔偿","p":"楼下找上门说漏水，先别急着否认，第一时间关阀门、找物业排查原因。确实是你家的问题，主动道歉，尽快维修，和楼下一起拍照记录受损情况，协商赔偿的方式和金额，可以请物业作见证。如果是楼上漏到你家，同样先拍照、找物业，礼貌地要求对方处理，…","tip":"「真对不起，物业查了是我们家卫生间防水的问题，我们这周就修。您家天花板的损失我们来承担，您看是我们找人修，还是折算成钱给您？」","cost":{"money":"多","time":"中","will":"些","gain":"大","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-6","b":"social","s":25,"n":6,"t":"养狗要拴绳、清粪、不扰民；被狗咬了马上处理伤口并留证","p":"遛狗拴好牵引绳，进电梯抱起来或者让其他人先走，粪便随手清理，不让狗在夜里长时间吠叫。法律对养犬人的责任规定得很重：动物伤人，饲养人原则上要承担责任；没拴绳、违反管理规定的，责任更重；禁止饲养的烈性犬伤人，饲养人要承担全部责任。被狗咬了，…","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-7","b":"social","s":25,"n":7,"t":"楼道和消防通道不是自家储物间","p":"鞋柜、旧家具、纸箱、自行车、腌菜坛子堆在楼道里，平时看着只是不美观，一旦发生火灾，就会堵住所有人的逃生通路。楼道、安全出口、消防车通道都不能占用、堵塞，这是法律的硬性要求。邻居堆了东西，可以先私下提醒，不改的请物业处理。","tip":"「王阿姨，楼道里这几个箱子放着不太安全，万一着火了大家都不好跑，要不我帮您搬回家里？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq25-8","b":"social","s":25,"n":8,"t":"电动车不推进楼道、不进电梯，不私拉电线充电","p":"电动自行车电池起火速度快、温度高、烟气毒，楼道和电梯里起火，往往造成严重伤亡。不要把电动车推进楼道、电梯和家里，不要从窗户「飞线」充电，尽量使用小区的集中充电设施；电池不要私自改装、不要买来路不明的「大容量」电池。看到邻居这样做，可以提醒，…","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-9","b":"social","s":25,"n":9,"t":"不占别人的车位，不堵车库和消防通道","p":"别人买了或租了的车位，就算空着也不要停；临时停一下，在车上留下挪车电话。不要把车停在车库出入口、消防通道和别人家门口。自己的车位被占了，先打电话请对方挪车，或者找物业处理，不要用锁车、扎胎、堵车的方式报复，那样你也要承担责任。","tip":"（留言条）「您好，这是我的固定车位，麻烦您下次停到访客车位，谢谢！电话：138xxxx。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-10","b":"social","s":25,"n":10,"t":"高空抛物是违法犯罪，教孩子也别往窗外扔东西","p":"从楼上扔下一个苹果、一个酒瓶，都可能致人重伤甚至死亡。法律明确禁止从建筑物中抛掷物品；情节严重的，构成高空抛物罪。找不到具体是谁扔的，可能加害的整栋楼住户都可能要给予补偿。家里有小孩的，要告诉他们窗外不能扔东西，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-11","b":"social","s":25,"n":11,"t":"可视门铃和摄像头，别对着邻居家的门","p":"装个摄像头防盗可以理解，但如果正对着对门邻居的房门，邻居每天什么时候出门、谁来家里，都被你拍得一清二楚，这可能侵犯别人的隐私。安装时让镜头只拍自家门口的范围，安装前跟邻居打个招呼；邻居的摄像头对着你家，可以先沟通，沟通不了找物业，…","tip":"「您家装的摄像头好像正对着我们家门，能不能麻烦您调一下角度？」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-12","b":"social","s":25,"n":12,"t":"物业费按约定交；对服务不满意，走业主大会和法律渠道","p":"对物业不满意，很多人选择不交物业费，结果被起诉，还要付滞纳金。法律规定，物业按约定提供了服务的，业主不能以「我不需要」为由拒交。反过来，物业也不能用停水、停电、停暖、停气的方式催缴。对物业服务不满意，可以通过业主大会、业主委员会反映、监督，…","tip":"","cost":{"money":"多","time":"少","will":"些","gain":"中","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-13","b":"social","s":25,"n":13,"t":"住宅改成民宿、群租房、工作室，要经过受影响邻居的同意","p":"把自家住宅改成民宿、棋牌室、培训班、群租房，人员进进出出，噪声和安全隐患都会增加。法律规定，业主把住宅改变为经营性用房，除遵守法律法规和管理规约外，还要经过有利害关系的业主一致同意。邻居这样做影响到你的，可以要求停止，协商不成可以起诉。","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-14","b":"social","s":25,"n":14,"t":"向邻居借东西：按时还，完好还，弄坏了主动赔","p":"借个梯子、电钻、折叠桌，是邻里之间的常事。用完了尽快还，擦干净再还；弄坏了，主动说明并赔偿或者买个新的。借了不还、还回去脏兮兮的，下次就借不到了，邻居心里也会有疙瘩。别人借你的东西，不方便的话可以直说。","tip":"「上次借您的电钻用完了，充好电了，谢谢啊！」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq25-15","b":"social","s":25,"n":15,"t":"帮邻居代收快递：说清楚责任，贵重物品别代收","p":"帮邻居代收快递是举手之劳，但万一丢了、坏了，可能说不清楚。日常的包裹可以帮，收到后拍个照片发给对方，尽快交给他；贵重物品、生鲜冷链、需要验货的，建议对方自己收或者放快递柜。邻居帮你收了，及时去取，道个谢。","tip":"「你的快递我帮你收了，外包装是好的，放在我家门口了，你回来记得拿哈。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-16","b":"social","s":25,"n":16,"t":"邻居家有喜事、丧事：表示心意即可，不必攀比","p":"邻居家生孩子、孩子考上大学、老人过世，见面说一声恭喜或者节哀，关系好的送点水果、红包，按当地的习惯来，不用太重。邻居家办丧事、搭灵棚、放鞭炮，可能会影响到你，在合理的范围内多一分体谅；时间过长、影响过大的，再委婉地沟通。","tip":"「听说您家孩子考上大学了，真替你们高兴！一点心意，给孩子买本书。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq25-17","b":"social","s":25,"n":17,"t":"和邻居闹僵了：不升级、不报复，找人民调解","p":"邻里纠纷最怕的是互相报复：你堵我车、我泼你门，你装震楼器、我报警投诉，最后两家都过不安生。真的谈不拢，可以请居委会、村委会或者人民调解委员会调解。人民调解不收费，达成的调解协议可以在三十天内共同申请法院司法确认，确认后一方不履行的，…","tip":"","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq25-18","b":"social","s":25,"n":18,"t":"关心身边的独居老人，留个联系电话","p":"楼里的独居老人，出了意外可能好几天都没人发现。平时见面多打个招呼，好几天没见到、门口的报纸牛奶堆着没取，敲门问一句；互相留个电话，也存一下他子女的联系方式。下雨下雪天，帮忙捎点菜，帮个小忙。","tip":"「李奶奶，这是我的电话，家里有什么事、身体不舒服，随时给我打。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-19","b":"social","s":25,"n":19,"t":"阳台晾衣、浇花、抽烟时，替楼下想一想","p":"楼上的衣服没拧干，水滴到楼下刚晒好的被子上；花盆浇水，泥水顺着外墙流下去；在阳台抽烟，烟味飘进楼下的卧室。这些小事积累起来，最伤邻里感情。衣服拧干了再晾，浇花用托盘接水，抽烟尽量离开窗边或者到楼下的室外空地。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq25-20","b":"social","s":25,"n":20,"t":"农村邻里：通行、排水、宅基地，按「方便生活、公平合理」来商量","p":"在农村，邻里纠纷常常集中在宅基地边界、出行的路、排水的沟、盖房子挡了光。法律规定，邻居因为通行等必须经过你家土地的，应当提供必要的便利；用水、排水也应当提供必要的便利。盖房子不能妨碍邻居的通风、采光和日照。边界不清的，…","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq25-21","b":"social","s":25,"n":21,"t":"对邻居有意见，别在小区群里点名、贴大字报","p":"气不过的时候，很多人会在业主群里点名道姓地指责邻居，或者在电梯里贴告示「曝光」。这样做很容易引发更大的冲突，内容不实或者带有侮辱性的，还可能侵犯对方的名誉权，被起诉要求赔礼道歉、赔偿损失。有问题私下说，或者请物业、居委会出面。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq26-1","b":"social","s":26,"n":1,"t":"加微信先说明身份和来意，别只发一个「你好」","p":"陌生人的好友申请，如果什么都不写，或者只写「你好」，很多人不会通过。在验证消息里写清楚：你是谁、谁介绍的或者在哪里认识的、找对方有什么事。通过之后，第一条消息再简单说明来意，并改好备注。","tip":"「王老师您好，我是某某公司的小李，张总介绍我向您请教一下数据合规的问题。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq26-2","b":"social","s":26,"n":2,"t":"不要只发「在吗」，有事直接说","p":"只发一句「在吗」「方便吗」，对方不知道你要干什么，回也不是，不回也不是，心里还会犯嘀咕。有事情直接在一条消息里说清楚：什么事、需要对方做什么、什么时候要，对方有空的时候就能直接回复。","tip":"「李姐，想问一下上次那家装修公司的联系方式，你方便的时候发我就行，不急。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq26-3","b":"social","s":26,"n":3,"t":"能打字就别发长语音，重要的事用文字","p":"一连串 60 秒的语音，对方在开会、在地铁里没法听，想找其中一句话还得从头听一遍。日常聊天、亲密关系之间发语音没问题，但工作、商量事情、对长辈以外的人，尽量用文字；地址、电话、金额、时间这类信息，一定用文字发。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq26-4","b":"social","s":26,"n":4,"t":"节日祝福别群发，带上称呼和一句具体的话","p":"逢年过节收到一大堆复制粘贴的祝福，很多人看都不看，甚至觉得被「群发」了有点敷衍。真想维系的关系，挑出几十个人，每条都带上称呼，加一句和对方有关的话，比如回忆一件事、问候一下家人。关系一般的，不发也不失礼。","tip":"「张老师，春节快乐！去年您推荐的那本书我读完了，受益很大。祝您和师母新年身体健康！」","cost":{"money":"0","time":"中","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq26-5","b":"social","s":26,"n":5,"t":"工作群里被 @ 了要回复，回「收到」再说什么时候处理","p":"领导或同事在群里 @ 你，就是在等你的回应。看到了，及时回复「收到」，能马上处理的说「马上处理」，需要时间的说清楚预计什么时候给结果。没有回应，对方不知道你看到了没有，很容易被误会成不负责任。处理完了，再在群里回复一下结果。","tip":"「收到，今天下午五点前把修改后的版本发群里。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq26-6","b":"social","s":26,"n":6,"t":"工作群的规矩：只谈工作，不刷屏，私事私聊","p":"工作群是办公的地方：不发与工作无关的链接、广告、拉票、表情包刷屏；两个人之间的讨论，超过三五个来回就转到私聊；在群里不批评人、不吵架；发文件写清楚文件名和版本；下班后、周末不在群里讨论不紧急的事。领导在群里发了重要通知，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq26-7","b":"social","s":26,"n":7,"t":"下班后和深夜，不发不紧急的工作消息","p":"你在晚上十一点想起一件事，顺手发给同事，对方可能就要被迫加班或者一晚上睡不好。不紧急的工作，用定时发送功能，或者记下来第二天上班再发；真的紧急，直接打电话说明情况。作为领导，更要注意，你的一条消息，下属会当成命令。","tip":"（真紧急时）「抱歉这么晚打扰，客户那边系统崩了，需要你帮忙看一下。」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq26-8","b":"social","s":26,"n":8,"t":"拉人进群先问一声；建群说明目的，事办完了可以解散","p":"突然被拉进一个几百人的群，里面全是不认识的人和广告，很让人反感。拉人之前私下问一句「方便拉你进个群吗」，说明这个群是干什么的；建群后在群公告里写清楚群的用途和规矩；临时为了一件事建的群，事情办完了就解散或者说明可以自由退出。","tip":"「我们准备建个同学聚会的筹备群，就讨论时间地点，聚完就解散，拉你进来可以吗？」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq26-9","b":"social","s":26,"n":9,"t":"当了群主就要管群：违法和侵权的内容及时处理","p":"群主和管理员不是只负责拉人的，按照规定，互联网群组的建立者、管理者应当履行群组管理责任，规范群里的信息发布。群里有人发色情、赌博、诈骗链接、谣言，或者有人在群里辱骂、曝光别人的隐私，群主要及时提醒、删除、移出群聊，必要时向平台举报。","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq26-10","b":"social","s":26,"n":10,"t":"转账要写清楚用途；收到不明转账先别点收款","p":"借钱给别人，转账时备注「借款」；还钱时备注「还某月借款」；替别人垫付的，备注清楚是什么费用。一旦发生纠纷，这些备注和聊天记录就是证据。收到陌生人或者说不清来由的转账，先别急着点收款，问清楚是怎么回事；对方说「转错了，麻烦你转回来」，…","tip":"（转账备注）「借款 5000 元，约定 2026 年 12 月 31 日前归还。」","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq26-11","b":"social","s":26,"n":11,"t":"私聊的内容，别随手截图转给别人","p":"朋友私下跟你吐槽、倾诉、说了一些不想让别人知道的事，你截图发给第三个人，哪怕只是「给你看看这个人多搞笑」，一旦传回去，信任就彻底没了。涉及别人隐私的聊天记录，未经同意公开传播，还可能侵犯隐私权。真需要拿聊天记录维权的，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq26-12","b":"social","s":26,"n":12,"t":"朋友圈晒生活，别把孩子、住址、行程都晒出去","p":"孩子穿着校服的照片、小区门牌、车牌、机票登机牌上的二维码、「全家出去旅游一周」的定位，这些信息拼在一起，足以让不法分子知道你家在哪、孩子在哪上学、家里什么时候没人。晒照片前，把门牌、车牌、证件、校名打上码；旅游的照片回来再发；…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq26-13","b":"social","s":26,"n":13,"t":"给领导、长辈、异性的朋友圈点赞评论，把握分寸","p":"朋友圈的评论，共同好友都能看到。给领导的朋友圈点赞即可，评论简短得体，不开玩笑、不刷屏式吹捧；长辈发的养生文章，不在评论区反驳，有问题私聊；异性朋友的照片，特别是对方有伴侣的，评论别太暧昧。拿不准的，点个赞就好。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq26-14","b":"social","s":26,"n":14,"t":"有意见当面说，别在朋友圈指桑骂槐","p":"「有些人表面一套背后一套」「某些人自己心里清楚」，这类朋友圈谁都看得出在说谁，却又谁都不好接话。被说的人会记恨，旁观的人会觉得你小气。有矛盾，私下找对方说清楚；不想说，就安静地远离。朋友圈「仅某人可见」地发一段阴阳怪气的话，…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq26-15","b":"social","s":26,"n":15,"t":"没核实的消息不转发，尤其是「紧急扩散」类的","p":"「某地发生重大事故」「某小区出现传染病」「某品牌食品致癌」，这类消息往往打着「紧急」「速转」的旗号，传得快，辟谣慢。转发前先看来源是不是官方，搜一搜有没有权威媒体报道或辟谣。故意散布谣言、谎报险情疫情灾情扰乱公共秩序的，要被拘留罚款；…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq26-16","b":"social","s":26,"n":16,"t":"网上骂人、造谣，和当面骂人一样要担责","p":"隔着屏幕，很多人觉得骂两句没人知道。实际上，公然侮辱他人或者捏造事实诽谤他人，要受治安管理处罚；侵犯他人名誉权，要承担停止侵害、赔礼道歉、赔偿损失的民事责任；在网上诽谤他人，同一信息被点击浏览五千次以上或者被转发五百次以上的，…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq26-17","b":"social","s":26,"n":17,"t":"被网暴了：先开防护，再取证，然后投诉、报警或起诉","p":"遭遇网暴，第一步是保护自己：在平台上开启防护功能，比如屏蔽陌生人、关闭评论和私信、设置内容仅好友可见。第二步是取证：截图、录屏，记下网址、账号和时间，可以使用平台提供的快捷取证功能，必要时公证。第三步是维权：通过平台的网暴投诉入口举报，…","tip":"","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq26-18","b":"social","s":26,"n":18,"t":"不「人肉」、不曝光别人的个人信息","p":"看到网上的争议事件，有人会去扒当事人的姓名、电话、住址、单位、家人照片，再公开发出来。不管当事人对错，这种做法都可能侵犯隐私和个人信息，引发线下的骚扰甚至伤害。向他人出售或者提供个人信息，要受治安管理处罚；情节严重的，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq26-19","b":"social","s":26,"n":19,"t":"「帮忙砍一刀」「帮我投个票」：可以不参与","p":"砍价、助力、投票、点赞的链接，经常要求授权个人信息、下载 App、绑定手机号，有的还是诈骗或者刷票。亲友发来的，可以帮就帮，不想帮也不必勉强，不回复或者简单说一句「最近不太方便点链接」就行。自己尽量少发这类链接给别人，特别是关系一般的人。","tip":"「我手机设置了不点外部链接，这次就不帮你砍了哈，祝你砍成功！」","cost":{"money":"0","time":"少","will":"否","gain":"小","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq26-20","b":"social","s":26,"n":20,"t":"删好友、拉黑，安安静静地做，不必公开宣布","p":"关系淡了、闹僵了、对方让你不舒服，可以删除或者拉黑，这是你的自由。但不用在朋友圈宣布「已拉黑某某」，也不必删之前发一大段控诉。对于以后还可能碰面的人，比如同事、亲戚，可以先设置「不让他看我的朋友圈」「不看他的朋友圈」，保持表面的和气。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq26-21","b":"social","s":26,"n":21,"t":"网友见面：选公共场所，告诉家人朋友，自己回家","p":"网上聊得再投机，见面时也是陌生人。第一次见面选人多的公共场所，白天见，自己去、自己回；把对方的信息、见面地点和时间告诉一位家人或朋友，约定好报平安的时间；不去对方家里或者酒店，不喝离开过视线的饮料。对方提出借钱、投资、带你去「一个好地方」，…","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"自保","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq26-22","b":"social","s":26,"n":22,"t":"守好自己的账号：不出借，开好安全设置，换手机先解绑","p":"微信、支付宝、银行 App 不只是聊天工具，更是你的钱包和身份。几件事值得现在就做：开启登录保护和支付密码，不用生日、手机号做密码；定期查看登录过的设备，删掉不认识的；设置紧急联系人，账号被盗时能找回；…","tip":"「验证码是登录我账号用的，谁问都不能给，你直接找客服吧。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq27-1","b":"social","s":27,"n":1,"t":"到了陌生的地方，拿不准就问当地人","p":"去外地参加婚礼、葬礼、拜年，第一次去伴侣老家，最稳妥的办法是提前问：问伴侣、问当地的朋友、问主人家关系近的人。问清楚穿什么、带什么、随多少、几点到、有什么禁忌。主动问不丢人，自作主张犯了忌讳才尴尬。","tip":"「我第一次参加你们这边的婚礼，不太懂规矩，礼金一般随多少？有什么要注意的吗？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"体面","who":"异乡"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq27-2","b":"social","s":27,"n":2,"t":"尊重少数民族的风俗习惯，尤其是饮食禁忌","p":"和信仰伊斯兰教的少数民族朋友一起吃饭，选清真餐厅，不点含猪肉的菜，也不要在饭桌上拿这个开玩笑；去少数民族地区，了解当地的节日、服饰和礼节，不随意触碰别人的宗教用品。各民族都有保持或者改革自己风俗习惯的自由，这是写在宪法里的。","tip":"「我们订了一家清真餐厅，你看可以吗？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"体面","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq27-3","b":"social","s":27,"n":3,"t":"第一次见对方父母：礼数按对方家乡的来，提前问伴侣","p":"有的地方讲究第一次上门要带够几样礼品、给长辈红包，有的地方长辈会给上门的晚辈「见面礼」，有的地方吃饭时座位、敬酒都有讲究。这些都要提前问伴侣：带什么、带多少、要不要给红包、对方父母有什么忌讳和喜好。伴侣也要提前在父母面前帮你铺垫。","tip":"（问伴侣）「你爸妈喜欢什么？你们那边第一次上门有没有什么讲究，比如要不要包红包？」","cost":{"money":"多","time":"少","will":"些","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq27-4","b":"social","s":27,"n":4,"t":"彩礼和嫁妆的地域差异很大，商量时参考当地习惯，也要守法律底线","p":"不同地区的彩礼数额可能相差几十倍，有的地方还有「三金」「改口费」「压箱钱」等讲究。双方家庭来自不同地方的，彩礼按哪边的习惯来，最好由两个年轻人先商量好，再各自和父母沟通。无论哪里的习俗，借婚姻索取财物都是法律禁止的；彩礼返还等纠纷，…","tip":"","cost":{"money":"多","time":"中","will":"是","gain":"大","lens":"金钱","who":"婚恋"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq27-5","b":"social","s":27,"n":5,"t":"婚礼上的「闹婚」要有底线，低俗、伤人的不参与","p":"接亲时的堵门、婚宴上的小游戏，图的是热闹喜庆。但给新人、伴娘伴郎涂抹、捆绑、强迫喝酒、做带有性意味的动作，就越界了，近年来因为闹婚导致受伤、被起诉的事件并不少见。作为新人，提前和亲友打好招呼，定下规矩；作为宾客，别人起哄时不跟着闹，…","tip":"（新人提前说）「我们这次婚礼不搞闹伴娘那一套，大家吃好喝好，玩点轻松的游戏就行。」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"自保","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq27-6","b":"social","s":27,"n":6,"t":"参加丧事：衣着素净，表情庄重，不嬉笑、不玩手机","p":"去吊唁、参加追悼会和葬礼，穿黑、灰、深蓝等深色素净的衣服，不穿大红大绿、不化浓妆、不戴夸张的首饰。到场后按照主人家的安排行礼，不大声说笑，不在灵堂前拍照、玩手机。各地丧葬礼俗不同，比如是否需要戴孝、跪拜、守夜，听从主人家的安排就好。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq27-7","b":"social","s":27,"n":7,"t":"吊唁时说话：简单表达哀悼，不追问死因，不说空洞的大道理","p":"见到逝者家属，一句「节哀顺变」「有什么需要帮忙的尽管说」就够了，握握手、拍拍肩，比很多话都有用。不要追问「怎么走的」「是不是没及时送医院」，不要说「他走了也是解脱」「你要坚强」，更不要在这个时候谈遗产、谈借款。过一段时间，…","tip":"「阿姨，您节哀。叔叔的事我们都很难过，这几天有什么需要跑腿的，您随时叫我。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq27-8","b":"social","s":27,"n":8,"t":"白事礼金：数额、用什么颜色的信封、要不要回礼，各地讲究不同","p":"白事随礼，有的地方习惯用白色信封，有的地方讲究礼金用单数，有的地方主人家会退回一部分或者回赠毛巾、糖果之类的回礼，有的地方则不收礼金。拿不准的，问和主人家关系近的亲友，或者跟着同去的人一起随。礼金一般不必比红事多，心意到就好；…","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq27-9","b":"social","s":27,"n":9,"t":"进寺庙、教堂、清真寺：衣着得体，守规矩，拍照先问","p":"宗教场所是信众的圣地，不是普通景点。进去之前看一下门口的须知：有的要求不穿短裤短裙、背心，有的要求脱鞋，有的区域不对外开放；说话小声，不随意触摸佛像、经书等宗教物品；不在正在进行的仪式中穿行或拍照，拍照前看看有没有禁止的标识，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq27-10","b":"social","s":27,"n":10,"t":"同一个称呼，换个地方意思可能就变了","p":"称呼的分量各地并不一样：在有的地方，「师傅」是对所有人的客气称呼，在有的地方只用来叫司机和手艺人；「老板」「美女」「帅哥」在一些城市是日常招呼，在正式场合或者对长辈就显得轻浮；「小姐」在不少地方带有不好的联想，…","tip":"「您好，请问怎么称呼您比较合适？」","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":"异乡"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq27-11","b":"social","s":27,"n":11,"t":"过年的习俗各家不同：年夜饭几点吃、初几去谁家，提前商量","p":"有的地方年夜饭中午吃，有的晚上吃；有的地方初一不出门，有的初一就要挨家拜年；有的地方女儿初二回娘家，有的没有这个讲究。夫妻来自不同地方的，过年去谁家、怎么安排，提前商量好，必要时各让一步，比如今年在这边，明年在那边。","tip":"「今年我们先在你家过年三十，初二回我家，你看你爸妈能接受吗？」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq27-12","b":"social","s":27,"n":12,"t":"坐月子、满月、抓周等习俗：尊重心意，不科学的做法可以温和地改","p":"生孩子前后，长辈往往有很多讲究：月子里不能洗头洗澡、不能开窗、要捂得严严实实、要一直躺着。这些出于关心，但其中一部分并不科学，甚至可能有害，比如夏天捂月子可能导致中暑。可以先肯定长辈的心意，再拿医生的建议来说话，必要时请医生直接跟长辈解释。…","tip":"「妈，谢谢您这么用心照顾我。医生说可以用温水擦身、保持通风，我们就按医生说的来，您帮我盯着别着凉就行。」","cost":{"money":"少","time":"少","will":"是","gain":"大","lens":"关系","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq27-13","b":"social","s":27,"n":13,"t":"清明祭扫：文明祭祀，林区墓地不烧纸、不放鞭炮","p":"清明节、寒衣节、祭日去扫墓，是缅怀亲人的重要时刻。但在山林、墓区焚烧纸钱、燃放鞭炮，很容易引发山火，不少地方明确禁止野外用火。可以用献花、植树、擦拭墓碑、写一封信的方式祭扫，很多地方也提供网上祭扫。去之前看一下当地墓园的规定。","tip":"","cost":{"money":"少","time":"中","will":"否","gain":"中","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq27-14","b":"social","s":27,"n":14,"t":"不搞「地域黑」，不拿口音和家乡开玩笑","p":"「你们那儿的人都……」，这种话说出来可能只是开玩笑，听的人却会觉得被冒犯，而且对一个人的判断，被你用他的出身就代替了。不要拿别人的口音、家乡的食物、刻板印象开玩笑；在群里看到地域黑的言论，不转发、不附和。了解一个人，看他做的事，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"体面","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq27-15","b":"social","s":27,"n":15,"t":"在农村，红白事上搭把手，也是一种随礼","p":"在不少农村地区，谁家办红白事，左邻右舍都会来帮忙：搭棚、借桌椅、洗菜、端盘子、迎客、记账。这种「出力」本身就是人情的一部分，以后你家有事，大家也会来帮你。回老家赶上了，主动问一句有什么能帮忙的；在外地赶不回去的，可以请家人代为表达。","tip":"「叔，我今天没什么事，帮您看着点礼账吧，有什么要搬的也叫我。」","cost":{"money":"0","time":"中","will":"否","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq27-16","b":"social","s":27,"n":16,"t":"在外地生活，尊重本地人的生活习惯","p":"到一个新城市生活，会发现很多不一样的地方：垃圾分类的要求、排队的习惯、说话的节奏、饮食的口味、对「准时」的理解。少用「我们那儿怎么怎么样」来比较，多观察本地人是怎么做的。学几句本地话，了解一点本地的历史和饮食，很容易拉近和本地人的距离。","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"关系","who":"异乡"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq27-17","b":"social","s":27,"n":17,"t":"饭桌上的地方讲究，跟着主人走","p":"有的地方鱼上桌时鱼头要朝向主宾，有的地方吃鱼不能翻面，有的地方主人要先动筷子，有的地方敬酒有固定的顺序和说法，有的地方劝菜劝酒格外热情。到了别人的地盘，不要自作主张，主人怎么安排就怎么来；对方的讲究你不理解，也别当场质疑。…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"中","lens":"体面","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq27-18","b":"social","s":27,"n":18,"t":"习俗和法律冲突时，以法律为准","p":"有些所谓的「老规矩」，其实已经违法：不到法定婚龄就办酒席「先结婚」、换亲、包办婚姻、高价彩礼「卖女儿」、为已故的人「配阴婚」而买卖甚至盗挖尸骨、丧事上「闹丧」堵路索要高额赔偿。不管当地多少人这么做，都不是你也跟着做的理由。…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq27-19","b":"social","s":27,"n":19,"t":"带外地或外国伴侣回家，提前给双方「翻译」习俗","p":"伴侣来自不同的地方甚至不同的国家，双方家庭的习惯可能大相径庭：怎么称呼、要不要给红包、能不能拒绝夹菜、长辈问收入是不是冒犯。你是唯一同时了解两边的人，提前给伴侣讲清楚你家的规矩和长辈的脾气，也提前跟父母打好招呼，…","tip":"（对父母）「她那边过年不兴给红包，她要是没准备，你们别多想，她心意都在礼物里了。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq27-20","b":"social","s":27,"n":20,"t":"习俗会变：尊重老一辈的坚持，也不必事事照搬","p":"很多习俗正在变化：彩礼和份子钱在一些地方被倡导「减负」，婚丧事被提倡简办，网上拜年、电子红包越来越普遍。对长辈很在意的习俗，能照顾的尽量照顾，那是他们的情感寄托；对铺张浪费、加重负担的旧俗，可以温和地带头改变。改变的时候，…","tip":"「爸，我们这次婚礼想办得简单一点，省下的钱给你们换个好点的空调，您看亲戚那边您帮我们解释解释？」","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-1","b":"social","s":28,"n":1,"t":"被欺负时的顺序：先保安全，再留证据，最后维权","p":"遇到殴打、威胁、骚扰，第一件事是让自己脱离危险：离开现场、到人多的地方、躲进能锁门的房间、拨打 110。安全之后，再考虑证据：拍照、录音、保存聊天记录、记下在场的人。最后才是维权：报警、投诉、调解、起诉。顺序不能颠倒，…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-2","b":"social","s":28,"n":2,"t":"留痕要成体系：时间线、聊天记录、录音录像、证人、病历票据","p":"零散的证据很难说服别人，成体系的证据才有力量。准备一份时间线文档：每次发生了什么、什么时间、在哪里、谁在场、你怎么回应的；配上对应的聊天截图、录音、视频、照片、病历、转账记录、证人的联系方式。记录越及时、越具体，可信度越高。…","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-3","b":"social","s":28,"n":3,"t":"录音可以作为证据，但不能用违法手段取得","p":"很多人担心「偷偷录音不合法」。一般来说，你作为当事人，录下自己和对方的对话，用来证明对方说过的话，是可以作为证据的。但如果是以严重侵害他人合法权益、违反法律禁止性规定或者严重违背公序良俗的方法取得的，比如在别人家里偷装窃听器，…","tip":"（录音中自然地确认）「王总，你说的意思是，上个月的提成这个月也不发了，对吗？」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq28-4","b":"social","s":28,"n":4,"t":"证据保存原件，多处备份，重要的做公证或电子存证","p":"聊天记录被对方撤回、删除，手机丢了、坏了，证据就没了。重要的聊天记录截图后，再导出或备份；录音录像保留原始文件，同时上传到云盘；纸质证据复印并拍照。对方可能删除的网页、帖子，可以做公证或者使用可信的电子存证服务固定下来。…","tip":"","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-5","b":"social","s":28,"n":5,"t":"被打了：报警、就医、验伤，别急着私了","p":"被人殴打后，第一时间报警，让警察到场固定证据；去医院就诊，如实告诉医生受伤的经过，保留病历、检查报告和医药费票据；伤得比较重的，申请伤情鉴定。不要因为对方当场塞几百块钱就签「私了协议」，有些伤当时看不出严重程度。殴打他人的，…","tip":"","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq28-6","b":"social","s":28,"n":6,"t":"正当防卫受法律保护，但别「打红了眼」","p":"面对正在发生的不法侵害，为了保护自己或他人，采取制止侵害的行为，属于正当防卫，不负刑事责任。对正在进行的行凶、杀人、抢劫、强奸、绑架等严重危及人身安全的暴力犯罪，采取防卫行为造成侵害人伤亡的，不属于防卫过当。…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq28-7","b":"social","s":28,"n":7,"t":"被威胁、跟踪、反复骚扰：报警，公安可以责令对方不得接触你","p":"有人写信、发消息威胁你的人身安全，或者反复发侮辱、恐吓、淫秽信息，在你家楼下、单位门口蹲守跟踪，这些都不是「私人恩怨」，而是违反治安管理的行为。保存好每一条消息、每一次被跟踪的时间地点和照片，向公安机关报案。…","tip":"","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq28-8","b":"social","s":28,"n":8,"t":"前任纠缠骚扰：明确说不，留证，报警，申请保护令或禁令","p":"分手或者离婚后，对方不停地打电话、发消息、堵门、找你的家人朋友、威胁曝光你的隐私，最重要的是一次性、明确地表态「我不同意复合，请不要再联系我」，之后不再回应，不见面「最后谈一次」。保留所有记录，报警处理。…","tip":"（最后一条消息）「我们已经分手了，我不会复合。请不要再联系我和我的家人，否则我会报警并申请保护令。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq28-9","b":"social","s":28,"n":9,"t":"遭受家暴：报警、验伤、申请保护令，必要时去庇护场所","p":"家暴不是「家务事」。被打了，第一时间报警，警察会出警处理，情节较轻的也可以对加害人出具告诫书；去医院验伤，保留病历和照片。可以向法院申请人身安全保护令，法院应当在七十二小时内作出裁定，情况紧急的二十四小时内作出，…","tip":"","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq28-10","b":"social","s":28,"n":10,"t":"遇到性骚扰：明确拒绝、保存证据、向单位投诉，也可以报警和起诉","p":"违背你的意愿，用言语、文字、图片、身体接触等方式对你进行性骚扰，你有权要求对方承担责任。当场能表态的，明确说「请停止」；保存聊天记录、邮件、照片，记下时间地点和目击者；在单位发生的，向人事、合规、工会等部门投诉，单位有义务调查处理；…","tip":"","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq28-11","b":"social","s":28,"n":11,"t":"防范「被下药」：酒杯不离视线，感觉异常立刻求助，事后尽快报警验血","p":"在酒吧、聚会、和不熟的人吃饭时，饮料和酒杯不要离开自己的视线，离开座位回来后的饮料别再喝；不喝陌生人递来的已经开封的饮料。如果喝了一点就感到异常头晕、意识模糊、手脚发软，立刻告诉信得过的朋友或店员，拨打 110，不要跟陌生人走。…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-12","b":"social","s":28,"n":12,"t":"被偷拍：当场制止或报警，要求删除，不要私下「交易」","p":"在地铁、商场、试衣间、酒店发现有人偷拍，或者发现房间里有可疑的摄像头，安全的情况下可以当场制止、大声求助，并立即报警，让警察检查和固定对方手机里的内容。不要自己去抢手机，避免冲突升级。偷窥、偷拍、窃听、散布他人隐私，要受治安管理处罚；…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq28-13","b":"social","s":28,"n":13,"t":"被领导当众辱骂、人格侮辱：批评可以接，侮辱不必忍","p":"「你是猪吗」「你爸妈怎么教的你」「长成这样还好意思」，这些已经不是工作批评，而是人格侮辱。可以当场平静地说「请您就事论事」；事后记录下时间、原话和在场的同事，有条件的录音；向人事、更高一级领导或者工会反映。用人单位侮辱、体罚劳动者的，…","tip":"「王总，这件事是我做得不好，我接受批评。但请您不要说我家人。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq28-14","b":"social","s":28,"n":14,"t":"借钱时没写借条：让对方用文字确认借款，再配上转账记录","p":"碍于情面没写借条的钱，并不是就要不回来了。只有一张转账记录，对方可能说「那是你还我的钱」或者「是你送我的」；所以要补上能证明「借款」这层关系的证据。可以用文字消息自然地提起：写明时间、金额和「借」字，问对方什么时候方便还。…","tip":"「上次三月份借你的两万块，你看什么时候方便还我？我这边下个月要交房租。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq28-15","b":"social","s":28,"n":15,"t":"追讨欠款：书面催告、申请支付令、小额诉讼，必要时财产保全","p":"对方拖着不还，先发消息或书面催告，写明金额和最后期限，这能让诉讼时效中断、重新计算。事实清楚、没有其他纠纷的，可以向法院申请支付令，债务人要在收到支付令十五日内清偿或者提出书面异议，不异议也不还的，你可以申请强制执行。…","tip":"","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-16","b":"social","s":28,"n":16,"t":"被冤枉、被诬告：别认没做过的事，要求对方拿出证据","p":"在商场被店员怀疑偷东西、在单位被诬陷拿了公物、被人举报做了根本没做的事，第一反应不要是慌乱或者为了息事宁人而「认了」。冷静地要求对方说明依据、拿出证据；商家怀疑你偷东西，可以报警让警察处理，但经营者无权搜查你的身体和随身物品，…","tip":"「我没有拿。您如果有怀疑，我们报警，让警察来处理，但您没有权利搜我的包。」","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq28-17","b":"social","s":28,"n":17,"t":"被敲诈勒索、被威胁曝光隐私：不转钱，留证据，马上报警","p":"「不给钱就把你的照片发给你所有的联系人」，这是裸聊敲诈、私密照勒索的典型套路。对方拿到第一笔钱后，几乎一定会要第二笔、第三笔。正确的做法是：不再回应、不转一分钱；保存聊天记录、对方账号、转账信息；立即报警；同时提醒亲友，…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-18","b":"social","s":28,"n":18,"t":"存好这几个求助电话，关键时刻不用到处找","p":"遇事不知道找谁，是很多人维权失败的第一步。建议存好：110 报警；120 急救；96110 反诈预警咨询；12348 公共法律服务（法律咨询、法律援助）；12338 妇女维权；12355 青少年服务；12333 人社服务（劳动纠纷、社保）；…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-19","b":"social","s":28,"n":19,"t":"名誉、隐私被侵害：可以要求道歉、消除影响，严重的要求精神损害赔偿","p":"被人造谣、诋毁、曝光隐私，除了报警之外，还可以通过民事诉讼要求对方停止侵害、删除内容、赔礼道歉、消除影响、恢复名誉，并赔偿你的经济损失；造成严重精神损害的，可以要求精神损害赔偿。停止侵害、消除影响、恢复名誉、赔礼道歉的请求，…","tip":"","cost":{"money":"少","time":"多","will":"是","gain":"中","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq28-20","b":"social","s":28,"n":20,"t":"维权不等于报复：不私刑、不暴力讨债、不以牙还牙","p":"被欠钱就把人关起来「谈」、找人上门泼油漆堵锁眼、在网上发动亲友网暴对方、私自扣押对方的东西，这些「维权」方式可能让你从受害者变成违法者：非法限制他人人身自由的，构成非法拘禁罪；使用暴力、胁迫等方法催收高利放贷等产生的非法债务，情节严重的，…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-21","b":"social","s":28,"n":21,"t":"请不起律师，可以申请法律援助","p":"很多人觉得打官司要花很多钱，干脆放弃了。其实国家有法律援助制度：经济困难的公民，在追索劳动报酬、工伤赔偿、赡养费抚养费、请求给予社会保险待遇等事项上，可以申请免费的法律援助，由律师提供咨询、代写文书、代理诉讼。…","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq28-22","b":"social","s":28,"n":22,"t":"受了伤害，也要照顾自己的心：必要时寻求专业帮助","p":"被家暴、被骚扰、被网暴、被骗之后，很多人会长期失眠、焦虑、自责，觉得「是我自己太傻」。这些反应很正常，错的不是你。和信任的家人朋友说说，不要一个人扛；持续影响生活和工作的，寻求心理咨询或者精神科医生的帮助。…","tip":"","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq29-1","b":"social","s":29,"n":1,"t":"先分清人情和贿赂：看身份、看请托、看价值","p":"判断一份「心意」是不是贿赂，可以问三个问题：第一，对方给你东西，是因为你这个人，还是因为你手里的职权？第二，对方有没有正在或者将要找你办的事？第三，价值是不是明显超出了你们之间正常的礼尚往来？亲戚朋友之间婚丧嫁娶的正常往来，不是贿赂；…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq29-2","b":"social","s":29,"n":2,"t":"行贿也是犯罪：为谋取不正当利益送钱，一般三万元就够立案","p":"很多人以为只有收钱的人才犯法，送钱的人是「被逼无奈」。其实，为谋取不正当利益给予国家工作人员财物，就构成行贿罪。按照司法解释，行贿数额在三万元以上的，就要追究刑事责任；一万元以上不满三万元，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq29-3","b":"social","s":29,"n":3,"t":"2024 年起，行贿的七种情形要从重处罚","p":"2024 年 3 月 1 日起施行的刑法修正案（十二）加大了对行贿的惩处，「受贿行贿一起查」。下列情形从重处罚：多次行贿或者向多人行贿；国家工作人员行贿；在国家重点工程、重大项目中行贿；为谋取职务、职级晋升、调整行贿；…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq29-4","b":"social","s":29,"n":4,"t":"被索贿、没得到不正当利益的，不是行贿；但要尽快反映","p":"办正当的事，却被对方明示暗示「不给好处就卡着」，这是索贿。法律规定，因被勒索给予国家工作人员财物，没有获得不正当利益的，不是行贿。但「被勒索」需要证据证明，最好的做法是：不给；如果已经被迫给了，保留好聊天记录、转账记录和证人，…","tip":"「这件事我是按正常程序申请的，材料都齐全。如果有什么问题，请您书面告诉我依据。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq29-5","b":"social","s":29,"n":5,"t":"卷进去了：被追诉前主动交待，法律给出路","p":"如果过去确实行过贿，越拖越被动。法律规定，行贿人在被追诉前主动交待行贿行为的，可以从轻或者减轻处罚；犯罪较轻的、对调查突破或侦破重大案件起关键作用的，或者有重大立功表现的，可以减轻或者免除处罚。最好在律师的帮助下，…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq29-6","b":"social","s":29,"n":6,"t":"「感情投资」也有红线：给上级或管理对象的财物达三万元，可能被视为受贿","p":"「我没有具体求他办什么事，就是平时逢年过节表示一下。」这种「感情投资」并不安全。司法解释规定，国家工作人员索取、收受具有上下级关系的下属，或者具有行政管理关系的被管理人员的财物，价值三万元以上、可能影响职权行使的，视为承诺为他人谋取利益。…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq29-7","b":"social","s":29,"n":7,"t":"贿赂不只是现金：购物卡、装修、免债、旅游、会员都算","p":"司法解释明确，贿赂犯罪中的「财物」包括货币、物品和财产性利益：替你装修房子、免除你的债务、给你办会员卡、请你出国旅游，都按实际支付的金额计算。司法实践中，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq29-8","b":"social","s":29,"n":8,"t":"家人收的礼也会算到你头上：管好家属，交代清楚","p":"请托人找不到你，往往会找你的配偶、子女、父母。司法解释规定，特定关系人索取、收受他人财物，国家工作人员知道后未退还或者上交的，应当认定国家工作人员具有受贿故意。家属本人利用你的影响力收钱帮人办事，还可能单独构成利用影响力受贿罪。…","tip":"「以后不管谁送东西、托你办事，你都说『家里有规矩，不收不管』，然后告诉我。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq29-9","b":"social","s":29,"n":9,"t":"「帮着打个招呼」也可能是受贿：斡旋受贿的风险","p":"有些人觉得，事情不归我管，我只是给管这件事的同事打个招呼，收点「辛苦费」不算受贿。其实，国家工作人员利用本人职权或者地位形成的便利条件，通过其他国家工作人员职务上的行为，为请托人谋取不正当利益，索取或者收受财物的，以受贿论处。…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq29-10","b":"social","s":29,"n":10,"t":"别当「中间人」：介绍贿赂、截留好处，都是犯罪","p":"「你跟那个领导熟，帮我递个话，事成之后少不了你的。」在请托人和国家工作人员之间沟通关系、撮合条件、使贿赂得以实现的，构成介绍贿赂罪；在对方不知情的情况下把钱留给自己的，可能构成利用影响力受贿罪；明明不认识却吹嘘关系、骗取钱财的，构成诈骗罪。…","tip":"「这种事我真帮不了，也劝你别这么办，按正常程序走最稳妥。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq29-11","b":"social","s":29,"n":11,"t":"「花钱能进编制」「花钱能捞人」：不是诈骗就是行贿","p":"「我认识人社局的领导，二十万保你考上事业编」「交五十万，保证让你家孩子进名校」「花点钱能把案子摆平、人捞出来」，这类话听到就该警惕。公务员录用要通过公开考试、严格考察、平等竞争、择优录取，事业单位也实行公开招聘。绝大多数「包办」的人是骗子，…","tip":"","cost":{"money":"多","time":"少","will":"否","gain":"大","lens":"金钱","who":"学生,体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq29-12","b":"social","s":29,"n":12,"t":"在企业里收回扣，也是受贿：现在和公职人员同一标准","p":"采购拿供应商的回扣、销售给客户经办人「返点」、HR 收应聘者的「感谢费」、工程负责人收分包商的好处，在民营企业同样是犯罪：公司、企业的工作人员利用职务便利，索取或者收受他人财物，为他人谋取利益，数额较大的，构成非国家工作人员受贿罪；…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"生意"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq29-13","b":"social","s":29,"n":13,"t":"虚报报销、截留货款、私收客户的钱：职务侵占","p":"用假发票报销、把私人消费混进差旅费、收了客户的货款不入账、虚报加班费和人头费，单笔看起来不多，累计起来就可能触犯刑法。公司、企业的工作人员利用职务便利，将本单位财物非法占为己有，数额较大的，构成职务侵占罪；2026 年 5 月 1 日起，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"新人,生意"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq29-14","b":"social","s":29,"n":14,"t":"「先借公司的钱周转一下」：挪用资金同样是犯罪","p":"出纳、财务、管钱的业务人员，最容易遇到这种诱惑：先把公司账上的钱拿出来炒股、还信用卡、借给朋友，过几天再补回去。法律规定，利用职务便利挪用本单位资金归个人使用或者借贷给他人，数额较大、超过三个月未还的，…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"生意"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq29-15","b":"social","s":29,"n":15,"t":"把公司的生意交给亲友做：民营企业也可能构成犯罪","p":"手握采购权、业务分配权的人，把公司的盈利业务交给自己亲友经营，以明显高于市场的价格从亲友的公司采购，或者以明显低于市场的价格卖给亲友的公司，过去主要追究国有企业人员。…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"管理,生意"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq29-16","b":"social","s":29,"n":16,"t":"收到推不掉的礼：及时退还或上交，并留下记录","p":"有时候礼物是硬塞的：放下就走、快递寄到家、夹在文件里。发现后不要拖，尽快原物退还，并保留退还的记录（快递单、聊天记录、转账退回凭证）；实在退不了的，按单位规定登记上交到纪检、合规部门。按照司法解释，收受请托人财物后及时退还或者上交的，…","tip":"「东西我已经让快递原样退回了，单号是 SF123……，请您查收。以后真的不用这样。」","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq29-17","b":"social","s":29,"n":17,"t":"在职时帮忙，离职后收钱，同样是受贿","p":"有人想得很「周到」：现在帮你办事不收钱，等我退休或离职了，你再给我安排个顾问、送点股份。司法实践中，国家工作人员利用职务上的便利为请托人谋取利益之前或者之后，约定在其离职后收受请托人财物，并在离职后收受的，以受贿论处。…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"体制内"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq29-18","b":"social","s":29,"n":18,"t":"行贿记录会跟着企业和个人：「受贿行贿一起查」","p":"过去有人觉得行贿的一方「顶多是个证人」。现在的政策是受贿行贿一起查：对多次行贿、巨额行贿以及向多人行贿的，重点查处；行贿人可能被纳入行贿人信息库，在招投标、政府采购、资质审批等方面受到限制。一次行贿，…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"生意"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq29-19","b":"social","s":29,"n":19,"t":"想举报：通过纪检监察的正式渠道，实名举报受保护","p":"遇到公职人员索贿、受贿、利用职权谋私的，可以向纪检监察机关举报：拨打 12388，登录中央纪委国家监委网站或者各地纪委监委网站的举报平台，或者写信、当面举报。举报时写清被举报人的姓名单位、具体事实、时间地点和证据线索。…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq29-20","b":"social","s":29,"n":20,"t":"和公职人员打交道：「亲」而有度，「清」而不疏","p":"做生意免不了和政府部门打交道。健康的关系是：有困难，通过正式渠道反映，政府部门帮助解决；政策不清楚，去问、去咨询；有意见，在座谈会、听证会上提。不搞私下的宴请送礼，不找「特殊关系」，不让官员给你的企业「站台」谋私利。交往可以坦荡真诚，…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"关系","who":"生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq29-21","b":"social","s":29,"n":21,"t":"听到「行业惯例」「大家都这么做」，先停一下","p":"很多人卷进贿赂和利益输送，不是因为贪，而是因为被一句话说服了：「这是行业惯例」「前任都是这么做的」「不给的话项目肯定拿不到」「这点钱不算什么」。这类话术的共同点，是把违法的事说成正常的事，把个人的风险说成集体的习惯。听到它们，…","tip":"「这块我们公司有明确的合规要求，我做不了主。按正常流程走，结果怎样我都接受。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"新人,生意"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq29-22","b":"social","s":29,"n":22,"t":"底线清楚，人情才能长久","p":"把这一章浓缩成一句话：凡是需要偷偷摸摸给的、凡是对方因为你的职位才给的、凡是不敢写进合同和账本的，都不要碰。真正的人情，是我遇到难处时你拉我一把，你遇到喜事时我真心祝贺，它不需要用来交换权力。守住这条底线，你可能会失去一些机会，…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq30-1","b":"social","s":30,"n":1,"t":"识别操控的共同信号：怀疑自己、被孤立、忽冷忽热、不敢说不","p":"操控常常发生在亲密关系、职场、家庭和「圈子」里，形式不同，信号却很相似：你越来越经常怀疑自己的记忆和判断；对方有意无意地让你和朋友家人疏远；对方一会儿对你极好，一会儿冷落你，你总在讨好、等待他「变好」；你害怕他生气，不敢表达不同意见，…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-2","b":"social","s":30,"n":2,"t":"PUA 的常见路径：先捧高，再打压，后控制，最后榨取","p":"网络上说的「PUA」，在恋爱中常常呈现这样的过程：一开始猛烈追求、甜言蜜语，让你觉得遇到了真爱；接着开始挑剔、贬低，说你「不够好」「没有人会像我这样包容你」；然后限制你的社交、要求你随时报备、查看你的手机；最后提出越来越过分的要求，…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"自保","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-3","b":"social","s":30,"n":3,"t":"煤气灯效应：对方不断否认你的记忆和感受","p":"「我从来没说过这话，是你记错了」「你太敏感了」「你是不是有病」，当这类话反复出现，你开始真的觉得是自己的问题，这就是常说的「煤气灯效应」。社会学研究指出，它往往建立在关系中的权力不平等之上，让受害者逐渐丧失对现实的判断。…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-4","b":"social","s":30,"n":4,"t":"情感勒索：用恐惧、义务和愧疚逼你就范","p":"「你要是走了，我就不活了」「我为你付出了这么多，你就这样报答我？」「你不答应，就是不爱这个家」，这类话的共同点，是让你因为害怕、觉得「应该」、心生愧疚而放弃自己的判断。应对的办法是把「请求」和「情绪」分开：先不急着答应，…","tip":"「我知道你很失望，但这件事我想清楚了，答案还是不行。我们可以聊别的办法。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-5","b":"social","s":30,"n":5,"t":"道德绑架：「你不帮就是不仁义」，可以不接这个框","p":"「你那么有钱，借我点怎么了」「都是亲戚，你不帮谁帮」「大家都捐了，就你不捐」，道德绑架的套路，是把一个可以商量的请求，包装成一道「你不答应就是坏人」的考题。你可以不接受这个前提：帮与不帮，是你的选择，不是你的义务。…","tip":"「我理解你的难处，但这件事我帮不上。这和我们的关系好不好没有关系。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq30-6","b":"social","s":30,"n":6,"t":"职场 PUA：否定一切、制造恐惧、让你觉得离开就活不下去","p":"严格的领导不等于职场 PUA。区别在于：严格的领导批评你的工作，给出标准和改进方向；PUA 式的领导否定你这个人，「你这种水平出去根本找不到工作」「我是看你可怜才留你」，同时不断加码要求、画饼、让你孤立无援。遇到后者，不要内化那些贬低；…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq30-7","b":"social","s":30,"n":7,"t":"想从操控中脱身：记事实、找外援、定边界，必要时彻底离开","p":"离开一段操控关系，往往比想象中难，因为你已经被训练得习惯讨好、害怕冲突。可以分几步走：第一，把对方的言行记录下来，帮助自己看清模式；第二，重新联系被疏远的朋友和家人，把情况告诉至少一个人；第三，设定具体的边界，比如「不再接受查手机」；第四，…","tip":"","cost":{"money":"少","time":"中","will":"是","gain":"大","lens":"自保","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq30-8","b":"social","s":30,"n":8,"t":"长期精神折磨不只是「感情问题」，严重的可能构成犯罪","p":"很多人以为只有动手打人才算家暴。其实法律所说的家庭暴力，包括以经常性谩骂、恐吓等方式实施的精神侵害。对共同生活的家庭成员长期打骂、冻饿、限制自由、精神折磨，情节恶劣的，构成虐待罪；致使被害人重伤、死亡的，处罚更重。司法实践中，…","tip":"","cost":{"money":"0","time":"中","will":"是","gain":"大","lens":"自保","who":"婚恋"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq30-9","b":"social","s":30,"n":9,"t":"销售里的心理套路：送你小礼物、限时限量、「大家都买了」","p":"心理学家总结过几种常见的说服手段：先给你一点免费的好处，让你觉得欠了人情（互惠）；告诉你「只剩最后三个名额」「今天不买就涨价」（稀缺）；安排一屋子人抢着下单（从众）；请穿白大褂的「专家」站台（权威）。这些手段本身不一定违法，…","tip":"「东西我先不要了，谢谢你的小礼物，我回去想想。」","cost":{"money":"多","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-10","b":"social","s":30,"n":10,"t":"免费体检、免费旅游、讲座送鸡蛋：针对老人的会销陷阱","p":"针对老年人的骗局，往往从「免费」开始：免费领鸡蛋、免费体检、免费旅游、免费听健康讲座。几次下来，「小王」「小李」叫爸叫妈、嘘寒问暖，老人放下戒心，然后被推销天价保健品、「包治百病」的理疗仪、「以房养老」「养老公寓」投资项目。…","tip":"（对父母）「妈，那些天天送东西、叫您妈的年轻人，图的是您的退休金。买什么之前跟我说一声，我帮您查查。」","cost":{"money":"多","time":"少","will":"些","gain":"大","lens":"金钱","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-11","b":"social","s":30,"n":11,"t":"识别传销：交钱入门、拉人头、按层级拿钱","p":"不管叫「连锁经营」「消费返利」「资本运作」还是「互助平台」，只要有这三个特征，就要高度警惕：要交一笔钱或者买一批产品才能取得资格；收入主要来自你发展了多少下线，而不是卖出了多少真实产品；人员按顺序形成层级，上线从下线的业绩里提成。…","tip":"「这种要交钱拉人的项目，我一律不参加，你也小心点。」","cost":{"money":"多","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq30-12","b":"social","s":30,"n":12,"t":"识别非法集资：没牌照、到处宣传、许诺高回报、面向所有人","p":"非法集资的核心，是未经国家金融管理部门许可，以许诺还本付息或者其他投资回报的方式，向不特定的人吸收资金。常见的包装有：养老项目、私募基金、虚拟货币、农业合作社、「原始股」、消费返利、融资租赁。…","tip":"","cost":{"money":"多","time":"少","will":"些","gain":"大","lens":"金钱","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq30-13","b":"social","s":30,"n":13,"t":"反诈的四条底线：来电不轻信，链接不乱点，信息不外泄，转账先核实","p":"电信网络诈骗的花样每年都在变，但几乎所有骗局最后都落在一个动作上：让你转账，或者让你提供验证码、密码、银行卡信息。记住四条：陌生来电、短信，不管对方说自己是谁，都不轻信；陌生链接、二维码、App，不点、不扫、不下载；…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-14","b":"social","s":30,"n":14,"t":"「我是公安局的，你涉嫌洗钱」：公检法不会让你转账到「安全账户」","p":"骗子冒充公安、检察院、法院，说你的身份证被盗用、涉嫌洗钱或者贩毒，发来带着你照片的「通缉令」，要求你对谁都保密，配合「资金清查」，把钱转到所谓的「安全账户」。记住：公检法机关不会通过电话、微信、QQ 办案，不会发「电子通缉令」，…","tip":"","cost":{"money":"多","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-15","b":"social","s":30,"n":15,"t":"刷单返利：先给甜头，后收大网","p":"「在家兼职，点赞关注就能赚钱」「垫付货款，返还本金加佣金」，刷单类诈骗的剧本几乎都一样：前几单真的返钱，让你尝到甜头；然后要求做「联单」「大单」，金额越来越大；最后说你「操作失误」「账户冻结」，必须再交钱才能解冻，直到你被榨干。…","tip":"","cost":{"money":"多","time":"少","will":"些","gain":"大","lens":"金钱","who":"学生"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq30-16","b":"social","s":30,"n":16,"t":"「杀猪盘」：网上认识的完美对象，最后都会带你去投资","p":"在婚恋网站、社交软件、游戏里认识一个条件很好的人：长得好看、事业成功、温柔体贴，每天嘘寒问暖，却总有理由不视频、不见面。聊了一段时间，他不经意地透露自己在某个平台投资赚了很多钱，「带你一起赚」。你先小额投入，真的赚了还能提现，于是越投越多，…","tip":"「我不做任何投资，也不在别人推荐的平台上充钱。」","cost":{"money":"多","time":"少","will":"是","gain":"大","lens":"金钱","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-17","b":"social","s":30,"n":17,"t":"「注销校园贷」「退款理赔」「修复征信」：冒充客服的骗局","p":"「您上学时开通的校园贷账户需要注销，否则影响征信」「您买的商品有质量问题，我们给您三倍理赔」「花钱可以帮您删除逾期记录」，这类电话都是骗局，最后都会让你在各种借贷 App 上借钱「清空额度」，或者开屏幕共享、提供验证码。…","tip":"","cost":{"money":"多","time":"少","will":"否","gain":"大","lens":"金钱","who":"学生,新人"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq30-18","b":"social","s":30,"n":18,"t":"冒充领导、熟人加你微信借钱：打电话核实","p":"骗子用领导、老师、亲戚的头像和名字加你好友，说「我在开会不方便接电话」「帮我给一个朋友转一笔钱，回头还你」「孩子学校要交费，先帮我垫一下」。很多人碍于面子，不好意思打电话核实。记住：任何通过微信、QQ、短信提出的借钱、转账要求，…","tip":"「王总，我打您电话确认一下转账的事，您方便接一下吗？」","cost":{"money":"多","time":"少","will":"否","gain":"大","lens":"金钱","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-19","b":"social","s":30,"n":19,"t":"AI 换脸、拟声：视频里是熟人，也要换个渠道核实","p":"现在的技术可以用几秒钟的声音、几张照片合成出以假乱真的视频和语音。「妈，我出车祸了急需用钱」「我是你领导，视频里你也看到了，赶紧转账」，看到熟悉的脸、听到熟悉的声音，也不能立刻相信。凡是涉及钱的，挂断后用自己保存的号码回拨；…","tip":"（视频中）「你先挂了，我用你的手机号打给你。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"金钱","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-20","b":"social","s":30,"n":20,"t":"「荐股群」「内部消息」「稳赚不赔的平台」：虚假投资理财","p":"虚假投资理财是近年来造成损失最大的诈骗类型之一。套路是：拉你进一个「投资交流群」，群里的「老师」天天晒收益、讲行情，群友纷纷「感谢老师」（多数是托），然后推荐你在某个 App 或网站上投资，前期小额能提现，大额充值后就无法提现、平台关闭。…","tip":"","cost":{"money":"多","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-21","b":"social","s":30,"n":21,"t":"境外「高薪招聘」：小心被骗进诈骗园区","p":"「东南亚高薪招客服、打字员，月薪两三万，不要求学历，包机票」，这类招聘很可能是诱骗你去境外从事电信诈骗的陷阱。一旦过去，护照被收、人身自由被限制，甚至遭受暴力。去境外工作，一定要通过有资质的对外劳务合作企业，签正规合同，确认工作签证；…","tip":"","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"自保","who":"学生,新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-22","b":"social","s":30,"n":22,"t":"出租出借银行卡、帮人「跑分」取现：骗子的帮凶也要坐牢","p":"「把你的卡借我走一下流水，每次给你一百」「帮忙用你的账户收款再转出去」「去银行取个现金交给我」，这些都是在为诈骗、赌博团伙转移赃款。明知他人利用信息网络实施犯罪，仍提供支付结算等帮助，情节严重的，构成帮助信息网络犯罪活动罪；…","tip":"「我的卡只有我自己用，多少钱都不借。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"自保","who":"学生"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq30-23","b":"social","s":30,"n":23,"t":"发现被骗：马上报警、马上止付，当心「帮你追回损失」的二次诈骗","p":"被骗后最重要的是速度。第一时间拨打 110 或 96110 报警，说明转账的时间、金额、对方账户；同时联系银行或支付平台，询问能否紧急止付、冻结；保存好聊天记录、转账凭证、对方账号、网址和 App 安装包，不要删除。…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"金钱","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq30-24","b":"social","s":30,"n":24,"t":"帮家里的老人和孩子防骗：装反诈 App，设限额，常聊天","p":"骗子最喜欢找信息不灵通、缺少陪伴的老人和涉世未深的孩子。可以帮他们做几件事：手机上安装「国家反诈中心」App 并开启来电预警；在手机银行里设置单日转账限额；开通银行的「亲情账户」或大额转账提醒；教会他们「凡是要转账，先给我打电话」。…","tip":"（对父母）「以后谁让您转账，不管说得多急，您都先给我打个电话，我们一起看看。」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"金钱","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq31-1","b":"social","s":31,"n":1,"t":"学生时代：真诚交几个朋友，比混进很多圈子重要","p":"学生时代的友谊，往往是一生中最纯粹的关系，没有太多利益掺杂。不必刻意经营「人脉」，也不必为了合群勉强自己。找几个三观相近、能一起成长的朋友，在别人需要时帮一把；和室友相处，作息、卫生、费用这些小事提前说清楚；对老师有礼貌，有问题主动请教。…","tip":"","cost":{"money":"0","time":"中","will":"否","gain":"大","lens":"关系","who":"学生"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq31-2","b":"social","s":31,"n":2,"t":"请老师写推荐信、帮忙内推：提前开口，备好材料，事后反馈","p":"请导师、老师写推荐信，至少提前两到三周，附上你的简历、申请的项目或岗位、截止日期，以及希望老师重点写的几件事，最好附一份草稿供参考。请学长学姐内推，先自己研究清楚岗位，再简洁地说明你为什么合适。无论结果如何，事后都告诉对方一声，…","tip":"「王老师，我想申请某某大学的硕士项目，截止日期是 12 月 15 日。附件是我的简历和个人陈述，如果您方便的话，能否请您为我写一封推荐信？」","cost":{"money":"0","time":"少","will":"否","gain":"大","lens":"关系","who":"学生"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq31-3","b":"social","s":31,"n":3,"t":"刚工作的头三年：先立住「靠谱」两个字","p":"职场新人最大的资本不是聪明，而是可靠：交代的事有回音，答应的事按时做，犯了错敢承认，不懂的地方主动问。这个阶段，也是建立职业口碑的关键时期，你在第一份工作里的表现，会通过前领导、前同事传到很多地方。同时要守住自己的法定权利，…","tip":"","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"关系","who":"新人"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-4","b":"social","s":31,"n":4,"t":"谈恋爱以后：开始学习和对方的家庭打交道","p":"恋爱稳定以后，人情世故的范围就扩大了：节日要不要问候对方父母、见家长带什么、对方家里有事要不要出面。原则是：由伴侣做「引路人」，先问清楚对方家里的习惯；主动但不越界，问候到了，但不急着插手对方的家事；两个人之间的矛盾，不拉双方父母进来评理。","tip":"","cost":{"money":"少","time":"少","will":"些","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-5","b":"social","s":31,"n":5,"t":"结婚成家：两个人先站在一起，再面对两个家庭","p":"结婚以后，最重要的人际关系是夫妻关系。和双方父母的相处、过年去谁家、给双方父母多少钱、人情往来怎么随，夫妻先私下商量好，再一起对外。各自的父母由各自去沟通，不在父母面前指责伴侣，也不让伴侣去和你的父母「硬碰硬」。婚后的人情账，…","tip":"","cost":{"money":"多","time":"中","will":"是","gain":"大","lens":"关系","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-6","b":"social","s":31,"n":6,"t":"自家添了孩子：报喜不「催礼」，收了礼记得回礼和道谢","p":"孩子出生后，在家族群、朋友圈报个喜，发一张照片、说一句母子平安就够了，不必一个个私信通知，更不要群发收款码，那会让人觉得是在「要份子」。不方便接待探望的，直接说「等满月后再聚」。收到红包和礼物的，用小本子或表格记下来，…","tip":"「谢谢大家的祝福！宝宝和妈妈都挺好，这段时间先让她好好休息，满月后请大家吃饭。」","cost":{"money":"少","time":"少","will":"否","gain":"中","lens":"关系","who":"婚恋,父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-7","b":"social","s":31,"n":7,"t":"有了孩子：给孩子做个懂礼貌、有边界的榜样","p":"孩子学人情世故，不是听你讲道理，而是看你怎么做：你怎么对待服务员、怎么和邻居打招呼、怎么拒绝别人、怎么跟伴侣吵架又和好。教孩子说「请」「谢谢」「对不起」，也教孩子说「不」：不想被亲戚抱、不想表演节目，可以拒绝；身体的隐私部位，…","tip":"（亲戚要孩子表演时）「孩子今天不太想表演，我们下次再说，来，先吃饭。」","cost":{"money":"0","time":"中","will":"些","gain":"大","lens":"关系","who":"父母"},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-8","b":"social","s":31,"n":8,"t":"人到中年：人情做减法，把时间留给真正重要的人","p":"中年以后，时间和精力都有限：上有老、下有小，工作压力最大。可以有意识地给人情往来做减法：那些只在需要你时才出现的人、每次见面都让你很累的饭局、纯粹出于面子的应酬，可以慢慢退出。把省下来的时间，留给家人、几个老朋友和自己的身体。研究也发现，…","tip":"","cost":{"money":"少","time":"少","will":"是","gain":"大","lens":"关系","who":""},"grade":"B","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-9","b":"social","s":31,"n":9,"t":"父母老了：常回家、常打电话，大事一起商量","p":"父母需要的，往往不只是钱，还有陪伴和被尊重。分开住的，经常打电话、视频，定期回家看看；父母的身体、财产、住在哪里、要不要请护工这类大事，兄弟姐妹之间商量好分工，并尊重父母本人的意愿。法律也规定，家庭成员应当关心老年人的精神需求，…","tip":"","cost":{"money":"多","time":"中","will":"些","gain":"大","lens":"关系","who":"父母"},"grade":"A","disputed":false,"ev":"法条","hasRef":true},{"id":"rq31-10","b":"social","s":31,"n":10,"t":"去医院探病：先问方不方便，少待、少问、多听","p":"探病前先问家属，病人方不方便、什么时间合适，避开治疗、休息和饭点；手术后、重症期间，病人往往不想见太多人。去了待十几二十分钟就走，说话轻声，不在病房里打电话。不追问病情细节和花了多少钱，不讲「我认识一个人也是这个病，后来……」的故事，…","tip":"「看你气色还不错，安心养着，单位的事别操心。我就不多打扰了，有事随时叫我。」","cost":{"money":"少","time":"少","will":"否","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-11","b":"social","s":31,"n":11,"t":"亲友得了重病：实际的帮助，比一句「加油」有用","p":"面对重病的亲友，很多人不知道该说什么，于是干脆不联系。其实不需要说得多好，具体的帮忙最实在：帮忙查资料、联系医院、陪着去复查、给家属送一顿饭、帮忙照看孩子。与其说「有什么需要随时找我」，不如直接说「周六我有空，我陪阿姨去医院复查吧」。…","tip":"「我这周三下午有空，可以帮你去医院拿报告，你看行吗？」","cost":{"money":"少","time":"中","will":"些","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq31-12","b":"social","s":31,"n":12,"t":"有了一定地位以后：越要谨慎，越要记得低处的人","p":"职位升了、事业成了，身边会突然多出很多「朋友」，说好话的人越来越多，说真话的人越来越少。这时候更要清醒：不轻易答应别人的请托，不在饭局上许诺；对过去帮过你的人、对普通的工作人员，态度保持不变；身边要留一两个敢说你不对的老朋友。…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"大","lens":"体面","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-13","b":"social","s":31,"n":13,"t":"人生低谷时：别切断所有联系，开口求助不丢人","p":"失业、生病、离婚、创业失败，很多人第一反应是躲起来，不回消息、不参加聚会，觉得「混成这样没脸见人」。可越是这种时候，越需要别人的支持和信息。挑几个信得过的人，坦白地说出你的处境和具体需要：帮忙留意工作机会、推荐一位医生、陪你吃顿饭。…","tip":"「我最近工作没了，正在找新的机会。你那边要是听说有合适的岗位，帮我留意一下，谢谢。」","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq31-14","b":"social","s":31,"n":14,"t":"离婚以后面对亲友：一句话说明，不诉苦，不让别人站队","p":"离婚后，亲戚、同事、共同的朋友难免会问起。不必每个人都解释来龙去脉，一句「我们已经分开了，现在都挺好的」就够了；不在饭桌上、朋友圈里数落对方，那些话传来传去，最后伤的是自己的体面和孩子。共同的朋友，让他们自己决定和谁来往，…","tip":"「我们已经和平分开了，现在各自都挺好，谢谢关心。」","cost":{"money":"0","time":"少","will":"是","gain":"中","lens":"体面","who":"婚恋"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-15","b":"social","s":31,"n":15,"t":"重组家庭：称呼不强求，规矩慢慢立，财产提前说清楚","p":"再婚后，孩子要不要改口叫「爸爸」「妈妈」，不要勉强，让孩子按自己的节奏来；管教孩子的事，初期主要由亲生父母出面，继父母先做朋友。双方各自的婚前财产、给各自子女的安排，最好在婚前签好书面协议，避免日后的纠纷。法律规定，…","tip":"","cost":{"money":"多","time":"多","will":"是","gain":"大","lens":"关系","who":"婚恋,父母"},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-16","b":"social","s":31,"n":16,"t":"临近退休：交接好工作，体面退场，不干预继任者","p":"退休前几个月，把手上的工作、资料、人脉梳理清楚，交给接班的人；退休后，老同事请教可以帮忙，但不要主动干预继任者的决定，更不要在背后评价「他不如我当年」。原来围在身边的人变少了，是正常现象，别往心里去。提前培养一些工作之外的兴趣和朋友圈，…","tip":"","cost":{"money":"0","time":"少","will":"些","gain":"中","lens":"体面","who":"管理"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-17","b":"social","s":31,"n":17,"t":"帮子女带孙辈：帮忙不越位，教育以孩子父母为主","p":"老人帮忙带孩子，是很大的付出，但也容易产生矛盾：喂饭、穿衣、看手机、要不要打骂，两代人的观念常常不同。做长辈的，可以提建议，但最终听孩子父母的；做子女的，要感谢父母的付出，有分歧私下温和地沟通，不当着孩子的面争执。…","tip":"（子女对父母）「妈，您带孩子太辛苦了。吃糖这件事我们想控制一下，您帮我们盯着点，有什么不方便的跟我说。」","cost":{"money":"少","time":"多","will":"是","gain":"大","lens":"关系","who":"父母"},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false},{"id":"rq31-18","b":"social","s":31,"n":18,"t":"老年再婚：子女不能干涉，财产可以事先约定","p":"父母丧偶或离异后想再婚，子女的担心常常集中在财产上。法律明确规定，老年人的婚姻自由受法律保护，子女或者其他亲属不得干涉；赡养义务也不因老人的婚姻关系变化而消除。比较好的做法是：老人在再婚前和对方、和子女一起把财产的事说清楚，…","tip":"","cost":{"money":"少","time":"少","will":"是","gain":"中","lens":"自保","who":"父母"},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq31-19","b":"social","s":31,"n":19,"t":"提前安排身后事：意定监护、遗嘱，是给家人的体贴","p":"很多家庭的矛盾，发生在老人失能或去世之后：谁来照顾、谁来做医疗决定、财产怎么分。成年人可以在意识清醒时，以书面形式确定自己的监护人，将来丧失行为能力时由其履行监护职责，这叫意定监护。…","tip":"","cost":{"money":"少","time":"少","will":"些","gain":"大","lens":"自保","who":""},"grade":"A","disputed":false,"ev":"法条","hasRef":false},{"id":"rq31-20","b":"social","s":31,"n":20,"t":"父母过世后分遗产：先商量，留书面协议，别为钱伤了手足","p":"没有遗嘱的，遗产按法定顺序继承：第一顺序是配偶、子女、父母，同一顺序的继承人一般均等分配，对被继承人尽了主要扶养义务的、生活特别困难的，可以多分或者照顾。法律提倡继承人本着互谅互让、和睦团结的精神协商处理，协商不成可以调解或起诉。…","tip":"「爸妈辛苦一辈子，我们别为这个吵。按法律的份额，老三照顾得最多，多分一些，大家看行吗？」","cost":{"money":"多","time":"中","will":"是","gain":"大","lens":"关系","who":""},"grade":"A","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-21","b":"social","s":31,"n":21,"t":"人情往来随年龄调整：年轻时广结善缘，年长后看重情分","p":"二三十岁，可以多参加聚会、多认识人，人情往来稍多一点，是在为未来积累；四五十岁，家庭和身体需要更多精力，随礼的范围、应酬的次数可以主动收缩；六七十岁，老朋友一个个少了，更要珍惜身边的人，也接受子女和晚辈的照顾。每个阶段，问问自己：这份人情，…","tip":"","cost":{"money":"少","time":"少","will":"些","gain":"中","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":true},{"id":"rq31-22","b":"social","s":31,"n":22,"t":"知世故而不世故：一辈子的人情，归结为真诚、分寸和底线","p":"读到这里，你会发现，这本书里的大部分条目都可以归结为三件事。真诚：说真话，办实事，记得别人的好。分寸：给别人留面子，也给自己留余地，知道什么时候该进、什么时候该退。底线：不违法，不害人，不让人情压过良心和规则。懂得人情世故，…","tip":"","cost":{"money":"0","time":"少","will":"是","gain":"大","lens":"关系","who":""},"grade":"C","disputed":false,"ev":"经验共识","hasRef":false}];
